window.__D("text/torat-shmuel/c052",{"p":[[2000480533,"מפתח לגאולתן של בנים פי' מפתח היינו מפתח לפתח, אמר הקב\"ה אתה אמרת והי' ה' לי לאלקים פי' אלקים היינו כח הפועל בנפעל<sup data-n=\"5687\">128</sup> ואצלו הי' ה' בחי' אלקים כי הנה כתי' חלקי ה' אמרה נפשי<sup data-n=\"5688\">129</sup> כמו כי חלק ה' עמו<sup data-n=\"5689\">130</sup> היינו בכלל כן חלקי ה' אמרה נפשי היינו בפרט שכל א' יש לו שם ה'<sup data-n=\"5690\">131</sup>, פי' שם ה' בקיצור, ו\"ה היינו תורה ותפלה וה' ראשונה היא בחי' התבוננות ויו\"ד עם הקוצש\"י הוא בחי' עם קשה עורף<sup data-n=\"5691\">132</sup> הוא ביטול שלמעלה מן הטעו\"ד, וכל א' יש לו בחי' זו, וכאשר מברר ומגיע לבחי' זו אז אצלו ה' בבחי' אלקים כן יעקב אמר והי' ה' לי לאלקים כמ\"ש עם לבן גרתי<sup data-n=\"5692\">133</sup> פי' גרתי גימט' תרי\"ג<sup data-n=\"5693\">134</sup> מצות שקיים<sup data-n=\"5694\">137</sup> כל תרי\"ג<sup data-n=\"5695\">135</sup> מצות<sup data-n=\"5696\">136</sup> ע\"כ הי' אצלו ה' בחי' אלקים כו'. וזהו מי אל כמוך נושא עון ועובר על פשע לשארית נחלתו למי שמשים א\"ע כשיריים<sup data-n=\"5697\">138</sup> כמו למשל שיריים ממאכל שהמאכל הולך אצלו בפנימי' והמותר נשאר כן מה שאפשר שיומשך בפנימי' נמשך בפנימי' והמותר נשאר, בבחי' מקיף, וע\"י שמשים א\"ע כשריים אז מגיע לבחי' מקיף, ומהו\"ע המקיף ית' להלן.\n<b>וזהו</b> אתה אמרת והי' ה' לי לאלקים חייך כל טובות וברכות ונחמות שאני נותן לבניך איני נותן אלא בלשון הזה שנא' והי' ביום ההוא יצאו מים חיים מירושלים אל הים הקדמוני<sup data-n=\"5698\">139</sup>, פי' ירושלים היינו יראה שלם<sup data-n=\"5699\">140</sup> שלימות היראה<sup data-n=\"5700\">141</sup> וים הקדמוני היינו בחי' מקדם אשר לא נעשה<sup data-n=\"5701\">142</sup>, פי' נעשה היינו בסדר השתלשלות ומקדם אשר לא נעשה למעלה מסדר השתלשלות, וביום ההוא יצאו מירושלים אל הים הקדמוני שירושלים ישפיע אל הים הקדמוני, והי' ביום ההוא יוסיף ה' שנית ידו פי' יוסיף היינו תוס' ברכה, ושנית ידו היינו עוד תוס' ברכה יותר, והי' ביום ההוא",[["5687","128","<b>אלקים היינו כח הפועל בנפעל</b>: ראה גם לקו\"ת בחוקותי מט, ב. מאמרי אדה\"ז תקס\"ז ע' רי. ש\"א לו, א. פח, ב. פט, ב."],["5688","129","<b>חלקי ה' אמרה נפשי</b>: איכה ג, כד."],["5689","130","<b>כי חלק ה' עמו</b>: האזינו לב, ט."],["5690","131","<b>שכל א' יש לו שם ה'</b>: ראה גם (לעיל בחלק המאמרים) המשך יונתי פ\"ה. לעיל ח\"א (בחלק המאמרים) מאמר ד\"ה ואעשך לגוי גדול הערה 26."],["5691","132","<b>עם קשה עורף</b>: תשא לד, ט. ראה גם המשך יונתי שם."],["5692","133","<b>עם לבן גרתי</b>: וישלח לב, ה."],["5693","134","<b>גרתי גימט' תרי\"ג</b>: רש\"י שם. בראשית רבתי לר' משה הדרשן שם."],["5694","137","<b>שקיים כל תרי\"ג מצות</b>: ראה הל' ת\"ת לאדה\"ז פ\"א, ה\"ד. תו\"ח בשלח קעה, ד ובהערה 542."],["5695","135","<b>תרי\"ג מצות</b>: ראה מכות כג, סע\"ב. כללי המצות לר\"י גיקטיליא מערכת שש מאות [צפת תשנ\"ב ע' 208]. לקו\"ש יתרו כרך כו ס\"ע 424 ואילך. אג\"ק שלו ח\"ג ע' רג."],["5696","136","<b>שקיים כל תרי\"ג מצות</b>: ראה בעה\"ט וישלח שם. לעיל הערה 134."],["5697","138","<b>מי אל כמוך. . לשארית נחלתו למי שמשים א\"ע כשיריים</b>: מיכה ז, יח. ר\"ה יז, ריש ע\"ב."],["5698","139","<b>אל הים הקדמוני</b>: המשך הכתוב [בדילוג] והי' ביום ההוא — זכרי' יד, ח. חלק זה מהכתוב לא הובא לעיל במדרש (שבריש המאמר). אבל הובא בהנחה שני' שם בריש המאמר — ראה בהנחה שני' שם הערה 10."],["5699","140","<b>ירושלים היינו יראה שלם</b>: ראה תוד\"ה הר תענית טז, א. ב\"ר פנ\"ו, י. לעיל ח\"א (בחלק המאמרים) המשך מצה זו ובהערה 1139."],["5700","141","<b>ירושלים היינו. . שלימות היראה</b>: ראה לקו\"ת ר\"ה ס, ב. פ' ראה כט, ד. ל, רע\"ג. שה\"ש ו, ג. ז, סע\"ב. לעיל שם ובהערה 1140."],["5701","142","<b>מקדם אשר לא נעשה</b>: ע\"פ ישעי' מו, י."]]],[2000480534,"יטפו ההרים עסיס היינו ברכה והמשכה, והי' ביום ההוא יתקע בשופר גדול כדי שיהי' ובאו האובדים בארץ אשור והנדחים בארץ מצרים והשתחוו להר ה'<sup data-n=\"5702\">143</sup> הי' צריך לזה שופר גדול<sup data-n=\"5703\">144</sup>, פי' אשור היינו תענוגים<sup data-n=\"5704\">145</sup> שיש תענוג ממאכל שערב לחיך, ויש תענוג של כבוד ותענוג מלבושים, וזהו האובדים בארץ אשור שזהו פועל טמטום המוח, כי האובדים בארץ אשור היינו טמטום המוח שא\"א להתבונן כלל, והנדחים בארץ מצרים היינו טמטום הלב<sup data-n=\"5705\">146</sup> שהגם שמתבונן במוח מ\"מ אינו נמשך בלב כמארז\"ל חמרא דפרגוסא ומיא דיומסס קיפחא עשרת השבטים שהי' להם לקרוא<sup data-n=\"5706\">148</sup> החדש הזה לכם<sup data-n=\"5707\">149</sup> פי' שזה יהי' לכם וקראו החרש הי' לבם<sup data-n=\"5708\">147</sup> מפני שטמטמו אצלם את לבם, וזהו\"ע טמטום הלב הגם שמתבונן במוח מ\"מ אינו נמשך בלב. ובד\"כ יש ג' שרי פרעה קנה ושט ורידין<sup data-n=\"5709\">150</sup>, קנה ושט היינו תאוות אכילה ושתי' ורידין היינו רתיחת הדמים שבהבלי עוה\"ז שזהו מיצר הגרון שמונע ומעכב שלא יומשך ממוח בלב. וכדי שיבואו האובדים בארץ אשור והנדחים בארץ מצרים להשתחוו<sup data-n=\"5710\">151</sup> בהר ה' שענין השתחוואה היינו בפישוט ידים ורגלים<sup data-n=\"5711\">152</sup> בבחי' ביטול צריך לזה שופר גדול ע\"כ ביום ההוא יתקע בשופר גדול דוקא. וזהו שארז\"ל הרואה שופר בחלום יצפה לישועה כמ\"ש והי' ביום ההוא יתקע בשופר גדול, כי ענין החלום הוא בעת השינה, ושינה הו\"ע שופר תשובה החזרת הנפש, ורואה בחלום שופר זהו שופר בכופל א\"כ זהו כמו שופר גדול ע\"כ יצפה לישועה והי' ביום ההוא יתקע בשופר גדול.\n<b>עפ\"ז</b> יובן מ\"ש בילקוט שמאיל של יצחק לא יצא דבר לבטלה כי האפר של איל הוא יסוד של מזבח הפנימי כמ\"ש שמן וקטורת ישמח לב<sup data-n=\"5712\">153</sup>, כי על מזבח החיצון הקריבו פרים ואילים וכבשים היינו הקרבת חלב ודם חלב הו\"ע תענוג ודם הו\"ע רתיחת הדמים אבל על מזבח הפנימי' הי' הקטרת הקטורת שהו\"ע בחד קטיר אתקטרנא בי' אחידא<sup data-n=\"5713\">154</sup> כו' והו\"ע אפר של מזבח הפנימי' כו', והגידים של איל של יצחק",[["5702","143","<b>ובאו האובדים. . והשתחוו להר ה'</b>: המשך הכתוב והי' ביום ההוא יתקע בשופר גדול — ישעי' כז, יג [ושם: והשתחוו לה' בהר]."],["5703","144","<b>צריך לזה שופר גדול</b>: ראה לקו\"ת שבהערה הבאה."],["5704","145","<b>אשור היינו תענוגים</b>: ראה לקו\"ת ר\"ה ס, א. עטרת ראש שער ר\"ה ע' 52. אוה\"ת ר\"ה כרך ה ע' ב'פה."],["5705","146","<b>טמטום המוח. . טמטום הלב</b>: ראה יומא לט, א. לעיל ח\"א (בחלק המאמרים) המשך זאת חנוכת המזבח ובהערה 343."],["5706","148","<b>שהי' להם לקרוא</b>: ראה לעיל הנחה ד\"ה אני לדודי הא' פיסקא אך כ\"ז. שבת שם."],["5707","149","<b>החודש הזה לכם</b>: בא יב, ב."],["5708","147","<b>חמרא דפרגוסא. . הי' לבם</b>: ראה שבת קמז, ב."],["5709","150","<b>ג' שרי פרעה קנה ושט ורידין</b>: ראה תו\"א ויחי קב, ג. לעיל ח\"א (בחלק המאמרים) המשך מצה זו ובהערה 271."],["5710","151","<b>להשתחוו</b>: אוצ\"ל: להשתחוות. או והשתחוו. ראה גם לעיל הערה 143."],["5711","152","<b>השתחוואה היינו בפישוט ידים ורגלים</b>: ברכות לד, ב. רמב\"ם הל' תפלה פ\"ה, הי\"ג. הל' ע\"ז פ\"ו, ה\"ו."],["5712","153","<b>שמן וקטורת ישמח לב</b>: משלי כז, ט."],["5713","154","<b>בחד קטיר. . אחידא</b>: ראה זהר אד\"ז האזינו רפח, א. רצב, א. מאמרי אדה\"א שמות ח\"ב ע' שכט. וש\"נ. תו\"ח לך צו, א ובהערה 3. שער האמונה צח, ב. סה\"מ מלוקט ג' ע' קנא ואילך."]]],[2000480535,"היינו עשרה כנורות של דו\"ד<sup data-n=\"5714\">155</sup> כי דוד הי' מרכבה לבחי' מל' ושרש המל' הוא ברדל\"א<sup data-n=\"5715\">156</sup> וע\"י שהי' מרכבה הי' בונה בנין המל' בפרצוף שלם עי\"ז הגיע לשרש בחי' רדל\"א כו', עורו של איל הי' אזור מתניו של אלי' כמ\"ש חגרה בעוז מתני', כאשר ידבק אזור עור במתניו כן ידבק אתכם אלי בניי<sup data-n=\"5716\">158</sup>, וענין מתני' היינו ענין אמונה<sup data-n=\"5717\">157</sup>, כי אלי' התקרבו<sup data-n=\"5718\">159</sup> אותם לאמונה מדוע אתם פוסחים על שתי הסעיפים אם ה' אלקים לכו אחריו ואם הבעל לכו אחריו<sup data-n=\"5719\">160</sup>, כי אפי' האדם כאשר עוסק במו\"מ צריך לכוון<sup data-n=\"5720\">161</sup> כדי שירויח ויהי' ביכולתו ללמוד ולהתפלל אבל כאשר עוסק בגשמיות ושוכח על הרוחני' היינו ג\"כ פוסח על שתי הסעיפים ואלי' קירב אותם לאמונה ע\"כ האזור שלו הי' מעור של איל של יצחק, ובשרש נמשך מנה\"י החדשים שנמשך ממ\"ה החדש שהוא ממצחא דא\"ק<sup data-n=\"5721\">162</sup>, והנה שרש האזור הוא מרשימו כידוע שהרשימו היינו מלפני הצמצום ולא נגע בה הצמצום<sup data-n=\"5722\">163</sup> ומשם שורש הלבושים<sup data-n=\"5723\">164</sup> ע\"כ אזור של אלי' הי' מרשימו כו', וקרנים של איל שמאלו שתקע בו בהר סיני כמ\"ש נטע<sup data-n=\"5724\">165</sup> שמאלו ברא ארץ<sup data-n=\"5725\">166</sup> שמ\"ת הי' בקרן שמאל וארז\"ל וכי מאי איכפת להקב\"ה אם ישחוט מן הצאוור או מן העורף אלא לא ניתנו המצות אלא כדי לצרף את הבריות<sup data-n=\"5726\">167</sup>, פי' בריות היינו הגוף ונה\"ב<sup data-n=\"5727\">168</sup> ועיקר המכוון של מ\"ת הי' בשביל זה כדי לברר הגוף ונה\"ב כו', וכ\"ז הוא המשכה מלמעלמ\"ט, אבל לע\"ל יהי' בקרן של ימין שהוא גדול משמאל כי לע\"ל יהי' מלמטלמ\"ע שהמטה יתעלה במקום המעלה, כי במ\"ת כתי' קול גדול ולא יסף<sup data-n=\"5728\">169</sup> שהי' השופר שופר קטן אבל הקול גדול וזהו המשכה פנימי' בחי' קול היינו המשכה<sup data-n=\"5729\">170</sup> פנימי' אבל לע\"ל יהי' קרן של ימין שגם החיצוני' יאיר ויתגלה ע\"כ יהי' שופר גדול כו'. ועפ\"ז יובן מה שנאחז בטליתו",[["5714","155","<b>עשרה כנורות של דו\"ד</b>: ראה גם לעיל ובהערה 25."],["5715","156","<b>ושרש המל' הוא ברדל\"א</b>: ראה לקו\"ת חוקת נח, ב (סוס\"ב) וכ\"מ בע\"ח שער א\"א פ\"ב. לעיל ח\"א (בחלק המאמרים) המשך מצה זו ובהערה 1704."],["5716","158","<b>כאשר ידבק. . אלי בניי</b>: ירמי' יג, יא [ושם: כאשר ידבק האזור אל מתני איש כן הדבקתי אלי את כל בית ישראל ואת כל בית יהודה]."],["5717","157","<b>חגרה בעוז מתני'. . אמונה</b>: משלי לא, יז. ראה אגה\"ק ס\"א."],["5718","159","<b>התקרבו</b>: בסמוך מובא קירב, ואולי גם כאן צ\"ל כן."],["5719","160","<b>מדוע אתם פוסחים. . אלקים. . אחריו</b>: מלכים-א יח, כא [ושם: עד מתי. . האלקים]."],["5720","161","<b>האדם. . במו\"מ צריך לכוון</b>: ראה שו\"ע אדה\"ז הל' מו\"מ סקנ\"ו, רס\"ב."],["5721","162","<b>ממ\"ה החדש שהוא ממצחא דא\"ק</b>: ראה ע\"ח שער שבה\"כ ש\"ט, פ\"ו. שער התיקון ש\"י, פ\"ב ופ\"ד."],["5722","163","<b>שהרשימו. . ולא נגע בה הצמצום</b>: ראה גם לעיל ח\"א (בחלק המאמרים) המשך מצה זו פ\"ו-ז."],["5723","164","<b>שהרשימו. . שורש הלבושים</b>: ראה גם לקמן הנחה ד\"ה כנשר יעיר קנו ובהערה 149."],["5724","165","<b>נטע</b>: אוצ\"ל: נטה."],["5725","166","<b>נטה שמאלו ברא ארץ</b>: ראה פדר\"א פי\"ח. הנסמן בתו\"א וארא נו, ב."],["5726","167","<b>וכי מה איכפת. . לצרף את הבריות</b>: ראה תנחומא שמיני ז-ח. ב\"ר רפמ\"ד. אוה\"ת שמיני ע' נב ואילך. המשך מים רבים תרל\"ו ע' קטו. סה\"מ תרל\"ח ע' מח ואילך. לקו\"ש אבות כרך יז ע' 415 הערה 53. שופטים כרך יט ע' 182 הערה 42."],["5727","168","<b>בריות. . הגוף ונה\"ב</b>: ראה המשך מים רבים תרל\"ו שם. (לעיל בחלק המאמרים) המשך יונתי ובהערה 204."],["5728","169","<b>קול גדול ולא יסף</b>: ואתחנן ה, יט."],["5729","170","<b>קול היינו המשכה</b>: ראה גם תו\"א וישב כז, ב. לעיל ח\"א (בחלק המאמרים) המשך מצה זו ובהערה 702."]]],[2000480536,"של א\"א, כי ענין עקידה היינו שעקד ע\"ג המזבח שעקד את יצחק הידים והרגלים עם הראש<sup data-n=\"5730\">171</sup> הכל ביחד כמו שעוקד הבהמה והוא הי' בחי' אדם א\"כ זהו אדם ובהמה תושיע ה'.\n<b>ועפי\"ז</b> יובן מה שנחשב לאברהם לנסיון<sup data-n=\"5731\">172</sup> ולא ליצחק ופי' המפרשים<sup data-n=\"5732\">173</sup> מפני כי יצחק הי' המס\"נ רק לפי שעה אבל באברהם שהוא הי' אצלו בן יחיד<sup data-n=\"5733\">174</sup> למאה שנים<sup data-n=\"5734\">175</sup> זהו נסיון גדול יותר שגם אח\"כ זהו נסיון וזהו נסיון עשירי<sup data-n=\"5735\">176</sup> כנגד עשר כחות הנפש<sup data-n=\"5736\">177</sup> וכדכתיב עתה ידעתי כי ירא אלקים אתה<sup data-n=\"5737\">178</sup>, מי העיר ממזרח צדק<sup data-n=\"5738\">179</sup> שהגיע לבחי' יר\"ע כו'. ועי\"ז האיל פשט את ידו ורגלו לטליתו של אברהם כי הנה מקיפים ופנימי' הגם שנמשך ע\"י המשכת הקו<sup data-n=\"5739\">180</sup> אך באמת בשרש מגיע בלפני הקו כי הנה כתי' נשמה שנתת בי טהורה היא<sup data-n=\"5740\">181</sup> אתה בראת אתה יצרת ואתה נפחת<sup data-n=\"5741\">182</sup>, בראת יצרת נפחת כנגד ג' עולמות בי\"ע<sup data-n=\"5742\">183</sup> וטהורה היא היינו מרשימו<sup data-n=\"5743\">184</sup> שלפני הצמצום שלא נגע בו הצמצום, מ\"מ הגם שלא נגע בה הצמצום מ\"מ זהו בעצם העלם כי רשימו הוא אותיות<sup data-n=\"5744\">185</sup> וכמו עד\"מ באותיות אנו רואים שהם מגלים השכל מ\"מ הם בעצם הוא העלם כך רשימו הגם שמגלה אור שלפני הצמצום מ\"מ זהו רק העלם, אבל במקיף שמעיגול הגדול שלפני הצמצום שם אינו שייך העלם",[["5730","171","<b>שעקד את יצחק הידים והרגלים עם הראש</b>: ראה שבת נד, א. רש\"י וירא כב, ט. לחם משנה להל' תמידין ומוספין פ\"א, ה\"י."],["5731","172","<b>לאברהם לנסיון</b>: לאחרי המאמר בא עמוד פנוי ושם נרשם (באותו כתב) בשולי העמוד:\nשמעתי מאיש א' ששמע מאדמו\"ר זצ\"ל נבג\"מ[ednref_335_ו] שזה שנמנה הנסיון לאברהם ולא ליצחק[ednref_336_ז] מפני כי יצחק הו\"ע גבורות ברשפי אש, שאש עולה למעלה, ע\"כ הי' בטבע ליכלל מלמטלמ\"ע, ע\"כ אינו נחשב לנסיון לפניו, אבל אברהם הוא בחי' חסד המשכה מלמעלמ\"ט, ע\"כ העקידה הי' לפניו נסיון גדול."],["5732","173","<b>ופי' המפרשים</b>: ראה גם (באו\"א) בחיי וירא כב, א. מאמרי אדה\"ז על פרשיות התורה ח\"א ע' קכח."],["5733","174","<b>בן יחיד</b>: ראה רש\"י וירא שם, ב."],["5734","175","<b>למאה שנים</b>: וירא כא, ה."],["5735","176","<b>נסיון עשירי</b>: ראה תרגום ירושלמי וירא כב, א. פדר\"א פל\"א. מפרשים לאבות פ\"ה, מ\"ג."],["5736","177","<b>נסיון עשירי כנגד עשר כחות הנפש</b>: ראה גם אוה\"ת ח\"ש כרך ד ס\"ע תשעט[ednref_337_ח] כנגד ע\"ס. וראה גם סה\"מ מלוקט ד' ע' נו ואילך."],["5737","178","<b>עתה ידעתי כי ירא אלקים אתה</b>: וירא כב, יב."],["5738","179","<b>מי העיר ממזרח צדק</b>: ישעי' מא, ב."],["5739","180","<b>מקיפים. . ע\"י המשכת הקו</b>: ראה לקו\"ת קרח נב, רע\"ג. נה, רע\"א."],["5740","181","<b>נשמה. . טהורה היא</b>: ברכת אלקי נשמה (מברכות ס, ב)."],["5741","182","<b>ואתה נפחת</b>: ראה גם (לעיל בחלק המאמרים) המשך יונתי ובהערה 528."],["5742","183","<b>בראת יצרת נפחת. . בי\"ע</b>: ראה תו\"א משפטים עז, סע\"א. לעיל ח\"א (בחלק ההנחות) הנחה ד\"ה כמים הפנים פיסקא אך הענין ואילך."],["5743","184","<b>נשמה. . מרשימו</b>: ראה גם (לעיל בחלק המאמרים) מאמר ד\"ה כנשר יעיר קנו על יד הערה 58."],["5744","185","<b>רשימו הוא אותיות</b>: ראה לקו\"ת בהר מג, ב ואילך. הוספות לויקרא נא, סע\"ב. לעיל ח\"א (בחלק המאמרים) המשך מצה זו פ\"ו-ז.\n\n[edn_335_ו] אדמו\"ר מהר\"ש או הצ\"צ.\n\n[edn_336_ז] וכמו שהקשה בזהר וירא קיט, ב. ראה גם אלשיך וירא כב, א ד\"ה ואחשבה.\n\n[edn_337_ח] ושם מובא גם רש\"י אבות שם כנגד עשרה מאמרות."]]],[2000480537,"וגילוי, וזהו הי' טליתו של א\"א בחי' מקיף ששם אינו שייך העלם וגילוי וע\"י העקידה עי\"ז פשט האיל ידיו ורגליו בטליתו של א\"א כו' כי אברהם הגביה את האיל ועשה מאיתו כל הדברים האלו שלא יהי' שום דבר לבטלה כו'. וזהו\"ע החזרת הנפש למקורו ושרשו, שע\"י שמחזיר את הנפש למקורו והרוח תשוב לאלקים אשר ניתנו, עי\"ז ונתתי רוחי בכם וחייתם, בחי' רוח אלקי' מרחפת ע\"פ המים<sup data-n=\"5745\">186</sup>, שהי' בתחלת הבריאה, כמארז\"ל הקב\"ה עושה להם כנפים<sup data-n=\"5746\">187</sup> ושטים ע\"פ המים והו\"ע מקיף זה כו'.\n<b>וזהו</b> שובה ישראל עד ה' אלקיך פי' אם פגם ע\"י חטא ועון בודאי צריך שיהי' בבחי' תשובה ע\"ד שה' יהי' אלקיך, ואם אפי' לא פגם צריך ג\"כ תשובה היינו החזרת הנפש למקורו ושרשו צריך ג\"כ שיהי' ה' בחי' אלקיך ממילא יומשך שם ה' מבחי' גבוה יותר. וזהו אתה אמרת והי' ה' לי לאלקים חייך כל טובות ונחמות יהי' בלשון הזה, והי' ביום ההוא יצאו מים חיים לשון והי' היינו שהו\"ה קודם לי\"ה<sup data-n=\"5747\">188</sup> כי שם הו'<sup data-n=\"5748\">189</sup> י\"ה קודם לו\"ה וכאן ו\"ה קודם לי\"ה, פי' וא\"ו היינו ששה מדות ששת ימים עשה<sup data-n=\"5749\">190</sup> וה' הוא בחי' בהבראם בה' בראם<sup data-n=\"5750\">191</sup>, כי לע\"ל יהי' ו\"ה קודם לי\"ה<sup data-n=\"5751\">192</sup>. וזהו שובה ישראל עד ה' אלקיך ששיעור תשובה היינו עד שה' יהי' בחי' אלקיך, אם פגם ע\"י חטא ועון צריך תשובה בודאי צ\"ל עד שה' יהי' בחי' אלקיך, ואם אפי' לא פגם מ\"מ צריך תשובה היינו החזרה למקורו ושרשו צריך ג\"כ עד שה' יהי' בחי' אלקיך ממילא יומשך משם ה' גבוה יותר, וזהו שובה ישראל עד ה' אלקיך כו'",[["5745","186","<b>רוח אלקי' מרחפת ע\"פ המים</b>: ע\"פ בראשית א, ב."],["5746","187","<b>הקב\"ה עושה להם כנפים</b>: ראה סנהדרין צב, ריש ע\"ב. ילקוט שמעוני ישעי' מ, לא (רמז תמז). מאמרי אדה\"א בראשית ע' עז. וש\"נ. ס\"ע פז ואילך."],["5747","188","<b>שהו\"ה קודם לי\"ה</b>: בשולי היריעה כאן נרשם: ענין ו\"ה קודם לי\"ה ע' ד\"ה קדושים תהיו כי קדוש אני ש' אמר\"ת. יודפס בע\"ה בסה\"מ תרמ\"א."],["5748","189","<b>הו'</b>: אוצ\"ל: הוי'."],["5749","190","<b>ששת ימים עשה</b>: תשא לא, יז. ראה גם לעיל (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה יפה שעה אחת הב' ובהערה 32."],["5750","191","<b>בהבראם בה' בראם</b>: בראשית ב, ד. ראה מנחות כט, ב. ב\"ר פי\"ב, ב. פרש\"י עה\"פ."],["5751","192","<b>לע\"ל יהי' ו\"ה קודם לי\"ה</b>: ראה גם לקו\"ת פ' ראה ל, ד."]]],[2000480538,"<h3>שובה ישראל הנחה ב'</h3>\n<b>הנחה מא' השומעים</b>\n<b>שובה</b> ישראל<sup data-n=\"5752\">1</sup> עד הוי' אלקיך<sup data-n=\"5753\">2</sup>, וצ\"ל למה נזכר כאן הלא דרך כלל עפ\"י רוב השני שמות אלו הם שם מלא<sup data-n=\"5754\">3</sup> ולמה נצרך לתשובה דוקא אלו השני שמות. אך הענין דהנה אי' במד\"ר פ' ע'<sup data-n=\"5755\">4</sup> ע\"פ ושבתי בשלום אל בית אבי<sup data-n=\"5756\">5</sup> ר' יהושע דסכנין בשם ר' לוי נטל הקב\"ה שיחתן של אבות ועשאן מפתח לגאולתן של בנים, אמר הקב\"ה<sup data-n=\"5757\">6</sup> אתה אמרת והי' הוי'<sup data-n=\"5758\">7</sup> לי לאלקים חייך כל טובות ונחמות<sup data-n=\"5759\">8</sup> שאני נותן לבניך איני נותן אלא בלשון הזה שנא' והי' ביום ההוא יצאו מ\"ח מירושלים<sup data-n=\"5760\">9</sup> חציים אל הים הקדמוני<sup data-n=\"5761\">10</sup>, והי' ביום ההוא יוסיף ה' שנית ידו<sup data-n=\"5762\">11</sup>, והי' ביום ההוא יטפו ההרים עסיס<sup data-n=\"5763\">12</sup>, והי' ביום ההוא יתקע בשופר גדול<sup data-n=\"5764\">13</sup>, וצ\"ל מהו המעלה מל' והי' שא' המד\"ר בו בל' אני<sup data-n=\"5765\">14</sup> פורע לך דמשמע שזהו מעלה יתירה. וגם צ\"ל מהו המעלה שלע\"ל יתקע בשופר גדול דוקא והלא לכאו' קטן הוא יותר מעלה וכמ\"ש במד\"ר שה\"ש פ\"ח ע\"פ אחות לנו קטנה<sup data-n=\"5766\">15</sup> ר' עזרי' בשם ר' יהודה בר' סימון לע\"ל עתידין כל שרי או\"ה באין ומקטרגי' את ישראל לפני הקב\"ה ואומרים רבש\"ע אלו עבדו ע\"ז ואלו עבדו כו' מפני מה אנו<sup data-n=\"5767\">16</sup> יורדי' לגיהנם ואלו אינן יורדין אמר להם הקב\"ה אחות לנו קטנה מה קטן זה כל מה שהוא עושה אין ממחין<sup data-n=\"5768\">17</sup> על ידו למה שהוא קטן, כך כל מה שישראל מתלכלכי' כל ימות השנה בעוונותיהן בא יוהכ\"פ ומכפר עליהם שנא' כי ביום הזה יכפר עליכם<sup data-n=\"5769\">18</sup> כו', וא\"כ עי\"ז עיקר הכפרה הוא בשביל שהם בבחי' קטנים, וגם צדיקים הגדולים מצינו שנק' בשם קטנים כמו דוד הקטן<sup data-n=\"5770\">19</sup> שמואל הקטן<sup data-n=\"5771\">20</sup> ואפי' ביעקב כתי' מי יקום יעקב כי קטן הוא<sup data-n=\"5772\">21</sup>, ואפי' בבחי' הגילוים שמלמעלה ארז\"ל",[["5752","1","<b>שובה ישראל</b>: הנחה ממאמר כ\"ק אדמו\"ר מהר\"ש ממאמר ד\"ה זה שנדפס לעיל בחלק המאמרים. וש\"נ.\nהנחה זו לא נגמרה בכתיבתה.\nהנחת אחרת מדרוש זה נדפסה לעיל לפני הנחה זו."],["5753","2","<b>שובה ישראל עד הוי' אלקיך</b>: הושע יד, ב."],["5754","3","<b>השני שמות. . שם מלא</b>: ראה זהר בראשית מח, ב. מט, א. ועוד. לקו\"ת צו יא, ב. נצבים נא, ג."],["5755","4","<b>במד\"ר פ' ע'</b>: ויצא סימן ו."],["5756","5","<b>ושבתי בשלום אל בית אבי</b>: ויצא כח, כא."],["5757","6","<b>אמר הקב\"ה</b>: וכ\"ה לעיל בהנחה ראשונה כאן. במדרש שם: אמר לו הקב\"ה."],["5758","7","<b>הוי'</b>: במדרש שם: ליתא."],["5759","8","<b>ונחמות</b>: שם: וברכות ונחמות."],["5760","9","<b>והי' ביום ההוא יצאו מ\"ח מירושלים</b>: זכרי' יד, ח."],["5761","10","<b>חציים אל הים הקדמוני</b>: כ\"ז ליתא במדרש שם. ראה בהנחה ראשונה (כאן) ובהערה 139."],["5762","11","<b>והי' ביום ההוא יוסיף ה' שנית ידו</b>: ישעי' יא, יא."],["5763","12","<b>והי' ביום ההוא יטפו ההרים עסיס</b>: יואל ד, יח."],["5764","13","<b>והי' ביום ההוא יתקע בשופר גדול</b>: ישעי' כז, יג."],["5765","14","<b>בל' אני </b>: אוצ\"ל בל' והי' אני. או בל' זה אני."],["5766","15","<b>אחות לנו קטנה</b>: שה\"ש ח, ח."],["5767","16","<b>אנו</b>: במדרש שם: אלו."],["5768","17","<b>מה קטן. . אין ממחין</b>: ראה (לעיל בחלק המאמרים) בהמאמר כאן הערה 10."],["5769","18","<b>כי ביום הזה יכפר עליכם</b>: אחרי טז, ל."],["5770","19","<b>דוד הקטן</b>: חולין ס, ב. שמואל-א יז, יד (ושם: ודוד הוא הקטן). ראה מאמרי אדה\"ז על פרשיות התורה ח\"א בהוספות ע' 21. מאמרי אדה\"א בראשית ע' רצז. סה\"מ תר\"ל ס\"ע שו."],["5771","20","<b>שמואל הקטן</b>: חולין שם. ראה סה\"מ תר\"ל שם. סדה\"ד חלק תנו\"א בערכו."],["5772","21","<b>מי יקום יעקב כי קטן הוא</b>: באוה\"ת חנוכה ח\"ב ע' 596 מציין: עמוס ז, ה. מכות כד, סע\"א. ראה חולין וסה\"מ תר\"ל שם. (לעיל בחלק המאמרים) מאמר ד\"ה רני ושמחי על יד הערה 122 ואילך."]]],[2000480539,"צמצם שכינתו בין ב' בדי ארון<sup data-n=\"5773\">22</sup>, וע\"י הצמצום הזה הי' כל הגילוים עליונים בבהמ\"ק וכמ\"ש ונועדתי לך שם ודברתי אתך<sup data-n=\"5774\">23</sup> כו', ומהו ההפרש בשופר בין קטן לגדול, וגם צ\"ל מארז\"ל הרואה שופר בחלום יצפה לישועה<sup data-n=\"5775\">24</sup> שנא' והי' ביום ההוא יתקע בשופר גדול, וצ\"ל מאי ראי' משופר גדול לסתם שופר דהרי שופר גדול דוקא מורה על ישועה ולא סתם שופר, וא\"ת שאין הפרש ביניהם הלא מהפ' אינו משמע כן, וגם צ\"ל מארז\"ל ע\"פ מי אל כמוך נושא עון ועובר על פשע לשארית נחלתו<sup data-n=\"5776\">25</sup> וארז\"ל למי שמשים א\"ע כשיריים<sup data-n=\"5777\">26</sup>, וצ\"ל הלא נושא עון הם יגמה\"ר ושם אין דקדוקים כלל כי אינו תופס מקום שמה, ולמה דוקא תלוי במי שמשים א\"ע כשיריים.\n<b>אך</b> הענין דהנה אי' בילקוט<sup data-n=\"5778\">27</sup> בשם פדר\"א פל\"א באילו של אאע\"ה ר' חנינא בן דוסא אומר אותו האיל לא יצא ממנו דבר לבטלה, אפרו של איל הוא יסוד שע\"ג מזבח הפנימי<sup data-n=\"5779\">28</sup>, גידיו של איל הם עשרה כנגד עשרה נבלים של כנור שהי' דוד מנגן<sup data-n=\"5780\">29</sup> בהם, עורו של איל הוא אזור מתניו של אלי' שהי' חגור אזור של עור<sup data-n=\"5781\">30</sup>, שתי קרניו של איל שופרות בשל שמאל תקע בו הקב\"ה על הר סיני שנא' ויהי קול השופר<sup data-n=\"5782\">32</sup> כו' והאלקים יעננו בקול<sup data-n=\"5783\">33</sup> וגם כתי' וכל העם כו' ואת קול השופר<sup data-n=\"5784\">34</sup>, וקרן של ימין<sup data-n=\"5785\">31</sup> הוא גדול מן השמאל ועתיד לתקוע בו לע\"ל בקיבוץ של גליות, וצ\"ל האיך שייך התחלקות ימין ושמאל בשופר הלא ידוע דענין השופר הוא מורה על צעקה<sup data-n=\"5786\">*35</sup> פנימית מעומקא דלבא כדי שעי\"ז יומשך יגמה\"ר<sup data-n=\"5787\">**35</sup> ששם הוא הסליחה",[["5773","22","<b>צמצם שכינתו. . ארון</b>: ראה ב\"ר פ\"ד, ד. מאמרי אדה\"ז תקס\"ג ח\"א ס\"ע שמו ואילך (נו\"א). לקו\"ת אמור לד, ב. הנסמן במאמרי אדה\"א בראשית ע' קכט. שה\"א ז, א ובהערה 12."],["5774","23","<b>ונועדתי לך שם ודברתי אתך</b>: ע\"פ תרומה כה, כב."],["5775","24","<b>הרואה שופר בחלום יצפה לישועה</b>: ילקוט שמעוני ישעי' כז, יג (רמז תלו). ראה (לעיל בחלק המאמרים) בהמאמר כאן הערות 21-22."],["5776","25","<b>מי אל כמוך. . לשארית נחלתו</b>: מיכה ז, יח. לעיל בהנחה ראשונה נרשם זה בסיום פיסקא שני'."],["5777","26","<b>למי שמשים א\"ע כשיריים</b>: ר\"ה יז, ריש ע\"ב."],["5778","27","<b>אי' בילקוט</b>: שמעוני מלכים-ב א, ח (רמז רכד) — בשינויים. וראה גם וירא כב, יג (רמז קא). ישעי' כז, יג (רמז תלו)."],["5779","28","<b>אפרו של איל הוא יסוד שע\"ג מזבח הפנימי</b>: ראה גם (לעיל בחלק המאמרים) בהמאמר כאן הערה 14."],["5780","29","<b>עשרה נבלים של כנור שהי' דוד מנגן</b>: ראה הגהת הרד\"ל בפרקי דר\"א פי\"ט אות כג. ספל\"א כאן אות עג."],["5781","30","<b>אליהו. . חגור אזור של עור</b>: מלכים-ב א, ח."],["5782","32","<b>ויהי קול השופר</b>: יתרו יט, יט."],["5783","33","<b>כו' והאלקים. . יעננו בקול</b>: בילקוט כאן ליתא. ראה גם לעיל בהנחה ראשונה כאן הערה 29."],["5784","34","<b>וכל העם. . השופר</b>: יתרו כ, טו. בילקוט כאן ליתא."],["5785","31","<b>שתי קרניו של איל. . שמאל. . ימין</b>: ראה גם (לעיל בחלק המאמרים) בהמאמר כאן הערה 16."],["5786","*35","<b>השופר. . צעקה</b>: ראה גם (לעיל בחלק המאמרים) בהמאמר כאן על יד הערה 33. לקו\"ת נצבים מד, ב ואילך. מח, א ואילך. ר\"ה נד, ג. נו, ד. סה\"ש תש\"ד ס\"ע 4 ואילך."],["5787","**35","<b>השופר. . יגמה\"ר</b>: ראה לקו\"ת פ' ראה ל, ג. נצבים מח, א. מאמרי אדה\"א דברים ח\"ג ע' א'מט ואילך. וש\"נ."]]],[2000480540,"ושם אין התחלקות כלל וכמאמרם לית שמאלא בהאי עתיקא<sup data-n=\"5788\">35</sup> וכתי' ימינך ה' נאדרי כו' תרעץ אויב<sup data-n=\"5789\">36</sup> שהוא כולו ימין, וגם צ\"ל מ\"ש קודם בפדר\"א<sup data-n=\"5790\">37</sup> ר' זכרי' אומר אותו האיל שנברא בין השמשות, וזה אי' גם במשנה וי\"א אף אילו של א\"א<sup data-n=\"5791\">38</sup> ע\"ה נברא בין השמשות, הי' רץ ובא להתקרב תחת יצחק והי' סמאל<sup data-n=\"5792\">39</sup> עומד ומשטה אותו כדי לבטל קרבנו של א\"א ונאחז בשתי קרנותיו בין האילנות שנא' וישא אברהם את עיניו וירא והנה איל<sup data-n=\"5793\">40</sup>, מה עשה האיל פשט את ידו בטליתו של א\"א הביט אברהם וראה את האיל ולקח אותו והתירו והקריבו תחת יצחק, וזה לכאו' אינו מובן כלל מהו הפי' שפשט את ידו ומהו זה שא' ואחז בטליתו האם בטלית הי' אברהם לבוש אז<sup data-n=\"5794\">41</sup>.\n<b>אך</b> הענין דהנה מה שיעקב נק' קטן<sup data-n=\"5795\">42</sup> הוא מפני שהוא מבריח מהקאה\"ק<sup data-n=\"5796\">43</sup>, ושם קצה מורה על היות בו שם הגבלה דמה שקטן הוא למעליותא הוא דוקא בעבודה שכל מה שהאדם מקטין א\"ע ה\"ה שפל בעיניו ועי\"ז נמחל לו עוונותיו כמו למשל באדם כאשר מחזיק א\"ע לגדול או שהוא גדול מדקדקין על כל מעשיו, אבל מי שמחזיק א\"ע לקטן או שהוא קטן הרי הוא אינו במשמע כלום וכל עניניו אינם במשמע ואין מדקדקים עליו, אבל מה שיעקב הוא קטן הוא לפי שמבריח מן קצה השמים דלעילא עד קצה\"ש דלתתא, לומר<sup data-n=\"5797\">44</sup> שם קצה ה\"ז הגבלה לגבי א\"ס העצמי דלגבי כללות<sup data-n=\"5798\">45</sup> ההשתל' אין תופסים מקום מפני שכולם לא נתהוו כ\"א מהארה בעלמא, ואפי' עולמות עליונים ששם ריבוי גילוי אלקות מ\"מ הרי נק' בשם עולם ולא נתהוה כ\"א מזיו והארה בעלמא ואין תופסים מקום כלל וכלל לגבי א\"ס וכמ\"ש אני ה' לא שניתי<sup data-n=\"5799\">46</sup> אתה הוא קודם שנבה\"ע<sup data-n=\"5800\">47</sup> ולאחר שנבה\"ע שאין שום שינוי והתפעלות לפניו מבריאותו את העולמות, ולכן נק' יעקב קטן לא מפני שהוא בעצם קטן אלא מפני הברחתו כללות ההשתל', וכללות ההשתל' נק' לגבי א\"ס בשם קטן.",[["5788","35","<b>לית שמאלא בהאי עתיקא</b>: ראה זהר אד\"ר נשא קכט, א. ע\"ח שער עתיק שי\"ב, פ\"ב. שער הארת המוחין של\"ב, פ\"ז. הנסמן במאמרי אדה\"א דברים ח\"ג ע' תתעא."],["5789","36","<b>ימינך ה'. . תרעץ אויב</b>: בשלח טו, ו."],["5790","37","<b>מ\"ש קודם בפדר\"א</b>: ספל\"א."],["5791","38","<b>וי\"א אף אילו של א\"א</b>: ראה אבות פ\"ה, מ\"ו."],["5792","39","<b>סמאל</b>: בפדר\"א שם: השטן. בילקוט שמעוני מהדורת ירושלים תשל\"ג פ' וירא כאן ע' 451 הערה 33 שבפדר\"א מהדורת סביוניטה שכ\"ז: סמאל."],["5793","40","<b>וישא אברהם. . והנה איל</b>: וירא כב, יג."],["5794","41","<b>לכאו' אינו מובן. . בטלית. . לבוש אז</b>: הנחה זו לא נגמרה כנ\"ל. — ראה גם בענין זה לעיל בהנחה ראשונה פיסקא ועפ\"ז יובן. ו(לעיל בחלק המאמרים) בהמאמר כאן סביבות הערה 54."],["5795","42","<b>שיעקב נק' קטן</b>: ראה גם תו\"א וישב כט, ד."],["5796","43","<b>שיעקב. . מבריח מהקאה\"ק</b>: ע\"ד תרומה כו, כח. ראה זהר בשלח נא, ב. תרומה קעה, ב. הנסמן במאמרי אדה\"א שמות ח\"א ע' יט. סה\"מ תרכ\"ט ע' קיז. וש\"נ. תרנ\"ג ע' רנח ואילך."],["5797","44","<b>לומר</b>: בהכת\"י הניח מקום פנוי לפני תיבה זו. ואוצ\"ל: ויש לומר."],["5798","45","<b>דלגבי כללות</b>: אוצ\"ל: דלגבי' כללות־ או דלגבי א\"ס כללות."],["5799","46","<b>אני הוי' לא שניתי</b>: מלאכי ג, ו. ראה גם לעיל (בחלק המאמרים) המשך יונתי ובהערה 29."],["5800","47","<b>אתה הוא קודם שנבה\"ע</b>: ראה תפלת השחר. של\"ה תולדות אדם ג, ב. מאמרי אדה\"ז על מארז\"ל ע' שלו."]]],[2000480541,"<b>ובזה</b> נבוא על ביאור ההפרש שבין שופר גדול לקטן, דהנה מעלת השופר הוא דכתי' בי' מן המיצר קראתי<sup data-n=\"5801\">48</sup> כו' ענני במרחב י\"ה שע\"י השופר נעשה מרחב בי\"ה כי הנה היו\"ד היא נקודה חדא וע\"י השופר נעשה בו מרחב, והנה העיקר בתקיעת שופר כתב הרמב\"ן שהוא התקיעה<sup data-n=\"5802\">49</sup> שהוא קול פשוט<sup data-n=\"5803\">50</sup> כי שברים תרועה מורה על גנוחי גניח ילולי יליל<sup data-n=\"5804\">51</sup> כדרך החולים וה\"ז חסר וא\"כ אין זה ממצות התקיעה בעצם אלא שעיקר המצוה היא התקיעה, והענין הוא דהנה תקיעה הוא צעקה בקול פשוט, והנה הגם שנת' בכ\"מ שהצעקה דשופר מורה על תשובה ממש צ\"ל דלאו דוקא על תשובה בלבד רומז כ\"א ג\"כ על מדריגת צדיקים, דאם נאמר שדוקא הוא על תשובה הרי נותנים מקום לחטוא וכמו שנת' דמצות<sup data-n=\"5805\">54</sup> התשובה<sup data-n=\"5806\">52</sup> הוא לאו דוקא על חטא ועון<sup data-n=\"5807\">53</sup> כ\"א על החזרת הנפש<sup data-n=\"5808\">55</sup> למקורו ושרשו וכמ\"ש והרוח תשוב<sup data-n=\"5809\">56</sup> כו', וכמו\"כ מצות שופר רומז ג\"כ על תשובה דחטא ועון ועל תשו' דהחזרת הנפש כי שופר הוא ג\"כ החזרת הנפש.\n<b>והנה</b> יש החזרת הנפש שבכל לילה וההחזרה כללית דכללות השנה והוא השופר, וכמו שבכל לילה צ\"ל חשבון צדק<sup data-n=\"5810\">57</sup> בינו לבין קונו מכל המודו\"מ דכל היום שאותן המדו\"מ שלא לה' א\"א להחזירם בבחי' העלאה לשרשו שהרי הם נגד רצונו ית' וצריך לעשות תשובה עליהם דהיינו חרטה ועקירת הרצון, כי הנה הנשמה הוא בחי' שליח מהמשלח שמשלחה להחיות את הגוף, ועיקר החיות הוא הקיום דתומ\"צ וכמ\"ש אנכי עשיתי ארץ<sup data-n=\"5811\">58</sup> ואדם עליה בראתי, בראתי בגימ' תרי\"ג<sup data-n=\"5812\">59</sup>, כמו\"כ החיות דר\"ה הוא ג\"כ בחי' שליח שנשלח חיות ממנו ית' להחיות כללות השנה ועיקר הכוונה הוא החיות רוחני וע\"ז הוא הדין ומשפט דר\"ה<sup data-n=\"5813\">60</sup>, והגם שהדין דר\"ה הוא על החיים הגשמי'<sup data-n=\"5814\">61</sup> היינו החיות דהגשמיות שהוא הקיום דתומ\"צ, ולכן צ\"ל חשבון בכל ר\"ה מכל המדו\"מ דשנה העברה, דהנה האדם הוא עולם קטן<sup data-n=\"5815\">62</sup> וכל מה שיש בעולם",[["5801","48","<b>מן המיצר קראתי</b>: תהלים קיח, ה."],["5802","49","<b>העיקר בתקיעת שופר כתב הרמב\"ן שהוא התקיעה</b>: ראה גם בהנחה ראשונה כאן."],["5803","50","<b>התקיעה שהוא קול פשוט</b>: שו\"ע אדה\"ז הל' ר\"ה סתק\"צ, ס\"א. ראה גם לעיל (בחלק המאמרים) המשך יונתי ובהערה 607."],["5804","51","<b>גנוחי גניח ילולי יליל</b>: ר\"ה לג, ב. לד, א."],["5805","54","<b>דמצות התשובה</b>: ראה (לעיל בחלק המאמרים) המשך יונתי הערה 464."],["5806","52","<b>דשופר מורה על התשובה</b>: ראה רמב\"ם הל' תשובה פ\"ג, ה\"ד."],["5807","53","<b>שנת' דמצות התשובה. . חטא ועון</b>: ראה לעיל הנחה ד\"ה יפה שעה אחת הב' על יד הערה 21 ואילך."],["5808","55","<b>תשובה. . החזרת הנפש</b>: ראה גם לעיל שם ובהערה 454."],["5809","56","<b>והרוח תשוב</b>: קהלת יב ז."],["5810","57","<b>שבכל לילה צ\"ל חשבון צדק</b>: ראה זהר קרח קעח, א. (לעיל בחלק המאמרים) המשך יונתי פכ\"ב ובהערה 549."],["5811","58","<b>אנכי עשיתי ארץ</b>: ישעי' מה, יב."],["5812","59","<b>בראתי בגימ' תרי\"ג</b>: ראה רמ\"ז לזהר ויגש רה, ב. לעיל ח\"א (בחלק המאמרים) המשך מצה זו ובהערה 1688."],["5813","60","<b>החיות הרוחני. . הדין ומשפט דר\"ה</b>: ראה לקו\"ת ר\"ה נו, א. מאמרי אדה\"א בראשית ע' קד. בהערה הבאה."],["5814","61","<b>שהדין דר\"ה. . החיים הגשמי'</b>: ראה הגהות מיימוניות רפ\"ג מהל' תשובה. (לעיל בחלק המאמרים) המשך יונתי ובהערה 568."],["5815","62","<b>האדם הוא עולם קטן</b>: ראה בחיי בראשית א, לא (ריש ע' נ) בשם חכמי המחקר. אדר\"נ פל\"א, ג. תנחומא פקודי ג. מאמרי אדה\"א הנחות תקע\"ז ע' צח. וש\"נ."]]],[2000480542,"יש באדם וע\"י החזרת החיות שבאדם עי\"ז נעשה החזרה בחיות כללי של העולם<sup data-n=\"5816\">63</sup>, וע\"ז רומז הצעקה דשופר ולא מיבעי' אם חטא ופגם שבודאי צ\"ל תשובה וצעקה פנימיות שהרי פגם הוא ל' חסרון כמו סכין פגום שנאחז בצפורן והרי חסר במקום ההוא, וכמו\"כ חטא הוא ג\"כ מל' חסרון<sup data-n=\"5817\">64</sup> וכמ\"ש קולע אל השערה ולא יחטא<sup data-n=\"5818\">65</sup> וכמ\"ש והייתי אני ובני שלמה חטאים<sup data-n=\"5819\">66</sup>, ופרש\"י כלומר חסרים<sup data-n=\"5820\">67</sup>, והרי ע\"י חטא ופגם נעשה חסרון למעלה ובודאי צ\"ל צעקה פנימית אלא אפי' בהחזרת הנפש צ\"ל צעקה פנימית, ובאמת כאשר יתבונן האדם יבין האיך שע\"י חטא ופגם נעשה רחוק מאד ממנו ית', דהנה כתי' סור מרע ועש\"ט<sup data-n=\"5821\">68</sup>, והנה העיקר הוא ועשה טוב שעי\"ז נעשה המשכת אלקות, אך בתחלה צ\"ל סו\"מ, אך כאשר הסו\"מ אינו כדבעי למהוי מכ\"ש שהמע\"ט אינו כדבעי למהוי, ולא די שלא נשלם הכוונה שיומשך ע\"י האורות ועי\"ז יתעלה נפשו למעלה אלא שמורידו לבאר שחת וא\"כ צריך לצעוק ע\"ז מפנימיות לבו, ובאמת כאשר יפשפש האדם בנפשו הדק היטב ימצא האיך שהוא רחוק ממנו ית'. והנה אפי' צדיקים גמורים שנקיים מכל חטא ופגם ואפי' מהרהורי עבירה שקשים מעבירה<sup data-n=\"5822\">70</sup> מפני שמלפפתו<sup data-n=\"5823\">71</sup> ומטמא מחשבתו מ\"מ ימצא בנפשו דקות הרע שבדו\"מ וצ\"ל חשבון בנפשו<sup data-n=\"5824\">69</sup> והמדו\"מ<sup data-n=\"5825\">*172</sup> שימצא בהם שהם לא לה' לגמרי צ\"ל תשובה עליהם דהיינו חרטה ועקירת הרצון, שהרי לכן גם הצדיק צ\"ל כל הוידוים דר\"ה<sup data-n=\"5826\">73</sup> ויוהכ\"פ<sup data-n=\"5827\">72</sup>, אפי' הצדיק שהוא נקי גם מדקות הרע מ\"מ הרי צריך מצות שופר שהוא הצעקה פנימית על החזרת הנפש.",[["5816","63","<b>החזרת החיות שבאדם. . העולם</b>: ראה זהר מקץ קצה, ב. לקו\"ת במדבר ה, ריש ע\"ב."],["5817","64","<b>חטא. . מל' חסרון</b>: ראה לקו\"ת מטות פב, א. נצבים נא, א. מאמרי אדה\"א דברים ח\"ג ע' תתקיד. נ\"ך ע' נא. סה\"מ תרל\"ב ח\"א ע' קמד. המשך תער\"ב ח\"ג ע' א'תנט. סה\"מ מלוקט א' ע' רצב. שם ב' ע' קכח ובהנסמן בהנ\"ל."],["5818","65","<b>קולע אל השערה ולא יחטא</b>: ס' שופטים כ, טז [בדילוג]."],["5819","66","<b>והייתי אני ובני שלמה חטאים</b>: מלכים-א א, כא."],["5820","67","<b>ופרש\"י כלומר חסרים</b>: תיבת כלומר לא הובא ברש\"י שם. ראה גם לעיל בהנחה ראשונה כאן הערה 66."],["5821","68","<b>סור מרע ועש\"ט</b>: תהלים לד, טו. ראה גם לעיל הנחה ד\"ה אני לדודי הב' ובהערה 89."],["5822","70","<b>מהרהורי עבירה שקשים מעבירה</b>: ראה יומא כט, א. לעיל ח\"א (בחלק המאמרים) המשך זאת חנוכת המזבח הערה 381."],["5823","71","<b>מעבירה מפני שמלפפתו</b>: ראה סוטה ג, ב. לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה מזבח אדמה תעשה לי פיסקא והנה כמו."],["5824","69","<b>צדיקים גמורים. . חשבון בנפשו</b>: ראה גם לקמן הנחה ד\"ה כנשר יעיר קנו ובהערה 106."],["5825","*172","<b>שבדו\"מ. . והמדו\"מ</b>: כ\"ה בהכת\"י."],["5826","73","<b>הוידוים דר\"ה</b>: ראה גם מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תתצו. תקס\"ב ח\"ב ע' תקנח וע' תקנט. ע' תקסד. מאמרי אדה\"א הנחות תקע\"ז ע' שלח. דברים ח\"ד ע' א'רנו. סה\"מ תרל\"ב ח\"ב ריש ע' תקפד. שו\"ע אדה\"ז הל' ר\"ה סתקפ\"ד, ס\"ב. ובסידורו לפני אבינו מלכנו [הועתק בהוספות לשו\"ע שם]. לקו\"ש ר\"ה כרך ד' ע' 1355[ednref_338_א]. ע' 1360. אוצר מנהגי חב\"ד חלק ר\"ה מערכת יתוודה בלחש ע' קכד-קכה."],["5827","72","<b>הצדיק. . הוידוים דר\"ה ויוהכ\"פ</b>: : ראה גם (לעיל בחלק המאמרים) המשך יונתי ובהערה 590.\n\n[edn_338_א] נדפס גם באג\"ק שלו חכ\"ב ע' תקיב."]]],[2000480543,"<b>אך</b> גם מי שחטא ופגם נגדו ית' מ\"מ בל יאמר נואש כי תשובה מועלת על הכל<sup data-n=\"5828\">74</sup>, והגם דאיתא בזהר שיש דברים שאין מועיל עליהם תשו'<sup data-n=\"5829\">75</sup>, היינו תשו' תתאה אבל תשו\"ע מועלת<sup data-n=\"5830\">76</sup>, ותשו\"ע היינו התקשרות נפשו בתו' ולכן אי' בכהאריז\"ל שהנודד שינה מעיניו בלילה א' בשבוע<sup data-n=\"5831\">78</sup> עי\"ז מבטל איזה כרת מנפשו<sup data-n=\"5832\">77</sup> והוא ע\"י הכח דתו' וכמ\"ש בתד\"א הי' רגיל ללמוד<sup data-n=\"5833\">79</sup> פרק א' דף א' ילמוד שני פרקים שני דפים, והגם כי תפלה הוא ג\"כ תשובה<sup data-n=\"5834\">80</sup>, כי תפלה הוא התדבקות הנפש<sup data-n=\"5835\">81</sup> וכמארז\"ל התופל כלי חרס<sup data-n=\"5836\">82</sup> והוא שפיכת הנפש<sup data-n=\"5837\">83</sup> שלפני ה' וכמ\"ש ואשפוך את נפשי<sup data-n=\"5838\">84</sup> לפני ה' מ\"מ ה\"ה רק תשו\"ת, אך אם פגם הנפש אינו גדול כ\"כ אז די לו בתשו\"ת דתפלה, ואם הפגם יותר גדול אז נצרך לתשו\"ע דתו', אבל תשו\"ע מועלת על הכל.\n<b>והנה</b> הגם שנת' שגם על החזרת הנפש צ\"ל צעקה פנימית מ\"מ אינו דומה להצעקה שעל החטא ועון, כי מי שחטא ה\"ה צועק על מה שחסר בנפשו וה\"ז כמו החולה שצועק מריבוי מכאוביו, והצעקה שעל ההחזרה הוא כמו געגוע הבן אל האב. והענין הנה הנפש קודם ירידתה למטה עמדה באהוי\"ר<sup data-n=\"5839\">85</sup> גדולה לפניו ית' ואח\"כ ירדה למטה להתלבש בגוף ונה\"ב, שלאחר כל העליות אין ערוך האהוי\"ר שלמטה לגבי האהוי\"ר שהי' לה מקודם וה\"ז ירידה עצומה, אך ע\"ז כתי' יש מפזר ונוסף עוד<sup data-n=\"5840\">86</sup> דכמו שהסוחר מפזר הון רב<sup data-n=\"5841\">87</sup> והוא בשביל הריוח שיתוסף אח\"כ כמו\"כ",[["5828","74","<b>תשובה מועלת על הכל</b>: ראה לקמן הערה 91."],["5829","75","<b>דאיתא בזהר. . שאין מועיל עליהם תשו'</b>: ראה אגה\"ת פ\"ד: בקצת מקומות בזוהר. ובמ\"מ הגהות והע\"ק לשם — זח\"א ריט, ב. ועייג\"כ זח\"א סב, א והגירסא בר\"ח — דלהלן — וזח\"ב ריד, ב. לקמן הנחה ד\"ה כנשר יעיר קנו ובהערה 132."],["5830","76","<b>תשו\"ע מועלת</b>: ראשית חכמה שער הקדושה פי\"ז (קרוב לתחלתו ד\"ה עוד בזהר, רד, א). אגה\"ת שם."],["5831","78","<b>בלילה א' בשבוע</b>: כ\"ה גם בהנחה הראשונה כאן על יד הערה 75."],["5832","77","<b>אי' בכהאריז\"ל. . בלילה א'. . כרת מנפשו</b>: ראה ספר מחברת הקודש סדר חגה\"ש קי, סע\"ד ואילך. ספר הכונות (קארעץ תקמ\"ד) מח, ב ד\"ה מסורת. נגיד ומצוה ח\"ב קרוב לסופו — ירושלים תשכ\"ה — ע' קצד. שו\"ע האריז\"ל כוונת מלקות. תפלת יהי רצון שבסיום תיקון ליל שבועות והושע\"ר. לעיל בהנחה הראשונה כאן על יד הערה 74."],["5833","79","<b>וכמ\"ש בתד\"א הי' רגיל ללמוד</b>: בקיצורים והערות לתניא ס\"ע לט מציין: ע' ויקרא רבה פכ\"ה ע\"ש. ראה לקו\"ש אגה\"ת כרך טל ע' 111 ואילך ובהערה 1 והערה 15 שם. לקמן הנחה ד\"ה כנשר יעיר קנו ובהערה 133."],["5834","80","<b>תפלה הוא ג\"כ תשובה</b>: ראה גם מאמרי אדה\"א דברים ח\"ב ע' תרנו."],["5835","81","<b>תפלה הוא התדבקות הנפש</b>: ראה גם לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה זאת חנוכת המזבח ובהערה 17."],["5836","82","<b>תפלה. . התופל כלי חרס</b>: כלים פ\"ג, מ\"ה. ראה גם (לעיל ח\"א בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה בן פורת יוסף הא' ובהערה 36."],["5837","83","<b>תפלה. . שפיכת הנפש</b>: ראה פע\"ח בתחלתו. ראה גם (לעיל בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה ויאמר ה' אל אברם לך לך ובהערה 67."],["5838","84","<b>ואשפוך את נפשי</b>: שמואל-א א, טו."],["5839","85","<b>הנפש. . עמדה באהוי\"ר</b>: ראה גם לעיל ח\"א (בחלק המאמרים) מאמר ד\"ה ואעשך לגוי ובהערה 60."],["5840","86","<b>יש מפזר ונוסף עוד</b>: משלי יא, כד."],["5841","87","<b>שהסוחר מפזר הון רב</b>: ראה גם תו\"א וישב כו, ג."]]],[2000480544,"הגם שנעשה גרעון באהוי\"ר שהי' לה מקודם מ\"מ ע\"י הירידה נעשה עלי' גדולה מאד והוא לאשתאבא בגופא דמלכא<sup data-n=\"5842\">88</sup> ועש\"ז נק' הנשמה בשם כנען<sup data-n=\"5843\">89</sup>.\n<b>והנה</b> הצדיק שלא חטא ופגם הרי הצעקה שלו הוא רק על החזרת הנפש והוא כמו למשל בגשמיות שכאשר ישמע האדם שיש דבר טוב מאד ה\"ה רוצה להשיגו, ועד\"ז מעין זה יובן שהצעקה דצדיקי' הוא בשביל לאשתאבא בגופא דמלכא, אבל מי שחטא ופגם הרי עי\"ז נעשה ריבוי מכאובים כמ\"ש מכף רגלו ועד ראשו<sup data-n=\"5844\">90</sup> אין בו מתום פצע וחבורה כו', הרי צעקה זו בהתגברות יתירה שהוא צועק מאליו וממילא וכמו החולה שכואב לו מאד ה\"ה צועק בקולות מרים, ומה מועיל הצעקה, אלא מפני המכאובים שנוגעים עד תוך תוכו ה\"ה צועק מאליו מקירות לבו. אך מ\"מ בל יאמר נואש ח\"ו כי אין לך דבר שעומד בפני התשובה<sup data-n=\"5845\">91</sup> וזהו דרך כלל הצעקה דשופר.\n<b>והנה</b> השופר הוא מקרן בהמה<sup data-n=\"5846\">92</sup> והוא כמארז\"ל בנ\"א שהם ערומים בדעת<sup data-n=\"5847\">93</sup> כאדם ונמשכים אחריך כבהמה, ופרש\"י כאדם כאדה\"ר<sup data-n=\"5848\">94</sup>, וצ\"ל הלא ידוע שאדם סתם רמז לחכ' וכמ\"ש ויפח באפיו נשמת חיים<sup data-n=\"5849\">95</sup> והוא כמ\"ש והחכ' תחיה<sup data-n=\"5850\">96</sup>, ואדה\"ר הוא ח\"ס כי יש כמה בחי' ראש וראשית וראשון<sup data-n=\"5851\">97</sup> ואדה\"ר הוא ח\"ס והבהמה אין לה דעת כלל והאיך נמשכים כבהמה. אך הנה ארז\"ל לעולם יהא אדם ערום ביראה<sup data-n=\"5852\">98</sup> ומשמע דגם אם יגיע ליראה עדיין אינו מספיק כ\"א נצרך שיהי' ערום ביראה, וצ\"ל מהו ערמומיות דיראה, דהנה יש שהוא<sup data-n=\"5853\">99</sup> הגבה למעלה מהחכ' וכמ\"ש אני חכ' שכנתי ערמה<sup data-n=\"5854\">100</sup> ואי' בזהר שערמה זו הוא בחי' גבוה מאד עד שהחכ' נחשבת רק כהשכן נגדה דהרי יש ריחוק הערך משכן לבעה\"ב שהשכן הגם שהוא דר בהבית מ\"מ אין הבית שלו כ\"א של בעה\"ב, ועד\"ז יובן שהערמה גבוה למעלה מעלה מהחכ'. והענין דהנה ההפרש בין חכ' לערמה, דהנה ארז\"ל איזהו חכם הרואה את הנולד<sup data-n=\"5855\">101</sup> שרואה הדבר שעדיין לא בא והוא רואה בעין שכלו שיבוא אחר כמה שנים ומגלה הדבר ההוא לזולתו ומזה הדבור נעשו מוחי' לזולתו, ואין הפי' שזה הדבור",[["5842","88","<b>לאשתאבא בגופא דמלכא</b>: זהר ויחי ריז, ב. ראה גם לעיל ח\"א (בחלק המאמרים) מאמר ד\"ה סמכוני באשישות ובהערה 51."],["5843","89","<b>נק' הנשמה בשם כנען</b>: ראה גם תו\"א שם."],["5844","90","<b>מכף רגלו ועד ראשו</b>: ישעי' א, ו [ושם: רגל. . ראש]."],["5845","91","<b>אין לך דבר שעומד בפני התשובה</b>: ראה תניא פכ\"ה. פיה\"מ להרמב\"ם אבות פ\"ג, מי\"א. סה\"מ תש\"ט ע' 42 (הא') בהערה. לקו\"ש בא כרך ו ע' 66 הערה 54."],["5846","92","<b>השופר הוא מקרן בהמה</b>: ראה ר\"ה טז, א. מאמרי אדה\"א דברים ח\"ג ע' תתצז. וש\"נ."],["5847","93","<b>בנ\"א שהם ערומים בדעת</b>: ראה חולין ה, ב. לקו\"ת בחוקותי נ, רע\"ג."],["5848","94","<b>ופרש\"י כאדם כאדה\"ר</b>: ראה רש\"י תהלים לז, ו. חולין שם."],["5849","95","<b>ויפח באפיו נשמת חיים</b>: בראשית ב, ז. ראה גם לעיל בהנחה ראשונה כאן ובהערה 87."],["5850","96","<b>והחכ' תחיה</b>: קהלת ז, יב [ושם: החכמה — ראה לעיל ח\"א (בחלק המאמרים) המשך מצה זו הערה 292]."],["5851","97","<b>ואדה\"ר הוא ח\"ס. . ראש וראשית וראשון</b>: ראה גם בהנחה ראשונה כאן."],["5852","98","<b>לעולם יהא אדם ערום ביראה</b>: ברכות יז, א."],["5853","99","<b>יש שהוא</b>: אוצ\"ל: יש ערמה שהוא."],["5854","100","<b>אני חכ' שכנתי ערמה</b>: משלי ח, יב. ראה גם סה\"מ תרל\"ב ח\"א ע' קצג. ח\"ב ע' תקסד."],["5855","101","<b>איזהו חכם הרואה את הנולד</b>: תמיד לב, א."]]],[2000480545,"נעשה מוחין ממש אלא שזה הדבור גורם שמתגלה אצל הזולת המוחין שלו להשיג בהדבור ההוא. ואפ\"ל כי נעשו לו מוחין ממש וכמארז\"ל לא קאים אינש אדעתי' דרבי'<sup data-n=\"5856\">102</sup> עד לאחר מ' שנין שלאחר מ' שנים אז יזכר שכך אמר הרב וכך הי' כוונתו הרי שנעשה מוחין ממש. אבל הערום אינו מדבר כלל מהענין שרוצה אלא מסבב בתחבולות והמצאות עד שלבסוף נתקיים מחשבתו המסבבת הדבר ההוא, והנה ערמה זו אסור עפ\"י דין כי שרש ערמה זו נמשך מחטא עה\"ד וכמ\"ש והנחש הי' ערום<sup data-n=\"5857\">103</sup> שהלכה בערמומית ותחבולות ששאלה מה אסר להם הקב\"ה אם זה אסר לכם ושאלה על הדבר המותר שידעה<sup data-n=\"5858\">*104</sup> שזה לא אסרו שהרי הי' ערום ומכ\"ש חכם אלא שע\"י דבר המותר הסיתה אותה לדבר האסור.\n<b>אך</b> הנה בקדושה יש ג\"כ ערמה וכמ\"ש בא אחיך במרמה<sup data-n=\"5859\">104</sup> שכדי לתקן ולברר החטא דעה\"ד שהי' ע\"י מרמה א\"א ג\"כ כ\"א רק ע\"י מרמה ולכן רימה יעקב אבינו ע\"ה את עשו וכמ\"ש ויעקבני<sup data-n=\"5860\">105</sup> כו', ועד\"ז יובן בערמה דיראה, דהנה הגם שבדרך כלל לא נזכר שני<sup data-n=\"5861\">106</sup> מדרגות יראה, יר\"ת ויר\"ע<sup data-n=\"5862\">107</sup>, מ\"מ דרך פרט יש הרבה מדרגות ביראה. דכמו שבביטול יש כמה ביטולים דהיינו ביטול היש שהוא בטל ויודע שהוא מציאות בלתי מתקיים לבדו ומ\"מ ה\"ה מציאות יש, והאיך ה\"ה שני הפכים, אלא שבאמת ה\"ה בטל דאם הי' נפרד לגמרי לא הי' מתקיים כלל שהרי חיותו מאתו ית' אלא מפני שהכח אלקי שמחי' אותו הוא ע\"י ההסתר ולכן הוא מציאות יש, והגם שכח ההסתר הוא אלקות כמו כח הנגלה וכמ\"ש אכן אתה אל מסתתר<sup data-n=\"5863\">108</sup> מ\"מ ה\"ה הסתר ולכן יכול להיות יש ולפי ערך ביטולו לפ\"ע זה הוא היש שלו, ויש ביטול אמיתי שהוא ביטול בתכלית לגמרי ביטול במציאות, ויש עוד ביטול שהוא ראו מ\"ה<sup data-n=\"5864\">109</sup> שרוצה שיתראה המ\"ה שלו לבריות, והאיך הוא זה דאם הוא בטל האיך רוצה שיתראה לזולתו ואם מראה לזולתו למה נק' בשם מה. אך הנה זה הביטול ממדרגות השפילות לגמרי שהוא מקור לקלי' שהם נגד רצונו ית' אלא מפני שה\"ה מחי' אותם וכמ\"ש ואתה מחי' את כולם<sup data-n=\"5865\">110</sup> ומפני החיות שבהם ע\"כ שיש בהם קצת ביטול. ועד\"ז יובן ביראה שיש יר\"ת ויש יר\"ע שהוא יראת הרוממות יראה בושת וכמו שמתבושש מאדם גדול אך כאשר מתבושש באמת בלתי שירמה א\"ע לזולתו, ויש עוד יראה השפילה כמ\"ש ותהי יראתם אותי מצות אנשים מלומדה<sup data-n=\"5866\">111</sup> והוא כנגד הביטול דראו מ\"ה. והנה",[["5856","102","<b>לא קאים אינש אדעתי' דרבי'</b>: ראה ע\"ז ה, ב. (לעיל בחלק המאמרים) מאמר ד\"ה וכל שיח השדה ספ\"א. מאמרי אדה\"א ויקרא ח\"ב ע' תמד. וש\"נ. תו\"ח בשלח ח\"א ריז, ג הערה 418. המשך וככה תרל\"ז ספל\"ה."],["5857","103","<b>והנחש הי' ערום</b>: בראשית ג, א."],["5858","*104","<b>שהלכה. . ששאלה. . ושאלה. . שידעה</b>: כ\"ה בהכת\"י."],["5859","104","<b>בא אחיך במרמה</b>: תולדות כז, לה. ראה גם סה\"מ ליקוט ח\"ג ע' קפה."],["5860","105","<b>ויעקבני</b>: תולדות שם, לו."],["5861","106","<b>נזכר שני</b>: אוצ\"ל: נזכר רק שני."],["5862","107","<b>יר\"ת ויר\"ע</b>: ראה גם תניא פמ\"ג. סידור הערה לתיקון חצות קנא, ג ואילך."],["5863","108","<b>אכן אתה אל מסתתר</b>: ישעי' מה, טו. ראה גם לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה אי' בירושלמי ובמדרש נביאים וכתובים ובהערה 33."],["5864","109","<b>ראו מ\"ה</b>: ראה וירא כב, כד. לעיל בהנחה ראשונה כאן הערה 104."],["5865","110","<b>ואתה מחי' את כולם</b>: נחמי' ט, ו."],["5866","111","<b>ותהי יראתם אותי מצות אנשים מלומדה</b>: ישעי' כט, יג. ראה גם לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה אי' בירושלמי ובמדרש נביאים וכתובים הערה 12."]]],[2000480546,"ביראה הגבוה מכולם עדיין צ\"ל ערום באותו היראה, דהנה כתיב מה ה' אלקיך שואל מעמך<sup data-n=\"5867\">112</sup> כו' והצנע לכת עם אלקיך<sup data-n=\"5868\">113</sup> דהיינו כאשר יבא לכל המדרגות הגבוהות בעבודה יהי' בבחי' הצנע לכת שלא יהיו בולטות האהוי\"ר שלו שאז יכול לגרום ליפול באיזה פניה ח\"ו, אבל כאשר אינו בולט אז הוא בבחי' מ\"ה כמו ועי\"ז יהי' הליכות עולם לו<sup data-n=\"5869\">114</sup> המשכת אלקותו ית' בעולם וזהו\"ע ערום ביראה.\n<b>והנה</b> מדריגת ערום ביראה במי תמצא במי שהוא עניו דהנה אי' בירושלמי מה שעשתה החכ'<sup data-n=\"5870\">115</sup> עטרה לראשה עשתה ענוה עקב לסוליסה (ל' נעל<sup data-n=\"5871\">116</sup> ) דכתי' ראשית חכ' יראת הוי'<sup data-n=\"5872\">117</sup> וכתי' עקב ענוה יראת ה'<sup data-n=\"5873\">118</sup> ופירשו מפרשי הקבלה עפ\"י פשוט כי יראה הוא יר\"ת מל' ובנין המל' הוא מהגבו'<sup data-n=\"5874\">119</sup> וזהו העטרה, וענוה הוא ת\"ת<sup data-n=\"5875\">120</sup> שהוא הגבה למעלה מגבו', אך באמת מדקדוק הל' עטרה לראשה משמע שענוה גדולה גם מעטרה שע\"ג ראשה והיינו כי העטרה הוא ח\"ס ואי' בהרמ\"ז שח\"ס דא\"א נחשב מכלל עולם האצי'<sup data-n=\"5876\">121</sup> ולכן הוא בבחי' עקב לגבי ענוה כי ענוה הוא ת\"ת דעתיק ולכן מי שהוא עניו לא איכפת לי' כלום ואינו חש למה שמדברים עליו ולכן מצינו כמה צדיקים גדולים שהיו חושבים א\"ע לאין, וכמו דהע\"ה שאמר ואנכי תולעת<sup data-n=\"5877\">122</sup> ולא כו' שעשה חשבון בנפשו דהנה כל מעלתו שהוא עוסק בשירות ותשבחות ותו' ותפלה בפיו הלא התולעת ג\"כ כחו בפיו<sup data-n=\"5878\">123</sup> ולכן אמר כי עני ואביון אני<sup data-n=\"5879\">124</sup>, אך דוד לא הי' רק מרכבה למדת המל'<sup data-n=\"5880\">125</sup>, אבל במרע\"ה כתי' והאיש משה עניו<sup data-n=\"5881\">126</sup> שהוא בחי' הענוה הגדולה מכולם וזהו שנמשכין כבהמה שהוא ביטול שלמעלה מהטו\"ד שהכל כבהמות לפניו. וזהו מ\"ש במד\"ר ע\"פ פתי יאמין לכל דבר<sup data-n=\"5882\">128</sup> זה",[["5867","112","<b>מה ה' אלקיך שואל מעמך</b>: לשון הכתוב עקב י, יב. ובמיכה (שבהערה הבאה) ומה ה' דורש ממך."],["5868","113","<b>והצנע לכת עם אלקיך</b>: מיכה ו, ח."],["5869","114","<b>הליכות עולם לו</b>: חבקוק ג, ו."],["5870","115","<b>אי' בירושלמי מה שעשתה החכ'</b>: ראה שם שבת פ\"א, סה\"ג."],["5871","116","<b>לסוליסה. . נעל</b>: ראה קרבן העדה שם."],["5872","117","<b>ראשית חכ' יראת הוי'</b>: תהלים קיא, י."],["5873","118","<b>עקב ענוה יראת ה'</b>: משלי כב, ד."],["5874","119","<b>ובנין המל' הוא מהגבו'</b>: ראה ע\"ח שער תיקון הנוקבא של\"ד, פ\"ה. מאמרי אדה\"א דברים ח\"א ע' ריח. וש\"נ. תו\"ח בשלח ח\"א רמד, א. וש\"נ. פלח הרמון אמור ע' רצא ואילך."],["5875","120","<b>וענוה הוא ת\"ת</b>: ראה פרדס שעה\"כ שכ\"ג, פט\"ז מערכת ענוה."],["5876","121","<b>ואי' בהרמ\"ז שח\"ס דא\"א. . האצי'</b>: ראה זהר אמור פח, סע\"ב ובהרמ\"ז שם. לעיל (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה כנשר יעיר קנו הערה 69."],["5877","122","<b>דהע\"ה שאמר ואנכי תולעת</b>: תהלים כב, ז."],["5878","123","<b>דהע\"ה. . כל מעלתו. . התולעת. . בפיו</b>: ראה לעיל בהנחה ראשונה כאן הערות 116-114."],["5879","124","<b>כי עני ואביון אני</b>: תהלים פו, א. ראה גם לעיל (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה אריב\"ל הנהו ך\"ו הודו על יד הערה 130 ואילך. סה\"מ תרל\"ח ע' נד. וש\"נ."],["5880","125","<b>דוד. . מרכבה למדת המל'</b>: ראה פרדס שעה\"כ שכ\"ג, פ\"ד מערכת דוד. הנסמן המאמרי אדה\"א דברים ח\"ג ע' תתקט."],["5881","126","<b>והאיש משה עניו</b>: בהעלותך יב, ג."],["5882","128","<b>פתי יאמין לכל דבר</b>: משלי יד, טו."]]],[2000480547,"משה<sup data-n=\"5883\">127</sup>, ולכאו' אינו מובן הלא משה רבן של כל הנביאים<sup data-n=\"5884\">129</sup> ונתנבא בזה<sup data-n=\"5885\">130</sup> אספה\"מ<sup data-n=\"5886\">131</sup> ומשה עלה בהר ולא אכל מ' יום<sup data-n=\"5887\">132</sup> והאיך אמרו עליו פתי יאמין כו', אך זהו מ\"ש בבינונים שלגבי א\"ס עצומ\"ה הכל כפתיים לפניו<sup data-n=\"5888\">133</sup>, וזהו בנ\"א שהם ערומים בדעת כאדה\"ר שהוא מדרגת ערום ביראה אז הוא בא למדריגת ענוה כזה שיהי' נמשך כבהמה, ועל ביטול זה קרן השופר שהוא קרן בהמה.\n<b>והסימן</b> במי שבא לזה ע\"ז אמר יעקב אבינו ע\"ה והי' ה' לי לאלקים, דהנה בכאו\"א מישראל יש בנפשו בחי' ה'<sup data-n=\"5889\">134</sup>, ה' ראשונה הוא התבוננו' בגדולת הבורא לאורך ורוחב והיו\"ד וקוש\"י הוא ביטול הרצון שלמעלה מטו\"ד וכמ\"ש כי עם קשה עורף<sup data-n=\"5890\">135</sup> משכיל לאיתן<sup data-n=\"5891\">136</sup> כו' ו\"ה הוא תו' ומצות או תפלה מדות ודבור. וזהו והי' הוי' לי לאלקים דכמו ששם אלקים מאיר בפנימי' כח הפועל בנפעל<sup data-n=\"5892\">137</sup> כמו\"כ יאיר שם ה' בפנימי' דהיינו שגם המקיף דחי' יאיר בפנימי' ויהי' לו בחי' יחידה, והגם שלכאו\"א מישראל יש יחידה<sup data-n=\"5893\">138</sup> אך כאשר הד' בחי' נרנ\"ח מאירים בפנימית אז ירגיש יחידה שבנפשו, וזכה לזה יעקב אבינו ע\"ה ע\"י שהי' אצל לבן והציל ממנו כל הניצוצות עקודים נקודים וברודים<sup data-n=\"5894\">139</sup> שהוא תיקון ותהו ולמעלה מהתהו, וזהו מ\"ש עם לבן גרתי וארז\"ל תומ\"צ שמרתי<sup data-n=\"5895\">141</sup>, כי גרתי בגימ' תרי\"ג<sup data-n=\"5896\">142</sup>, ועי\"ז בא לגילוי בחי' לובן העליון<sup data-n=\"5897\">140</sup>, ועי\"ז נמשך שם ה' בפנימית וממילא מאיר שם ה' שלמעלה מבחי' שם ה' זה, וזהו מ\"ש לשארית נחלתו<sup data-n=\"5898\">143</sup> וארז\"ל למי שמשים א\"ע כשיריים<sup data-n=\"5899\">144</sup> היינו שהמקיף מאיר בפנימי דכמו למשל בגשמיות<sup data-n=\"5900\">145</sup>",[["5883","127","<b>מ\"ש במד\"ר ע\"פ פתי יאמין. . משה</b>: שמו\"ר רפ\"ג. ראה קיצורים והערות לתניא ע' קא ואילך. סה\"מ תרל\"ג ח\"א ס\"ע קנא ואילך. המשך וככה תרל\"ז פמ\"ב (ע' נט)."],["5884","129","<b>משה רבן של כל הנביאים</b>: שמו\"ר פכ\"א, ד."],["5885","130","<b>משה. . ונתנבא בזה</b>: ראה ספרי ר\"פ מטות הובא ברש\"י שם. תו\"ח בשלח ח\"א קמד, ב הערה 29."],["5886","131","<b>משה. . אספה\"מ</b>: יבמות מט, ב. ראה גם לעיל ח\"א (בחלק המאמרים) מאמר ד\"ה נעשה אדם ספ\"א. תו\"ח ח\"ש קלא, ד."],["5887","132","<b>עלה בהר ולא אכל מ' יום</b>: עקב ט, ט. יח."],["5888","133","<b>מ\"ש בבינונים. . הכל כפתיים לפניו</b>: פי\"ח. ראה (לעיל בחלק המאמרים) בהמאמר כאן הערה 50."],["5889","134","<b>בכאו\"א מישראל. . בחי' ה'</b>: ראה גם (לעיל בחלק המאמרים) המשך יונתי פ\"ה. לעיל ח\"א (בחלק המאמרים) מאמר ד\"ה ואעשך לגוי גדול הערה 26."],["5890","135","<b>כי עם קשה עורף</b>: תשא לד, ט. ראה גם המשך יונתי שם."],["5891","136","<b>משכיל לאיתן</b>: תהלים פט, א."],["5892","137","<b>ששם אלקים. . כח הפועל בנפעל</b>: ראה גם לקו\"ת בחוקותי מט, ב. מאמרי אדה\"ז תקס\"ז ע' רי. ש\"א לו, א. פח, ב. פט, ב."],["5893","138","<b>שלכאו\"א מישראל יש יחידה</b>: ראה לקו\"ת פ' ראה כה, א. (לעיל בחלק המאמרים) מאמר ד\"ה ולהבין שרש ענין בחי' מזבח הפנימי פיסקא וביאור הענין ובהנסמן שם."],["5894","139","<b>עקודים נקודים וברודים</b>: ויצא לא, י. יב. ראה תו\"א נח י, ג ואילך."],["5895","141","<b>עם לבן גרתי. . תומ\"צ שמרתי</b>: וישלח לב, ה. ראה בהערה הבאה."],["5896","142","<b>גרתי בגימט' תרי\"ג</b>: רש\"י שם. בראשית רבתי לר' משה הדרשן שם."],["5897","140","<b>עם לבן. . לובן העליון</b>: ראה ע\"ח שער העקודים ש\"ו, פ\"א. מאמרי אדה\"א בראשית ע' רכב. וש\"נ. תו\"ח ויצא קסח, ד ובהערה 31."],["5898","143","<b>לשארית נחלתו</b>: מיכה ז, יח."],["5899","144","<b>למי שמשים א\"ע כשיריים</b>: ר\"ה יז, ריש ע\"ב."],["5900","145","<b>בגשמיות</b>: ע\"כ כתב והמשך העמוד הניח חלק. ראה המשך הענין לעיל בהנחה ראשונה כאן. (לעיל בחלק המאמרים) בהמאמר כאן."]]],[2000480548,"<h3>כנשר יעיר קנו</h3>\n<b></b><b>בס\"ד פ' האזינו תרמ\"א ליובאוויץ</b>\nהאזינו\n<b>כנשר</b> יעיר קנו<sup data-n=\"5901\">1</sup> על גוזליו ירחף יפרוש כנפיו יקחהו ישאהו על אברתו<sup data-n=\"5902\">2</sup>, ופי' המפרשים<sup data-n=\"5903\">3</sup> למה דוקא נשר כי מפני שנשר הוא מחולק משארי עופות כי שארי עופות שאינם פורחים גבוה מאוד ע\"כ נושאים את בניהם למטה מהם בין רגליהם מפני שיראים מפני העופות שפורחים למעלה מהם, אבל נשר שדרך הנשר בשמים<sup data-n=\"5904\">4</sup> ושמים הוא לרום<sup data-n=\"5905\">5</sup> שאינו מתיירא ממה שלמעלה הימנו אלא ממה שלמטה היינו מפני חיצים שבבני אדם לכן נושא את בניו על אברתו פי' על אברתו על גופו, וזהו במשל, וכן יובן בנמשל כי הנה כתי' ועל דמות הכסא<sup data-n=\"5906\">6</sup> דמות כמראה אדם, אף שאין לו גוף ולא דמות הגוף<sup data-n=\"5907\">7</sup> אך מ\"מ יש ציור דמות הגוף בתו' כמ\"ש וזאת התורה אדם<sup data-n=\"5908\">8</sup>, והן רמ\"ח מ\"ע ושס\"ה מל\"ת<sup data-n=\"5909\">9</sup> שרמ\"ח פקודין אינון רמ\"ח אברים דמלכא<sup data-n=\"5910\">10</sup>, ולכן נק' בש' אבר כמו אבר הוא כלי להשראת אור הנפש כמו\"כ מצות הם כלים להמשכות גילוי אלקות למטה, וע\"י ענין נשר מגיע אל בחי' על אברתו למעלה מענין בחי' המצות. וצ\"ל הלא מצות אף שהם רמ\"ח פקודין מצות פרטים, אך מ\"מ שרשן הוא בא\"ס בעל הרצון כמ\"ש נחת רוח לפני שאמרתי ונעשה רצוני<sup data-n=\"5911\">11</sup>, שפי' לפני קאי על א\"ס בעל הרצון<sup data-n=\"5912\">12</sup>, ואיך שייך לומר שע\"י ענין נשר מגיע לבחי' שהוא על אברתו למעלה מרצון העליון.\n<b>והענין</b> הוא כי מהו ענין נשר, נשר הו\"ע רחמים<sup data-n=\"5913\">13</sup> וזהו\"ע מ\"ש זכור רחמיך וחסדיך כי מעולם המה<sup data-n=\"5914\">14</sup> ונת' שאפי' כשאכשור<sup data-n=\"5915\">15</sup> דרא<sup data-n=\"5916\">16</sup> ג\"כ צריכין לזכות אבות, והעיקר זכות אבות הוא יעקב כי יעקב הוא המבריח מן הקצה אל הקצה<sup data-n=\"5917\">17</sup> שהי'",[["5901","1","<b>כנשר יעיר קנו</b>: הנחה ממאמר ד\"ה זה שנדפס לעיל בחלק המאמרים. וש\"נ.\nהנחת כ\"ק אדמו\"ר מהורש\"ב מדרוש זה נדפסה לעיל (בחלק הנחותיו)."],["5902","2","<b>כנשר יעיר. . על אברתו</b>: האזינו לב, יא."],["5903","3","<b>ופי' המפרשים</b>: (לעיל בחלק המאמרים) בהמאמר כאן מציין לרש\"י (עה\"פ — ראה גם מכילתא יתרו יט, ד)."],["5904","4","<b>שדרך הנשר בשמים</b>: משלי ל, יט."],["5905","5","<b>ושמים הוא לרום</b>: ע\"פ משלי כה, ג."],["5906","6","<b>ועל דמות הכסא</b>: יחזקאל א, כו."],["5907","7","<b>אף שאין לו גוף ולא דמות הגוף</b>: ע\"פ פיוט יגדל. ראה גם לעיל ח\"א (בחלק המאמרים) מאמר ד\"ה נעשה אדם ובהערה 31."],["5908","8","<b>וזאת התורה אדם</b>: חוקת יט, יד [ושם זאת[ednref_339_א]]. ראה זהר רע\"מ משפטים קיז, ב. צו כט, ב. תו\"א תרומה עט, ג. מאמרי אדה\"א דברים ח\"ד ע' א'שכז[ednref_340_ב]. וש\"נ."],["5909","9","<b>רמ\"ח מ\"ע ושס\"ה מל\"ת</b>: מכות כג, סע\"ב."],["5910","10","<b>שרמ\"ח פקודין אינון רמ\"ח אברין דמלכא</b>: ראה ת\"ז ת\"ל (עד, סע\"א). תניא רפכ\"ג. סידור שער החנוכה רפ, א. שע\"ת עב, ג הערה 17."],["5911","11","<b>נחת רוח. . רצוני</b>: ספרי שלח טו, ז. י. ראה לקו\"ש ויקרא כרך לב ע' 1. וש\"נ."],["5912","12","<b>לפני. . א\"ס בעל הרצון</b>: ראה גם לעיל הנחה ד\"ה לכל תכלה ראיתי קץ על יד הערה *96."],["5913","13","<b>נשר הו\"ע רחמים</b>: ראה לקו\"ת במדבר י, א. יא, ב. שה\"ש מט, ב. אוה\"ת האזינו ע' א'תרפה ואילך. קהלת יעקב מערכת נשר."],["5914","14","<b>זכור רחמיך. . המה</b>: תהלים כה, ו [בדילוג השם]."],["5915","15","<b>ונת' שאפי' כשאכשור דרא</b>: ראה לעיל (בחלק המאמרים) המשך יונתי פכ\"ד."],["5916","16","<b>כשאכשור דרא</b>: ע\"פ יבמות לט, ב. חולין צג, ב."],["5917","17","<b>יעקב הוא. . אל הקצה</b>: ע\"ד תרומה כו, כח. ראה זהר בשלח נא, ב. תרומה קעה, ב. הנסמן במאמרי אדה\"א שמות ח\"א ע' יט. סה\"מ תרכ\"ט ע' קיז. וש\"נ. תרנ\"ג ע' רנח ואילך.\n\n[edn_339_א] ראה גם סה\"מ תרל\"ח ע' תנ. וש\"נ.\n\n[edn_340_ב] וכן צ\"ל בסה\"מ תרל\"ח שם."]]],[2000480549,"מבריח מן קצה העליון עד קצה התחתון ולכן נק' יעקב נחלה בלי מצרים<sup data-n=\"5918\">18</sup>, וכמו שהי' מבריח מן הקצה אל הקצה כמו\"כ הי' מחבר חסד וגבורה כמ\"ש לולא אלקה אברהם אבי<sup data-n=\"5919\">19</sup> ופחד יצחק הי' לי, שהוא כולל שניהם והוא מדת הת\"ת<sup data-n=\"5920\">20</sup> שהוא<sup data-n=\"5921\">21</sup> מדת הרחמים<sup data-n=\"5922\">22</sup>. והענין מדת הרחמים לכאורה אינו שייך כ\"א על חסרון היינו שחסר לו פרט זה או פרט אחר או שחסר לו כלל, אבל על שלימות היינו שאינו חסר לו כלום אינו שייך רחמים עליו, אבל באמת שייך רחמים גם על שאינו חסר כי על כללות סדר השתל' העולמות<sup data-n=\"5923\">23</sup> שייך ג\"כ מדת רחמים, כי הנה כתי' מלכותך מל' כל עולמים<sup data-n=\"5924\">24</sup> ופי' ע\"פ פשוט שכללות כל העולמות הם רק מבחי' מל' לחוד, כי מלך שמו נק' עליהם<sup data-n=\"5925\">25</sup>. ובאמת לכאורה מהו פי' כל שהי' לו לומר מל' מל' עולמים, אלא כל הוא בגימט' נו\"ן<sup data-n=\"5926\">27</sup> שקאי על נו\"ן אלפים יובלות<sup data-n=\"5927\">26</sup> כי עכשיו הוא שית אלפי שנין<sup data-n=\"5928\">29</sup> דהוי עלמא וחד חרוב הוא שבעה, ולפי החשבון הזה יש שנה שמיטה ויובל<sup data-n=\"5929\">30</sup> ונו\"ן<sup data-n=\"5930\">28</sup> אלפים יובלות, וכתי' כל עולמים שאפי' העולמות שעתידין להיות בנו\"ן אלפים יובלות ג\"כ לא הי' רק ממדת המל', כי העולמות שעתידים להיות אין פי' שיתחדשו לגמרי כי באמת נאצלו מתחילה רק שהם בהעלם והוא ע\"ד עוה\"ז שמיד שעלה ברצונו לברוא את העולם מיד נברא<sup data-n=\"5931\">31</sup> רק שהי' בהעלם ואח\"כ נמשכו מהעלם אל הגילוי. וזהו בהי', כמו\"כ בעתיד בעולמות העתידים להיות בנ' אלפים יובלות נאצלו מתחילה רק שהם בהעלם ואח\"כ בזמן הנא\"י יומשכו מהעלם אל הגילוי.",[["5918","18","<b>נחלה בלי מצרים</b>: שבת קיח, סע\"א."],["5919","19","<b>לולא אלקה אברהם אבי</b>: ויצא לא, מב [ושם: לולי אלקי אבי אלקי אברהם]. ראה תו\"א תולדות יז, ג. לעיל ח\"א (בחלק המאמרים) מאמר ד\"ה ואעשך לגוי גדול ובהערה 109."],["5920","20","<b>והוא מדת הת\"ת</b>: ראה לעיל שם ובהערה 16."],["5921","21","<b>והוא. . מדת הרחמים</b>: ראה גם לעיל שם ובהערה 18."],["5922","22","<b>הת\"ת. . הרחמים</b>: ראה זח\"א בהשמטות רנא, ריש ע\"ב. פרדס שעה\"כ שכ\"ג, פ\"כ מערכת רחמים."],["5923","23","<b>רחמים. . על כללות. . העולמות</b>: ראה גם לקו\"ת במדבר ג, א. מאמרי אדה\"א דברים ח\"א ע' צג. וש\"נ. סה\"מ תרל\"ח ע' ח. וש\"נ. פיסקא הבאה."],["5924","24","<b>מלכותך מל' כל עולמים</b>: תהלים קמה, יג."],["5925","25","<b>מלך שמו נקרא עליהם</b>: ראה פיוט אדון עולם. לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה ישקני מנשיקות פיהו ובהערה 16."],["5926","27","<b>כל הוא בגימט' נו\"ן</b>: ראה מאו\"א מערכת היכל אות יא. לקו\"ת מטות פה, ב ובהנסמן במ\"מ לשם. מאמרי אדה\"ז תקס\"ד ע' כז ואילך."],["5927","26","<b>כל. . יובלות</b>: ראה גם לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה בן פורת יוסף הא' על יד הערות 19-20. המשך תער\"ב ח\"א ע' תרלא."],["5928","29","<b>שית אלפי שנין</b>: ראה ר\"ה לא, א. מאמרי אדה\"א בראשית ע' נג. וש\"נ."],["5929","30","<b>החשבון הזה. . שמיטה ויובל</b>: ראה גם לעיל (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן על יד הערה 26. תו\"ח מקץ ריז, ב הערה 20. שמות ח\"א א, ג ובהערה 35."],["5930","28","<b>נו\"ן אלפים יובלות</b>: ראה גם לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה בן פורת יוסף הא' ובהערה 20."],["5931","31","<b>שמיד שעלה ברצונו. . מיד נברא</b>: ראה גם לעיל ח\"א (בחלק המאמרים) המשך מצה זו פי\"ב ובהנסמן שם."]]],[2000480550,"<b>וע\"ז</b> כתי' מל' מל' כ\"ע שהם לא נמשכו רק ממדת המל' שהיא ש' והארה בעלמא שאינו פועל שינוי בעצם וזהו דכתי' אני הוי' לא שניתי<sup data-n=\"5932\">32</sup> אתה הוא קודם שנברא<sup data-n=\"5933\">33</sup> העולם ואתה הוא לאחר שנברא העולם שאין בו שום שינוי בין קודם הבריאה לאחר הבריאה. ולכאורה הלא קודם הבריאה לא הי' עולמות ואחר הבריאה נתהוה העולמות, אך מפני שלא נתהוה רק משם והארה בעלמא ע\"כ לא פועל שום שינוי בעצם. וע\"ז מתמא הנביא אני הוי' לא שניתי ואתם בני יעקב לא כליתם<sup data-n=\"5934\">34</sup>, הלא ע\"י ההתבוננות שאני הוי' לא שניתי שכללות השתל' העולמות לא פועל שום שינוי בעצם מחמת שנתהוה מש' והארה בעלמא הי' לכם לבוא לכלות הנפש, ואתם בני יעקב לא כליתם, אך התירוץ הוא מני' ובי' מחמת שאתם בני יעקב, פי' עקוב הלב ואנוש הוא<sup data-n=\"5935\">35</sup>, פי' חלישות וכמ\"ש עון עקבי יסובני<sup data-n=\"5936\">36</sup>, עבירות שאדם דש בעקבו<sup data-n=\"5937\">37</sup>, וכמ\"ש כי פנו אלי עורף<sup data-n=\"5938\">38</sup> פי' אף שפנו אלי שעושה מצות אך הם בבחי' עורף באחוריים וחיצוני', ע\"ד מצות אנשים מלומדה<sup data-n=\"5939\">39</sup>, וכל המצות עושים בקרירות ע\"כ מונע ומעכב מלבוא ע\"י ההתבוננות לכלות הנפש וממילא שייך ע\"ז ענין רחמים. וכן אפי' על עולמות עליונים עולמות הא\"ס שייך ג\"כ ענין רחמים, כי מאחר שהם עולמות שפי' הו\"ע העלם<sup data-n=\"5940\">40</sup> ה\"ה מעלים ומסתיר על א\"ס שבתוכו, ומאחר שנק' עולם ה\"ה יש. וזהו ידוע שכל יש מוכרח להיות שיש לו בחי' אין המחי' ומהוה אותו, והאין צריך להיות בהעלם מן היש, כי אם יהי' מושג האין להיש יהי' היש אין ואפס הי' כלא הי', ומאחר שהוא העלם שייך ע\"ז ענין רחמים. וכמו\"כ על אצי' אף שאצי' הוא אלקות<sup data-n=\"5941\">41</sup> ועל ע\"ס דאצי' כתי' שהוא אינון ואינון הוא<sup data-n=\"5942\">42</sup>, אך עכ\"ז מאחר שמוכרח לומר שהוא אינון ואינון הוא משמע שאפשר לומר באופן אחר, אך שבאמת הוא אינון ואינון הוא, שעל א\"ס עצמו\"ה אינו שייך לומר כן, ה\"ה העלם. ומה שאנו רואים שנק' ספי' לשון בהירה<sup data-n=\"5943\">43</sup> שהו\"ע גילוי ולא העלם, אך זה אינו אלא לגבינו",[["5932","32","<b>אני הוי' לא שניתי</b>: מלאכי ג, ו. ראה גם לעיל (בחלק המאמרים) המשך יונתי ובהערה 29."],["5933","33","<b>אתה הוא קודם שנברא</b>: ראה תפלת השחר. של\"ה תולדות אדם ג, ב. מאמרי אדה\"ז על מארז\"ל ע' שלו."],["5934","34","<b>ואתם בני יעקב לא כליתם</b>: המשך הכתוב אני ה' לא שניתי. ראה תו\"א יתרו סז, א. לעיל (בחלק המאמרים) המשך יונתי ובהערה 663."],["5935","35","<b>עקוב הלב ואנוש הוא</b>: ירמי' יז, ט [בדילוג]."],["5936","36","<b>עון עקבי יסובני</b>: תהלים מט, ו."],["5937","37","<b>עבירות שאדם דש בעקבו</b>: ראה של\"ה מס' תענית ר, ב. מסילת ישרים פ\"י. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תתצג. מאמרי אדה\"א הנחות תקע\"ז ע' קסו[ednref_341_ג]. סה\"מ תרל\"ח ע' שעט. לעיל (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן על יד הערה 34. וראה גם לעיל (בחלק המאמרים) המשך יונתי הערה 666."],["5938","38","<b>פנו אלי עורף</b>: ירמי' ב, כז. ראה גם לעיל (בחלק המאמרים) שם ובהערה 513."],["5939","39","<b>מצות אנשים מלומדה</b>: ישעי' כט, יג. ראה גם תניא פל\"ט (נג, ב). לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה אי' כו' נביאים וכתובים הערה 12."],["5940","40","<b>עולמות. . העלם</b>: ראה ספר הבהיר ס\"י. תו\"ח שמות ח\"א יח, ד הערה 783."],["5941","41","<b>שאצי' הוא אלקות</b>: ראה לעיל ח\"א (בחלק המאמרים) המשך מצה זו ובהערה 1599."],["5942","42","<b>שהוא אינון ואינון הוא</b>: ראה לעיל ח\"א (בחלק המאמרים) המשך זאת חנוכת המזבח פ\"ו הערה 102."],["5943","43","<b>ספי' לשון בהירה</b>: ראה לקו\"ת אמור לה, ב.\n\n[edn_341_ג] וכן צ\"ל בסה\"מ תרל\"ח המובא בפנים ההערה."]]],[2000480551,"אבל לגבי' ית' ה\"ז ענין העלם. וכן בברי' שעל ברי' כתי' מה גדלו מעשיך הוי' שקאי על מלאכים הגדולים<sup data-n=\"5944\">44</sup> שמלאך בשליש עולם הוא עומד<sup data-n=\"5945\">45</sup> ויש מלאכים שעומדים תמיד בביטול ואומרים ג\"פ קדוש ובכל קדוש עומדים שני אלפים שנה בביטול, אומרים פעם אחד קדוש ועומדים שני אלפים שנה בביטול, וכן בפעם שני', ועכשיו הם עומדים בביטול בפעם שלישי<sup data-n=\"5946\">46</sup> של קדוש, עכ\"ז יש להם גוף שמעלים ומסתיר על הנפש כמו באדם שהגוף הוא מעלים ומסתיר על עשר כוחות הנפש<sup data-n=\"5947\">47</sup> שלא יאירו בפנימי' כמו שהם בנפש, כמו\"כ אצל מלאכים הגוף שלהם מעלים ומסתיר. רק שבאדם הגוף שלו הוא מורכב מד' יסודות<sup data-n=\"5948\">48</sup> ואצל מלאכים הגוף שלהם הוא רק מב' יסודות<sup data-n=\"5949\">49</sup>, ומאיזה מהם מהדקות שבהם מאש ורוח כמ\"ש עושה מלאכיו רוחות<sup data-n=\"5950\">50</sup> משרתיו אש לוהט, אך עכ\"ז ה\"ה גוף. רק מ\"מ אינו שייך לקרות אצלם גוף ונפש אלא בש' אור וכלי אך עכ\"ז הכלי הוא מעלים ומסתיר ולכן ארז\"ל אפקוה למט\"ט<sup data-n=\"5951\">51</sup>, שמט\"ט הוא ממלאכים גדולים עכ\"ז שייך אצלו ענין דין ועונש והוא מצד הכלי שהוא מעלים ומסתיר, ומאחר שהו\"ע העלם שייך רחמים. וכש\"כ בעוה\"ז השפל והגשמי' ולא נדבר באלו שפגמו ח\"ו אלא אפי' צדיק שנקי מכל דבר חטא וליכלוך מ\"מ ה\"ה מלובש בגוף גשמי' והגוף הוא מעלים ומסתיר על אור הנפש שלא יאיר כמו שהוא. כי הנה מפני מה הי' ירידת הנשמה הוא בשביל לקיים תומ\"צ ואילו יצוייר שהנפש עצמה יכול לקיים מצות כמו שהיא בלא גוף הי' המעשים באופן היותר נעלה אך שמוכרח להיות שתתלבש בגוף, אך מ\"מ הרי הגוף הוא מעלים ומסתיר וממילא שייך ע\"ז רחמים.",[["5944","44","<b>מה גדלו מעשיך ה'. . הגדולים</b>: תהלים צב, ו. ראה (לעיל בחלק המאמרים) המשך יונתי ובהערה 120."],["5945","45","<b>שמלאך בשליש עולם הוא עומד</b>: ראה ב\"ר פס\"ח, יב. חולין צא, ב. לעיל ח\"א (בחלק המאמרים) מאמר ד\"ה ואעשך לגוי גדול הערה 44."],["5946","46","<b>ויש מלאכים. . ג\"פ קדוש. . בפעם שלישי</b>: ראה גם לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה ישקני מנשיקות פיהו ובהערה 24."],["5947","47","<b>עשר כחות הנפש</b>: ראה תו\"א תולדות יט, א. תניא פ\"ג."],["5948","48","<b>שבאדם הגוף. . מד' יסודות</b>: רמב\"ם הל' יסוה\"ת רפ\"ד."],["5949","49","<b>מלאכים הגוף. . מב' יסודות</b>: ראה תו\"א בראשית ד, ב. לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה ואתה תצוה ובהערה 18."],["5950","50","<b>עושה מלאכיו רוחות</b>: תהלים קד, ד."],["5951","51","<b>אפקוה למט\"ט</b>: חגיגה טו, א. ראה גם לעיל (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה כאן על יד הערה 41. לקו\"ת בהר מג, ד [ובמפתח ענינים שם מערכת בחירה — אג\"ק שלו חי\"ד ע' קמז]. מטות פז, א. סידור שער הק\"ש עג, ד[ednref_342_ד]. ביאוה\"ז בלק צט, ב. מאמרי אדה\"ז תקס\"ה ח\"א ע' יד. הנחות הר\"פ ע' קפו[ednref_343_ה]. מאמרי אדה\"א ויקרא ח\"ב ע' תרעא וע' תשכט. סהמ\"צ להצ\"צ ע' לו. אוה\"ת תבוא ע' תתרצג[ednref_344_ו]. איוב כרך א ע' תרס ואילך. סה\"מ תרכ\"ט ע' קסה. תרצ\"ז ע' 234. מאמר ד\"ה לדוד מזמור תרפ\"ב פ\"ה. אג\"ק כ\"ק אדמו\"ר מהוריי\"צ ח\"ב ע' שלה ואילך. ע' שלח. שיחת ש\"מ מ\"ח תשי\"ד ס\"י (שיחות קודש תשי\"ד — מהדורת תשס\"א — ע' 63).\n\n[edn_342_ד] אוה\"ת ואתחנן כרך ו ע' ב'רלג.\n\n[edn_343_ה] מאמרי אדה\"ז תקס\"ה ח\"ב ע' תתפו. ביאוה\"ז להצ\"צ כרך א ע' שצז. מאמר ד\"ה כבוד מלכותך יאמרו ר\"ה תשי\"ב.\n\n[edn_344_ו] והוא דרוש אדה\"ז מתקס\"ו."]]],[2000480552,"<b>והנה</b> למעלה כתי' יערוף כמטר<sup data-n=\"5952\">52</sup> לקחי תיזל כטל אמרתי, והנה ענין טל ומטר שענין מטר אנו רואים מהיכא נעשה מטר כתי' ואד יעלה מן הארץ<sup data-n=\"5953\">53</sup> שע\"י קיטורים ולחלוחית הארץ העולה למעלה נעשה מזה עננים והם שואבים מים מלמעלה ואח\"כ ירד מטר, וכמו\"כ יובן באדם שלהיות אצלו בחי' מטר יורד צריך להיות תחילה ואיד יעלה מן הארץ פי' איד הוא לשון שבירה<sup data-n=\"5954\">54</sup>, מן הארץ הוא גוף האדם שנברא מן הארץ כמ\"ש וייצר הוי' את האדם עפר מן האדמה<sup data-n=\"5955\">55</sup> שעפר הו\"ע ארץ צריך לשבור את גוף האדם, ואח\"כ יכול להיות בחי' מטר, וע\"ד שאמרו שברו הבריות את ערפם<sup data-n=\"5956\">56</sup> ומיד מטר ירדו<sup data-n=\"5957\">57</sup>, ופי' שברו הבריות את ערפם הוא כמ\"ש כי פנו אלי עורף שעושה המצוה בבחי' אחור מצד ההרגל מצות אנשים מלומדה ובקרירות והוא מפני שהגוף הוא חומר עב וגס לכן הוא מעלים ומסתיר על אור הנפש ופועל שכל מה שעושה יהי' בלא „ריינלייג, ואף שהנפש הוא שורה בתוך הגוף ובאמת הוא אור יקר אך מצד שהגוף הוא חומר עב וגס לכן אינו מאיר הנפש, וכמשל אבן טוב שמונח בתיבה של עץ אינו ניכר כלל בהירותו מצד שחומר העץ הוא מעלים ומסתיר שלא יהי' מאיר ומבהיק, כי אילו הי' מונח בכלי זכוכית הי' מאיר רק שהוא בתיבה של עץ שהוא חומר גס אינו מאיר, כמו\"כ הנפש אף שהוא אור יקר אך מפני שהוא מלובש בגוף חומר עב וגס מעלים ומסתיר עליו, ולזה צריך שבירת העורף. וכמו בארץ שלהיות הכנה למטר צריך קודם חרישה שחרישה היא מרפה לארעא<sup data-n=\"5958\">58</sup>, וענין החרישה הוא שמפררים ומחלקין רגבי האדמה שלא יהיו גוש אחד שאם יורד המטר על גוש עפר שאינו נחרש לא יהי' צומח, אף שצומח מ\"מ ה\"ז דוקא דשאים ועשבים, אבל כדי שיהי' ראוי למאכל אדם צריך לחרישה כמו\"כ באדם צריך להיות תחילה ענין חרישה שמפרר חומר הגוף, וזהו\"ע שברו הבריות את ערפם ואח\"כ מטר יורד. ובתקיעת שופר הו\"ע שברים כי תקיעה הוא קול פשוט אבל שברים הוא קולות קצרים שמפרידים את הקול לחלקים, ואחר השבירה יכול להיות מטר.\n<b>והנה</b> ענין מטר אין הפי' מטר גשמי' אלא הו\"ע תורה כמ\"ש כמטר לקחי. ובאמת הם ענין אחד כי ע\"י תורה ממשיכים מטר כמו שמצינו אצל הרשב\"י שבשעה שהעולם הי' צריכין למטר דרש על פסוק מה טוב ומה נעים<sup data-n=\"5959\">59</sup> שבת אחים גם יחד",[["5952","52","<b>יערוף כמטר</b>: האזינו לב, ב."],["5953","53","<b>ואד יעלה מן הארץ</b>: בראשית ב, ו. ראה גם המשך וככה תרל\"ז פס\"ו. פלח הרמון שה\"ש ע' פ."],["5954","54","<b>איד הוא לשון שבירה</b>: ראה ב\"ר פי\"ג, יב (ובמפרשים שם). ירושלמי תענית פ\"ב, ה\"א. מאמר ד\"ה כנשר יעיר קנו תשי\"ט."],["5955","55","<b>וייצר הוי'. . האדמה</b>: בראשית ב, ז [ושם: ה\"א]."],["5956","56","<b>שברו הבריות את ערפם</b>: ב\"ר פי\"ג, יד. ראה גם (לעיל בחלק המאמרים) בהמאמר כאן הערה 20."],["5957","57","<b>ירדו</b>: כנשצ\"ל: יורד. וכ\"ה בקרוב לסיום פיסקא זו."],["5958","58","<b>שחרישה היא מרפה לארעא</b>: ראה מועד קטן ב, ב. לקו\"ת האזינו עה, ד. שה\"ש לח, ד. שע\"ת סג, ב ואילך. המשך מים רבים תרל\"ו פקכ\"ו."],["5959","59","<b>מה טוב ומה נעים</b>: תהלים קלג, א. ראה זהר אחרי נט, ב. מאמרי אדה\"ז אתהלך לאזניא ע' רי ואילך. אוה\"ת אחרי ע' רנד ואילך[ednref_345_ז]. מאמרי אדמו\"ר הצ\"צ הנחות תרי\"ד ע' יד. סה\"מ תרכ\"ז ע' רצא ואילך. וש\"נ.\n\n[edn_345_ז] נדפס גם בביאוה\"ז להצ\"צ כרך ב ע' תתקכא ואילך."]]],[2000480553,"שעי\"ז פעל יחודים למעלה ועי\"ז ירד מטר למטה כי באמת תורה וגשם הו\"ע אחד כי תו' הו\"ע אור כמ\"ש כי נר מצוה ותורה אור<sup data-n=\"5960\">60</sup>, וגשם הוא ג\"כ ענין אור כמארז\"ל כל האור<sup data-n=\"5961\">62</sup> האמור באלי'<sup data-n=\"5962\">61</sup> בירידת גשמים הכתוב מדבר, כי מה שלמעלה הוא אור למטה הו\"ע גשמים, והראי' הוא ממ\"ש והי' אור הלבנה כאור החמה<sup data-n=\"5963\">63</sup> ואור החמה שבעתים כאור שבעת הימים ופי' רש\"י<sup data-n=\"5964\">64</sup> שאור יום אחד יהי' זפ\"ז שהוא מ\"ט, וז' פעמים שבעת הימים הרי ז' פעמים מ\"ט הוא שמ\"ג אותי' גשם. ולכן ארז\"ל כל המשתמש באור תורה<sup data-n=\"5965\">65</sup> אור תורה מחייהו, ועש\"ז נק' תורה בש' גשם כמו שגשם הוא מביא חיים לעולם כמו\"כ תורה היא מביאה חיים לעולם, וזהו\"ע מטר שנמשך מז' תחתוני' דעתיקא<sup data-n=\"5966\">66</sup>, אבל טל הוא מדריגה גבוה כי טל הוא כמאמר טל דנטיף מעתיקא<sup data-n=\"5967\">67</sup> שהוא מד' גבוה יותר ממקור ושרש נשמות ישראל, שמקור נש\"י היא רק מבחי' שיורא טלא<sup data-n=\"5968\">68</sup> דבדולחא<sup data-n=\"5969\">69</sup>, וענין שיורא הוא לא כמו שנת' למעלה<sup data-n=\"5970\">70</sup> שמה שלא נמשך בפנימי' נשאר בבחי' מקיף שהוא מד' גבוה, אלא פי' שיורא כפשוטו ואף שאי' ברמ\"ז שמחכ' סתימאה דאריך הוא שורש ומקור לנאצלים<sup data-n=\"5971\">71</sup> ושרש נש\"י הוא מגלגלתא דחפי' על מוחא<sup data-n=\"5972\">*72</sup> אך זהו רק מב' מזלות נוצר ונקה<sup data-n=\"5973\">72</sup> שהו\"ע צמצומים דשערות, ובחי' טל הוא מד' גבוה יותר כי הוא טלא דנטיף מעתיקא והו\"ע טל תחי'<sup data-n=\"5974\">73</sup> כמו שאי' באגרת<sup data-n=\"5975\">74</sup> אשר משיורא טלא<sup data-n=\"5976\">75</sup> הוא רק לטהר טמא מת פי' שמדחה הטומאה אבל לא להחיות את המת אבל טל הוא מד' שעתיד להחיות בו את המתים והוא מג' ראשונות דעתיקא<sup data-n=\"5977\">76</sup>. ובתורה הו\"ע מארז\"ל שלש שעות ראשונות הקב\"ה יושב ועוסק בתורה<sup data-n=\"5978\">77</sup> שזהו ענין",[["5960","60","<b>כי נר מצוה ותורה אור</b>: משלי ו, כג."],["5961","62","<b>האור</b>: אוצ\"ל: אורה."],["5962","61","<b>כל האור האמור באלי'</b>: בב\"ר ספכ\"ו: כל אורה שנאמר באליהוא אינה אלא בירידת גשמים. ראה לעיל (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה יונתי ובהערה 113."],["5963","63","<b>והי' אור הלבנה כאור החמה</b>: ישעי' ל, כו [בדילוג]."],["5964","64","<b>ופי' רש\"י</b>: ראה ישעי' שם. סה\"מ תרל\"ח ע' קס. וש\"נ. לעיל שם ובהערה 115."],["5965","65","<b>כל המשתמש באור תורה</b>: כתובות קיא, ב. ראה גם הנסמן בסה\"מ תרל\"ח ע' רצב."],["5966","66","<b>מטר שנמשך מז' תחתוני' דעתיקא</b>: ראה גם לעיל (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן. המשך וככה תרל\"ז פס\"ז."],["5967","67","<b>טל דנטיף מעתיקא</b>: ראה זהר בשלח סא, ב. סב, ב. יתרו פג, א. פח, א. אד\"ז האזינו רפח, א."],["5968","68","<b>שמקור נש\"י. . שיורא טלא דבדולחא</b>: ראה לקו\"ת האזינו עג, ג."],["5969","69","<b>שיורא טלא דבדולחא</b>: זהר ויקרא מט, א."],["5970","70","<b>שנת' למעלה</b>: מאמר ד\"ה שובה ישראל (סביבות הערה 45)."],["5971","71","<b>שאי' ברמ\"ז שמחכ' סתימאה דאריך. . לנאצלים</b>: ראה גם לעיל (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן הערה 69."],["5972","*72","<b>מגלגלתא דחפי' על מוחא</b>: ראה זהר אד\"ר נשא קכח, ב."],["5973","72","<b>מב' מזלות נוצר ונקה</b>: ראה לקו\"ת האזינו עג, ג. סה\"מ תרל\"ח ע' קג. וש\"נ. ע' שצז. לעיל (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן."],["5974","73","<b>טל תחי'</b>: ראה שבת פח, ב."],["5975","74","<b>שאי' באגרת</b>: כנצ\"ל: שאי' באגרת הקדש."],["5976","75","<b>שאי' באגרת הקדש אשר משיורא טלא</b>: סכ\"ח [ושם: טלא דבדולחא — ראה לקו\"ת האזינו שם. המשך מים רבים תרל\"ז פקע\"ה. לעיל (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן]."],["5977","76","<b>טל. . מג' ראשונות דעתיקא</b>: ראה גם מאמרי אדה\"ז תקס\"ד ע' קסא. אוה\"ת שה\"ש ח\"ב ע' תקי — תקיב. סה\"מ תרכ\"ז ע' תסד. תר\"ל ע' פט. תרל\"ב ח\"ב ע' תקע."],["5978","77","<b>שלש שעות. . ועוסק בתורה</b>: ראה ע\"ז ג, ב."]]],[2000480554,"אתעדל\"ע בלא אתעדל\"ת<sup data-n=\"5979\">78</sup>, כי אי' בגמ' כל היושב ועוסק בתורה הקב\"ה קורא ושונה כנגדו<sup data-n=\"5980\">79</sup> שזהו אתעדל\"ת ואח\"כ אתעדל\"ע<sup data-n=\"5981\">80</sup> אבל כאן הוא שהקב\"ה יושב ועוסק בתורה הו\"ע אתעדל\"ע בלא אתעדל\"ת שהו\"ע מתנה. אך עכ\"ז הנה אנו רואים שאין נותנים מתנה אלא למי שראוי<sup data-n=\"5982\">81</sup>, וכאן אם הקדים בחי' אם יערוף כמטר לקחי מקודם אז נותנין לו במתנה הטל שבתורה יש ג\"כ בחי' הטל. אך הנה הגוף החומרי הנה הוא מעלים ומסתיר כי לא יוכל להזדכך כראוי שיעלה במד' הטל כי אחר כל ההזדככות והביטושים שיקבל עכ\"ז נשאר בחומרי' הגוף שלכן מצינו במשה רבינו ע\"ה כשעלה למרום נשאר גופו ביצי'<sup data-n=\"5983\">82</sup> רק דוקא אלי' לבד עלה בסערה השמימה עם גופו<sup data-n=\"5984\">83</sup> והוא מפני שהוא הי' זיכוך חיצוני' דש' ב\"ן<sup data-n=\"5985\">84</sup> והוא ע\"י שהי' י\"ב חודש בעיבור<sup data-n=\"5986\">85</sup> ולכן כדי שיתעלה גם הגוף לבחי' טל צ\"ל בחי' כנשר שהו\"ע התעוררות רחמים ועי\"ז יכול גם הגוף לעלות לבחי' טל. והוא ע\"ד שמצינו במ\"ת שכתי' ואשא אתכם על כנפי נשרים<sup data-n=\"5987\">86</sup> שלכאורה אינו מובן מה היו צריכים אז למדת הרחמים הלא הי' קודם מ\"ת שאינו שייך חטא ועון<sup data-n=\"5988\">87</sup> ולמה הי' צריכים אז לבחי' רחמים, אך מפני שבנ\"י הי' במצרים שקועים במ\"ט שערי היפך<sup data-n=\"5989\">88</sup> ולאחר נ' יום הי' צריכים לקבל את התורה<sup data-n=\"5990\">89</sup>, ולהיות כי ברח העם<sup data-n=\"5991\">90</sup> שהרע הי' בתקפו רק שהם ברחו מהרע וכדי שלהיות ויחן ישראל נגד ההר<sup data-n=\"5992\">91</sup> כפה עליהם הר כגיגית<sup data-n=\"5993\">92</sup> שהוא בחי' אה\"ר לכן הי' צריכים לבחי' רחמים.\n<b>והנה</b> עכשיו עיקר גילוי בחי' נשר שהו\"ע רחמים הוא מתגלה ע\"י בכי' בעשי\"ת ולכן אי' בכהאריז\"ל כל מי שאינו בוכה<sup data-n=\"5994\">93</sup> בר\"ה וביוה\"כ אין נשמתו שלימה",[["5979","78","<b>אתעדל\"ע. . אתעדל\"ת</b>: נסמן להלן הערה 80."],["5980","79","<b>אי' בגמ' כל היושב ועוסק. . כנגדו</b>: ראה תדא\"ר רפי\"ח. מאמרי אדה\"א דברים ח\"ב ע' שפז. וש\"נ. תו\"ח וארא ח\"א נח, ג. וש\"נ."],["5981","80","<b>אתעדל\"ת. . אתעדל\"ע</b>: ראה זהר לך פח, א. מאמר ד\"ה לרוקע נדפס במאמרי אדה\"ז תקס\"ב ח\"א ע' קצד [ובמקביליו ובהנסמן במ\"מ לשם]. מאמרי אדה\"א דברים ח\"א ע' קצח. וש\"נ. תו\"ח שמות ח\"א מא, א ובהערה 189."],["5982","81","<b>מתנה אלא למי שראוי</b>: ראה מגילה כו, ב. גיטין נ, ב. ב\"מ טז, א. ב\"ב קנו, א."],["5983","82","<b>במשה. . גופו ביצי'</b>: ראה גם (לעיל בחלק המאמרים) בהמאמר כאן ובהערה 14."],["5984","83","<b>אלי' לבד עלה בסערה. . עם גופו</b>: מלכים-ב ב, יא. ראה גם לעיל שם ובהערה 17."],["5985","84","<b>אלי'. . דש' ב\"ן</b>: ראה פע\"ח שער הק\"ש ש\"ח, פ\"ח. לעיל ח\"א (בחלק המאמרים) המשך מצה זו ובהערה 156."],["5986","85","<b>אלי'. . י\"ב חודש בעיבור</b>: ראה גם (לעיל חלק המאמרים) בהמאמר כאן ובהערה 16."],["5987","86","<b>ואשא אתכם על כנפי נשרים</b>: יתרו יט, ד."],["5988","87","<b>קודם מ\"ת שאינו שייך חטא ועון</b>: ראה ערכין טו, א ואילך."],["5989","88","<b>במצרים שקועים במ\"ט שערי היפך</b>: ראה ז\"ח יתרו לא, א. לעיל ח\"א (בחלק המאמרים) המשך מצה זו ובהערה 387."],["5990","89","<b>ולאחר נו\"ן יום. . את התורה</b>: ראה (לעיל ח\"א בחלק המאמרים) המשך מצה זו ובהערה 1217."],["5991","90","<b>כי ברח העם</b>: בשלח יד, ה. ראה תניא פל\"א."],["5992","91","<b>ויחן ישראל נגד ההר</b>: יתרו יט, ב (בדילוג]."],["5993","92","<b>כפה עליהם הר כגיגית</b>: שבת פח, א. ראה תו\"א מג\"א צח, ד. ש\"א ב, ב הערה 33."],["5994","93","<b>כל מי שאינו בוכה</b>: ראה פע\"ח שער השופר שכ\"ו, פ\"ה. לקו\"ש האזינו כרך ט ע' 206. מאמרי אדה\"א דברים ח\"א ע' שיט. וש\"נ. תו\"ח וישב ר, ג הערה 35."]]],[2000480555,"ולכאורה צ\"ל מהו\"ע הבכי' ומהו אין נשמתו שלימה. הענין הוא כי הנשמה הו\"ע שליח מהמשלח וידוע שהשלימות השליחות נגמר כאשר השליח עושה שליחותו וחוזר למשלחו ואומר עשיתי כל אשר צויתני, וזהו גמר השליחות, כמו\"כ הנשמה היא שליח שנשלח מהמשלח להחיות האדם ובקיום תומ\"צ והיא צריכה לחזור ולעלות למעלה לומר שעשתה כל שליחותה ובד\"פ ההחזרה היא בלילה בעת השינה שאז הנשמה עולה למעלה ונשאר רק קושטא<sup data-n=\"5995\">94</sup> דחיותא<sup data-n=\"5996\">95</sup> והעלי' הוא ע\"י ק\"ש בידך אפקיד רוחי<sup data-n=\"5997\">96</sup> שהעלי' הו\"ע פקדון וכמו שבהפקדון<sup data-n=\"5998\">97</sup> צריך להיות שיהי' נקי כמו\"כ צריך לעשות חשבון הנפש בינו לבין קונו מכל המחשבות ודיבורים ומעשים וימצא מהם אשר לא לה' המה וע\"ז צריך תשובה וחרטה גמורה כי למה יעלה<sup data-n=\"5999\">98</sup> זאת עס איז ד ך נישט, וע\"ז הוא הבכי' ואז הוא<sup data-n=\"6000\">99</sup> עולה ושואבת לה חיים<sup data-n=\"6001\">100</sup> ממקור החיים, וכמו שהוא בפרט כך הוא צריך להיות בכלל שער\"ה עם חשוכא<sup data-n=\"6002\">101</sup> הוא הסתלקות החיות שנשלח מהמשלח להחיות האדם בקיום תומ\"צ שעיקר קיום העולמות הוא על<sup data-n=\"6003\">102</sup> תומ\"צ כמ\"ש אם לא בריתי<sup data-n=\"6004\">103</sup> יומם ולילה חוקות ארץ ושמים לא שמתי וכמ\"ש אנכי עשיתי ארץ<sup data-n=\"6005\">104</sup> ואדם עלי' בראתי שבראתי הוא בגימט' תרי\"ג<sup data-n=\"6006\">105</sup> שעיקר קיום העולמות הוא בשביל תומ\"צ, ע\"כ אז צריך ג\"כ לעשות חשבון הנפש מכל הדיבורים והמעשים אשר לא לה' המה שעשה במשך השנה הזו שע\"ז צריך תשובה וחרטה גמורה שהו\"ע עקירת הרצון, ואפי' צדיק גמור שנקי מכל חטא שייך ג\"כ לענין חשבון הנפש<sup data-n=\"6007\">106</sup> כי בודאי ימצא אצלו חטא ולכלוך כי אין צדיק בארץ אשר לא יחטא<sup data-n=\"6008\">107</sup> ובפרט ענין ביטול ד\"ת<sup data-n=\"6009\">108</sup> שאפשר לעסוק בד\"ת ולא עסק<sup data-n=\"6010\">109</sup>, ואפי' כשהוא מנוקה מכל ואפי' מביטול תורה מ\"מ צריך לעשות חשבון הנפש מפני שצריך לחזור",[["5995","94","<b>קושטא</b>: וכ\"ה גם לעיל הנחה ד\"ה יפה שעה אחת על יד הערה 91. אוצ\"ל: קיסטא."],["5996","95","<b>קיסטא דחיותא</b>: ראה גם (לעיל בחלק המאמרים) המשך יונתי ובהערה 225."],["5997","96","<b>בידך אפקיד רוחי</b>: תהלים לא, ו. ראה גם לעיל שם ובהערה 489."],["5998","97","<b>פקדון. . שבהפקדון</b>: בהכת\"י: פקודין. . שבהפקודין."],["5999","98","<b>יעלה</b>: כ\"ה בהכת\"י."],["6000","99","<b>הוא</b>: אוצ\"ל: היא."],["6001","100","<b>היא עולה ושואבת לה חיים</b>: ראה (לעיל בחלק המאמרים) בהמשך יונתי הערה 490."],["6002","101","<b>שערב ר\"ה עם חשוכא</b>: ראה אגה\"ק סי\"ד (קכ, ב. קכא, רע\"א). לקו\"ת ר\"ה נג, ד. (לעיל בחלק המאמרים) מאמר ד\"ה רני ושמחי על יד הערה 32. המשך וככה תרל\"ז רפפ\"א. סה\"מ תשי\"א ע' 33. סה\"מ מלוקט ה' ע' ה. לקו\"ש האזינו כרך ט ע' 220."],["6003","102","<b>על</b>: אוצ\"ל: ע\"י."],["6004","103","<b>אם לא בריתי</b>: ירמי' לג, כה [ושם: שמים וארץ]. ראה שבת לג, א. לעיל הנחה ד\"ה יפה שעה אחת הא' על יד הערה 25 ואילך."],["6005","104","<b>אנכי עשיתי ארץ</b>: ישעי' מה, יב."],["6006","105","<b>שבראתי הוא בגימט' תרי\"ג</b>: ראה רמ\"ז לזהר ויגש רה, ב. לעיל ח\"א (בחלק המאמרים) המשך מצה זו הערה 1688."],["6007","106","<b>צדיק גמור. . חשבון הנפש</b>: ראה גם לעיל הנחה ד\"ה שובה ישראל (הא' והב' על יד הערות 70. 69). (לעיל בחלק המאמרים) המשך יונתי פכ\"ג. מאמר ד\"ה רני ושמחי בשולי היריעה פיסקא או."],["6008","107","<b>אין צדיק בארץ. . יחטא</b>: קהלת ז, כ [בדילוג]. ראה גם לקו\"ת פ' ראה ל, ג ואילך. שע\"ת עד, ב הערה 31. עח, ג. מאמרי אדה\"א קונטרסים ע' תיד. סה\"מ תרל\"ב ח\"ב ע' תקפד. המשך תער\"ב ח\"ג ע' א'תנט. סה\"מ תש\"ח ע' 255. סה\"מ מלוקט א' ע' רצב."],["6009","108","<b>ענין ביטול תורה</b>: ראה לעיל הערה 106."],["6010","109","<b>שאפשר לעסוק. . עסק</b>: ע\"פ סנהדרין צט, א."]]],[2000480556,"ולומר שעשה כל אשר ציוהו המשלחו, וממילא שייך אצלו דין וחשבון. וזהו כל מי שאינו בוכה בר\"ה וביוהכ\"פ אינו נשמתו שלימה, פי' כי מאחר שאינו בוכה<sup data-n=\"6011\">110</sup> אין החזרה כדבעי וממילא אינו עולה למעלה ושואבת לה חיים וזהו אין נשמתו שלימה. וענין הבכי' אצל צדיקים גמורים הוא ע\"ד שאמרו מים תחתונים בוכים<sup data-n=\"6012\">111</sup> אנן בעינן למהוי קדם מלכא.\n<b>ולהבין</b> זה הלא לכאורה לא נשפלו ברע גמור ח\"ו. אך הענין הוא כי עד שלא נברא העולם הי' מים במים<sup data-n=\"6013\">112</sup>, שמים תחתונים הי' כלול במים עליונים, פי' שמים עליונים לא הי' בתכלית העילוי ומים תחתונים לא הי' בתכלית השפלות. ומשנברא העולם כתי' יהי רקיע<sup data-n=\"6014\">113</sup> בתוך המים ויהי מבדיל בין מים למים שמים העליונים נתעלו בתכלית העילוי כמארז\"ל כשתגיע לאבני שיש אל תאמרו מים מים<sup data-n=\"6015\">114</sup>, ומים תחתונים נשפלו בתכלית השפלות שמהם נמשך כל מיני תענוג הבלי עולם. אך אם הי' האכילה כראוי היינו שכשישראל אוכל או שותה ומברך עלי' ה\"ה מעלה אותה אך אם אוכל ע\"ד מבטן רשעים תחסר<sup data-n=\"6016\">115</sup> אז הוא מורידה אשר ע\"ז הירידה הם בוכים למה ירדו להחיות דבר כזו אשר יהי' אפשר בהם היפך הכוונה. נמצא שהבכי' הוא לא על ההשפלה אלא על הירידה. כמו\"כ ענין ירידת הנשמה בגוף שהיא ג\"כ ענין ירידה גדולה ועצומה שיתבונן שנשמה היא חלק אלקה ממעל<sup data-n=\"6017\">116</sup> כי חלק הוי' עמו<sup data-n=\"6018\">117</sup>, חלקי הוי' אמרה נפשי<sup data-n=\"6019\">118</sup>, ועכשיו שהיא ירידה בגוף גשמי חומר עב וגס שהי' ירידה צורך עלי', אלא שאפשר להיות שלא די שלא מעלה אותה אלא מורידה שחוטא ופוגם, שעל הירידה הזו שייך הבכי' למה נתלבשה להחיות גוף כזו וע\"ז שייך הבכי', וזהו כשלא פגם וכש\"כ כשפגם בפועל ממש צריך לתשובה וחרטה גמורה. והנה תשובה וחרטה הוא כמו שאמר רבינו נ\"ע משל ע\"ז כמו ההולך לרחוץ בנהר וטובע בהנהר בודאי הוא מתחרט<sup data-n=\"6020\">119</sup> למה הלך לרחוץ שזהו חרטה גמורה. ובאמת המשל הוא דומה לנמשל כי הנה ארז\"ל<sup data-n=\"6021\">120</sup> מים רבים לא יכלו לכבות את האהבה, מים רבים הם ריבוי טרדות הפרנסה<sup data-n=\"6022\">121</sup> והם לא יכלו לכבות את",[["6011","110","<b>אינו נשמתו שלימה. . בוכה</b>: ראה גם מאמרי אדה\"א דברים ח\"ב ע' תקו ואילך."],["6012","111","<b>מים תחתונים בוכים</b>: ראה ת\"ז ת\"ה (יט, ב). לעיל ח\"א (בחלק המאמרים) המשך זאת חנוכת המזבח פי\"ט. וש\"נ."],["6013","112","<b>עד שלא נברא. . מים במים</b>: ראה ב\"ר פ\"ה, ב. לעיל ח\"א (בחלק המאמרים) מאמר ד\"ה כמגדל דוד צוארך ובהערה 5."],["6014","113","<b>יהי רקיע</b>: בראשית א, ו. ראה לעיל שם ובהערה 13."],["6015","114","<b>כשתגיע. . מים מים</b>: ראה חגיגה יד, א."],["6016","115","<b>מבטן רשעים תחסר</b>: ע\"פ משלי יג, כה."],["6017","116","<b>שנשמה היא חלק אלקה ממעל</b>: ראה איוב לא, ב. תניא רפ\"ב. לעיל ח\"א (בחלק המאמרים) המשך מצה זו ובהערה 395."],["6018","117","<b>חלק ה' עמו</b>: האזינו לב, ט."],["6019","118","<b>חלקי ה' אמרה נפשי</b>: איכה ג, כד."],["6020","119","<b>שאמר רבינו נ\"ע משל. . וטובע בהנהר. ֿ. מתחרט</b>: ראה גם בשם אדה\"ז לעיל (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן על יד הערה 100. המשך וככה תרל\"ז פע\"א [ושם: שארז\"ל שאמר רבינו ז\"ל].\nראה גם (לעיל בחלק המאמרים) בהמאמר כאן על יד הערה 37. (לעיל בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה אני לדודי הב' על יד הערה 106. מאמר ד\"ה כנשר יעיר קינו תשכ\"ה ס\"ב. וש\"נ."],["6021","120","<b>ארז\"ל</b>: אמר רבינו ז\"ל."],["6022","121","<b>מים רבים. . טרדות הפרנסה</b>: שה\"ש ח, ז. תו\"א ר\"פ נח."]]],[2000480557,"האהבה כי מדת אהבה היא מסותרת בלב כאו\"א מישראל שאפי' קל שבקלים<sup data-n=\"6023\">122</sup> יש לו מס\"נ<sup data-n=\"6024\">123</sup> על קדה\"ש. והנה ענין מים רבים שהוא ריבוי טרדת הפרנסה שטרוד ומוטרד שהולך ועוסק וחושב אז ער וועט פאר חאפין פאר לויפן פאר טאן, ובאמת פאר לויפט מען ניט און מען פאר חאפט ניט אדרבא תחבולות שאט גאר<sup data-n=\"6025\">124</sup>, כי בתחבולות תעשה לך מלחמה, שצריך לידע שהוי' אלקיך הוא הנותן לך כח לעשות חיל<sup data-n=\"6026\">125</sup> והנה הוא טרוד ומוטרד בטרדת הפרנסה שעי\"ז עפ\"י רוב שגם המצוה שעושה אינו כדבעי שאין לו פנאי וגם אפשר שיעבור על מ\"ע לגמרי ועוד קשה יותר, נמצא שאדם כזו שרואים שהולך כל היום משומם נוכל לומר עליו שהמים רבים שלטו עליו וע\"ז הוא צריך תשובה וחרטה גמורה וזהו\"ע בכי'. וזהו כשעשה תשובה שייך שם ענין בכי' אך הנה אפי' כשלא עשה תשובה שייך ג\"כ ענין בכי' שע\"ז כתי' עוברי בעמק הבכה<sup data-n=\"6027\">126</sup> מעין ישיתוהו ויש בו ב' פי' הא' הוא על המיוסרים ביסורי הנפש בגיהנום<sup data-n=\"6028\">127</sup> שבוכים עד אשר נעשים מעינות מדמעותיהם, ועוד פי' בו שהוא קאי על עולי רגלים<sup data-n=\"6029\">128</sup> שעשו בשבילם מעיינות, ולחבר ב' הפי' הנה ממה שמיסרים אותם יסורי הנפש ובזה פועלים הזדככות בנפש עד אשר מהמעיינות נעשים ממעיני הישועה וכמ\"ש ושאבתם מים בששון<sup data-n=\"6030\">129</sup> שמשם הי' שואבים רוח הקודש<sup data-n=\"6031\">130</sup> תמיד כמעין הנובע תמיד. וזהו אם לא עשה תשובה אבל אם עשה תשובה מועלת לו ששב ורפא לו<sup data-n=\"6032\">131</sup>, כי מה שאי' בספרים שתשובה אינו מועלת<sup data-n=\"6033\">132</sup> לאיזה חטאים היינו תשובה תתאה אבל תשובה עילאה בודאי מועיל. וענין התשובה עילאה הוא בנקל לכל בר ישראל להגיע אליה כי הו\"ע התקשרות בתורה כמ\"ש בתדב\"א הי'",[["6023","122","<b>קל שבקלים</b>: ע\"פ ר\"ה כה, ב. תוספתא שם ספ\"א. קה\"ר פ\"א ד [ד]. רש\"י ויצא כט, כא."],["6024","123","<b>קל שבקלים. . מס\"נ</b>: ראה תניא פי\"ח. מאמרי אדה\"א הנחות תקע\"ז ע' קלד. וש\"נ. לקו\"ש חנוכה כרך ג ע' 818 בהערה. סה\"מ מלוקט ד' ע' קפח בהערה."],["6025","124","<b>תחבולות שאט גאר</b>: ראה גם סהמ\"צ להצ\"צ ע' 214. מאמרי אדה\"ז תקס\"ה ח\"ב ע' תרנו (נוסחא שני'): ”והמשכילי' יבינו השעור והערך בזה\". וראה גם דרך חיים ע' 6."],["6026","125","<b>שהוי' אלקיך. . חיל</b>: עקב ח, יח."],["6027","126","<b>עוברי בעומק הבכא</b>: תהלים פד, ז."],["6028","127","<b>פי' הא'. . בגיהנום</b>: ראה ערובין יט, א. שמו\"ר פ\"ז, ד. מדרש תהלים פד, ג."],["6029","128","<b>ועוד פי'. . עולי רגלים</b>: ראה מצודת דוד ואבן עזרא לתהלים שם."],["6030","129","<b>ושאבתם מים בששון</b>: ישעי' יב, ג."],["6031","130","<b>שמשם הי' שואבים רוח הקודש</b>: ראה ירושלמי סוכה פ\"ה, ה\"א. לקו\"א להה\"מ סרנ\"ט[ednref_346_ח]. אוה\"ת הושע כרך א ע' תלז. לקו\"ש האזינו וחה\"ס כרך ב ע' 424."],["6032","131","<b>ששב ורפא לו</b>: ע\"פ ישעי' ו, י."],["6033","132","<b>שאי' בספרים שתשובה אינו מועלת</b>: ראה לעיל הנחה ד\"ה שובה ישראל הב' על יד הערה 75 בשם הזהר. אגה\"ת פ\"ד[ednref_347_ט]. ראה גם יומא פה, ב (במשנה[ednref_348_י]).\n\n[edn_346_ח] נמצא גם באו\"ת צג, ג.\nהועתק לעיל בהנחה ד\"ה שובה ישראל שם.\n\n[edn_347_ט] ושם: בזוה\"ק בקצת מקומות — ראה מ\"מ הגהות והע\"ק לשם*. אגה\"ת עם ליקוט פירושים שם. לקו\"ש ביאורים באגה\"ת כרך טל ע' 201 ואילך.\n\n[edn_348_י] ראה רמב\"ם הל' תשובה פ\"ד, ה\"א-ה\"ו. תניא פכ\"ה. אגה\"ת פי\"א [ובאגה\"ת עם ליקוט פירושים שם]. לעיל הנחה ד\"ה אני לדודי הב' פיסקא ולהבין זה איך. (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) שם פיסקא ושרש הענין."]]],[2000480558,"רגיל ללמוד<sup data-n=\"6034\">133</sup> דף א' ילמוד שני דפין פרק א' ילמוד שני פרקים, ומי שאינו יכול לכפול לימודו יחזור לימודו יותר מרגילותו, ובזה יש עוד מד' אחרת גבוה יותר כי הו\"ע עבודה ג\"כ וכמאמר ושבתי וראיתי<sup data-n=\"6035\">134</sup> בין צדיק עובד אלקים לאשר לא עבדו אינו דומה למי ששונה פרקו מאה פעמים למאה פעמים ואחד, נמצא שמלבד שהו\"ע תשובה אלא שכולל ג\"כ ענין עבודה נמצא שתשובה מועלת לו.\n<b>אך</b> לכאורה צ\"ל אף שאם עשה תשובה וזכאי חולקהון דמארי תיובתא<sup data-n=\"6036\">135</sup> דמשכין לי' לקוב\"ה בחילא יתיר<sup data-n=\"6037\">136</sup> בשעתא חדא וברגעא חדא<sup data-n=\"6038\">137</sup> אך עכ\"ז מאין לו לבושים, ה\"ה ערטלאי שאף לבושי המצות אשר עשה הנה הם לבושים צואים<sup data-n=\"6039\">138</sup>. אך הנה ע\"ז כתי' יפרוש כנפיו יקחהו ישאהו על אברתו שהמצות נק' בש' כנפים מה יונה<sup data-n=\"6040\">139</sup> כנפיה מגינות עלי' אוף<sup data-n=\"6041\">140</sup> כנס\"י מצות מגינות עליהן, כי כשם שהכנפים בעוף הם כלים להרצון<sup data-n=\"6042\">141</sup> כי בתנועה אחת היא מעופפת למעלה כמו למטה ואין שינוי בהכנפים רק בהרצון לכל מקום שרצונה לעוף שמה נושאים אותה הכנפים, כמו\"כ המצות הם ג\"כ כלים שהם כלים לא\"ס בעל הרצון<sup data-n=\"6043\">142</sup>. אך זהו כשלא פגם וקיים תומ\"צ ה\"ה ממשיך משם לבושים אבל אם פגם הנה ע\"ז כתי' ישאהו על אברתו שצריך להמשיך ממקום גבוה יותר ממצות ומשם נלקח לבושים. והענין הוא כי הנה בתורתו של ר' מאיר הי' כתוב כתנות אור באלף<sup data-n=\"6044\">143</sup> ולכאורה מהו פי' של אור בא',",[["6034","133","<b>כמ\"ש בתדב\"א הי' רגיל ללמוד</b>: בקיצורים והערות לתניא ס\"ע לט מציין: ע' ויקרא רבה פכ\"ה ע\"ש[ednref_349_א]. ראה לקו\"ש אגה\"ת כרך טל ע' 111 ואילך ובהערה 1 והערה 15 שם.\nמובא בכ\"מ (בנוסף להנ\"ל — בשינויי לשונות) בשם תדב\"א ומהם: אגה\"ת פ\"ט. מאמרי אדה\"ז כתובים ח\"א ס\"ע ב. אוה\"ת ואתחנן ע' שסד[ednref_350_ב]. לעיל הנחה ד\"ה שובה ישראל (הא' והב' על יד הערות 76־ 79). סה\"מ תרל\"ב ח\"ב ע' תקצז. המשך מים רבים תרל\"ו פ\"צ. פקל\"ה. סה\"מ תרל\"ו ח\"ב ע' שז. תר\"ס ע' קב. תש\"ט ס\"ע 223 ובהערה לשם. לקו\"ש תשא כרך כא ע' 236 הערה 34."],["6035","134","<b>ושבתי וראיתי</b>: מלאכי ג, יח [ושם: ושבתם וראיתם. בדילוג]. ראה חגיגה ט, ב. תניא פט\"ו. לקו\"ש וארא ח\"א ע' 117 ואילך."],["6036","135","<b>וזכאי חולקהון דמארי תיובתא</b>: ראה זהר שבהערה 137."],["6037","136","<b>דמשכין לי' לקוב\"ה בחילא יתיר</b>: ראה זהר ח\"ש קכט, ב. אגה\"ת פ\"ח. מאמרי אדה\"א בראשית ע' קעב. וש\"נ. תו\"ח שמות ח\"א לז, א. וש\"נ."],["6038","137","<b>בשעתא חדא וברגעא חדא</b>: ראה זהר שם קכט, א. לקו\"ש ח\"ש כרך כ ע' 86 ואילך. כרך כה ע' 326 ואילך."],["6039","138","<b>לבושים צואים</b>: ראה זהר פינחס ריד, א. אגה\"ק פ\"ד. זכרי' ג, ג-ד. תניא פ\"ט. פ\"י."],["6040","139","<b>שהמצות. . כנפים מה יונה</b>: ראה שבת מט, א. (לעיל בחלק המאמרים) המשך יונתי בתחילתו ובהנסמן שם."],["6041","140","<b>אוף</b>: כנצ\"ל: אף."],["6042","141","<b>שהכנפים. . כלים להרצון</b>: ראה לעיל המשך יונתי שם ובהערה 9."],["6043","142","<b>המצות. . כלים לא\"ס בעל הרצון</b>: ראה גם תו\"א ויקהל קיד, ב. לקו\"ת חוקת נז, א. המשך יונתי שם."],["6044","143","<b>בתורתו. . כתנות אור באלף</b>: ראה לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה ערבים עלי דברי דודיך הערה 61.\n\n[edn_349_א] בלקוטי הגהות לתניא ס\"ע ס ע\"ש מהרא\"י ריבלין. וראה שוה\"ג הבאה.\n\n[edn_350_ב] מביאו [בתוס' ביאוריו] בתורת האו\"ת מהמגיד נ\"ע [מהדורת קה\"ת עט, ב] ושם: ”כמ\"ש רז\"ל אם הי' רגיל\" והצ\"צ מוסיף את הציון בתדב\"א — ”כמשרז\"ל בתדב\"א אם הי' רגיל\". מזה לכאורה משמע כבשולי הגליון שלפנ\"ז, שזהו הגהת מהרא\"י ריבלין."]]],[2000480559,"אך הנה ענין עור בע' הוא מלשון עורות מעובדים<sup data-n=\"6045\">144</sup>, שהעור קודם שנעבד הי' קשה וע\"י עיבודו בדריכה ובעיטה פועלים בו ריכוך שיהי' ראוי לדבר הצריך. וכן הענין כי באדם כתי' לעבוד את האדמה<sup data-n=\"6046\">145</sup> כי ניתנה לו התומ\"צ שעי\"ז ירכך את חומריות וגסות הגוף ונה\"ב וזהו כתנות עור בע', אך הבע\"ת לוקח לו לבושים מכתנות אור בא'. וענין אור בא' הענין הוא כי הנה ידוע שמצות נק' בש' כלים, וכלים ולבושים הו\"ע א', וידוע אשר שרש הלבושים קדם לשרש האורות<sup data-n=\"6047\">146</sup>. ויובן זה ממה שמצינו שאותיות נק' ג\"כ לבושים<sup data-n=\"6048\">147</sup> ומ\"מ הרי בהם וע\"י מתגלה השכל ששרשם הוא בקדמות השכל<sup data-n=\"6049\">148</sup>, כמו\"כ שורש הלבושים הוא בהרשימה<sup data-n=\"6050\">149</sup>, וענין הרשימה הנה אם נפרשו לגריעותא פי' אשר לא נשאר כ\"א רשימה שסילק את אורו הגדול אל הצד<sup data-n=\"6051\">151</sup> שכל האור נתעלם, ובאמת אם נדקדק<sup data-n=\"6052\">150</sup> היטב הלא מאין נשארו<sup data-n=\"6053\">152</sup> הרשימה הלא נשארו מאוא\"ס שקודם הצמצום שהי' האוא\"ס ממלא כל החלל<sup data-n=\"6054\">153</sup> שהוא ע\"ד אור מעין המאור ומהאור הזה נשאר הרשימה, שע\"ז כתי' הנה מקום אתי<sup data-n=\"6055\">154</sup> שהוא מקומו של עולם<sup data-n=\"6056\">155</sup> ואין העולם מקומו כי מעמד<sup data-n=\"6057\">156</sup> כללי לכללות עולמות אבי\"ע, וע\"י התשובה שהו\"ע ורוח תשוב לאלקי'<sup data-n=\"6058\">157</sup> אשר נתנה יבוא לבחי' נשמה שנתת בי טהורה<sup data-n=\"6059\">158</sup> ענין טהירו עילאה<sup data-n=\"6060\">159</sup> והוא ע\"ד שהקלף שנושא וסובל את האותי'. אך איך יכול לבוא לבחי' ומדריגה זו, הוא מאשר כי מחשבתן של ישראל קדמה לכל דבר<sup data-n=\"6061\">160</sup>, פי' בכל מקום שנאמר דבר שאפי' מה שעלה ברצונו לצמצם, בזה ג\"כ קדמה",[["6045","144","<b>עורות מעובדים</b>: ראה שבת מט, ב. תו\"ח יתרו ח\"ב רסח, ב. וש\"נ. סה\"מ תרל\"ח ע' שפ. וש\"נ."],["6046","145","<b>לעבוד את האדמה</b>: בראשית ג, כג."],["6047","146","<b>שרש הלבושים קדם לשרש האורות</b>: ראה מאמרי אדה\"ז תקס\"ב ח\"א ס\"ע ר ואילך בשם (ע\"ח) שער הכללים. אתהלך לאזניא ע' יז. אוה\"ת תצא ע' תתקכד ואילך. תו\"ח שמות ח\"א מו, א. וש\"נ."],["6048","147","<b>שאותיות נק' ג\"כ לבושים</b>: ראה שעה\"י קלה, ב ובהערה 23. המשך תער\"ב ח\"ב ס\"ע תתסג ואילך."],["6049","148","<b>שאותיות. . בקדמות השכל</b>: ראה גם (לעיל בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה יונתי בחגוי הסלע ובהערה 62."],["6050","149","<b>שורש הלבושים הוא בהרשימה</b>: ראה גם שעה\"י קל, א ובהנסמן במ\"מ לשם. (לעיל בחלק המאמרים) בהמאמר כאן על יד הערה 50. (בחלק ההנחות) הנחה ד\"ה יפה שעה אחת הב' על יד הערה 107. הנחה ד\"ה שובה ישראל הא' על יד הערה 164. מאמר ד\"ה זה תשכ\"ה הערה 25."],["6051","151","<b>שסילק את אורו הגדול אל הצד</b>: ראה גם לעיל ח\"א (בחלק המאמרים) המשך מצה זו הערה 216 ובשוה\"ג ד שם."],["6052","150","<b>וענין הרשימה. . ובאמת אם נדקדק</b>: ראה (לעיל בחלק המאמרים) בהמאמר כאן. מאמר ד\"ה חסידים ואנשי מעשה תשכ\"ט ס\"ג. וש\"נ."],["6053","152","<b>נשארו</b>: כנצ\"ל: נשאר."],["6054","153","<b>ממלא כל החלל</b>: ראה גם לעיל שם ובהערה 215."],["6055","154","<b>הנה מקום אתי</b>: תשא לג, כא. ראה גם לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה משה קבל תורה מסיני בתחילתו."],["6056","155","<b>שהוא מקומו של עולם</b>: ב\"ר פס\"ח, ט. ראה מאמרי אדה\"א דברים ח\"א ע' רצא. וש\"נ. תו\"ח בראשית מג, א הערה 2. סה\"מ תרכ\"ט ע' קסט. וש\"נ."],["6057","156","<b>כי מעמד</b>: כ\"ה בהכת\"י."],["6058","157","<b>ורוח תשוב לאלקי'</b>: קהלת יב ז [ושם: והרוח. . אל האלקי']."],["6059","158","<b>נשמה שנתת בי טהורה</b>: ברכת אלקי נשמה (מברכות ס, ב)."],["6060","159","<b>טהורה ענין טהירו עילאה</b>: ראה גם לעיל (בחלק המאמרים) המשך יונתי הערה 211."],["6061","160","<b>מחשבתן של ישראל. . דבר</b>: ב\"ר פ\"א, ד. ראה סה\"מ תרמ\"ד ע' שנט (מהדורת תשס\"ב)."]]],[2000480560,"מחשבתן של ישראל שהי' הם המכריחים לזה. אך צ\"ל מאחר שכן איך הוא הירידה צורך עלי' שאמרנו שצריך להיות העלי' מאיהו וגרמוהי לאיהו וחיוהי<sup data-n=\"6062\">161</sup> שכ\"ז הוא לאחר הצמצום אבל קודם הצמצום איך שייך שם העלי', אך באמת הענין הוא כי היכן שייך ירידה צורך עלי' לאחר הצמצום אבל קודם הצמצום לא שייך ירידה צורך עלי' אלא כי מקודם היתה בעצם כן ועתה הוא ע\"י עבודה יכול להיות לבוא לבחי' לדבקה בו<sup data-n=\"6063\">162</sup> ית'. ובאמת י\"ל אשר גם שם יש בחי' ירידה צורך עלי' אבל א\"א שם לחלקם בשמות מחולקים, כי השמות שייכים לאחר הצמצום אבל קודם הצמצום לא שייך ענין שמות. אך כ\"ז הוא עכשיו שאינו כ\"א והרוח תשוב שנושאים את ההארה אל השורש אבל השורש אינו מאיר למטה לכך אינו בבחי' קיום שאפי' אדה\"ר חי אלף שנה<sup data-n=\"6064\">163</sup> עכ\"ז מת, אבל לע\"ל שיתגלה בחי' ונתתי רוחי<sup data-n=\"6065\">164</sup> שהנותן בעין יפה הוא נותן<sup data-n=\"6066\">165</sup>, ואינו כתי' מי הוא הנותן שקאי על א\"ס עצמותו ומהותו, ואז יהי' וחייתם<sup data-n=\"6067\">166</sup> שיהי' חיים וקיימים. וזהו כנשר יעיר קינו על גוזליו ירחף יפרוש כנפיו יקחהו ישאהו על אברתו, שלצדיקים הו\"ע יפרוש כנפיו, וענין על אברתו הו\"ע הבע\"ת שמגיע לבחי' שלמעלה משרש המצות.",[["6062","161","<b>העלי'. . לאיהו וחיוהי</b>: ראה לעיל הנחה יפה שעה אחת הא' בסופה."],["6063","162","<b>לדבקה בו</b>: עקב יא, כב [ושם: ולדבקה]."],["6064","163","<b>אדה\"ר חי אלף שנה</b>: ראה בראשית ה, ה. ב\"ר פי\"ט, ח. במד\"ר פי\"ד, יב. סהמ\"צ להצ\"צ קח, סע\"ב. ולהעיר מת\"ז סת\"ע קלח, רע\"א."],["6065","164","<b>ונתתי רוחי</b>: יחזקאל לז, יד."],["6066","165","<b>שהנותן בעין יפה הוא נותן</b>: ראה ב\"ב סה, א. לקו\"ת האזינו עב, ב ובהנסמן במ\"מ לשם."],["6067","166","<b>וחייתם</b>: יחזקאל שם."]]],[2000480561,"<h3>ושאבתם מים</h3>\n<b></b><b>בס\"ד שבת חומ\"ס שנת תרמ\"א ליובאוויץ</b>\nשבת חומ\"ס\n<b>ושאבתם</b> מים<sup data-n=\"6068\">1</sup> בששון ממעיני הישועה<sup data-n=\"6069\">2</sup>, הנה זהו\"ע נסה\"מ שבחג<sup data-n=\"6070\">3</sup> שניתוסף על כל השנה שהי' רק נסה\"י<sup data-n=\"6071\">4</sup> אבל בחג ניתוסף נסה\"מ ג\"כ. וענין נסה\"מ לא מצינו בתורה כ\"א בדרך רמז שביום השני כתי' ונסכיהם מ\"ם יתירה וביום הששי כתי' ונסכיה שניתוסף יו\"ד וביום השביעי כתי' כמשפטם<sup data-n=\"6072\">5</sup> מ\"ם יתירה זהו רמז לנה\"מ. ולכאורה נראה שנסה\"י גבוה יותר כי הוא מבואר כמה פעמים בתו' בפ' נסכים<sup data-n=\"6073\">6</sup> ומנחתם ונסכיהם<sup data-n=\"6074\">7</sup>, ועוד הרבה פעמים, שהוא מורה על חביבות, כמו עד\"מ",[["6068","1","<b>ושאבתם מים</b>: הנחה ממאמר ד\"ה זה שנדפס לעיל בחלק המאמרים. וש\"נ."],["6069","2","<b>ושאבתם מים בששון ממעיני הישועה</b>: ישעי' יב, ג."],["6070","3","<b>נסה\"מ </b>[ ניסוך המים]<b> שבחג</b>: סוכה מב, ב. מח, א-ב. רמב\"ם הל' תמידין ומוספין פ\"י, ה\"ו."],["6071","4","<b>כל השנה. . נסה\"י </b>[ ניסוך היין]: ראה רמב\"ם הל' מעשה הקרבנות פ\"ב. הל' תמידין ומוספין פ\"ו, ה\"ו. בסמוך בפנים."],["6072","5","<b>ונסכיהם. . ונסכיה. . כמשפטם</b>: פינחס כט, יט. לא. לג."],["6073","6","<b>בפ' נסכים</b>: שלח פט\"ו."],["6074","7","<b>ומנחתם ונסכיהם</b>: אמור כג, יח. פינחס כט, יח ואילך."]]],[2000480562,"באדם שע\"ד שחביבה עליו מצוה עליה כמה פעמים, א' וב' וג' פעמים, אבל נסה\"מ לא מצינו כלל בתורה. והעיקר הוא הלמ\"מ<sup data-n=\"6075\">8</sup> אך רבנן סמכוה על רמז דקרא<sup data-n=\"6076\">9</sup> אבל א\"ל<sup data-n=\"6077\">10</sup> הלמ\"מ לא נוכל ללמוד מהרמז זה כי באמת באותיו' הנוספים ג\"כ מובן הפשט, משמע מזה דנה\"י גבוה מנה\"מ, ובאמת נסה\"מ גבוה יותר מנסה\"י, כי בנס\"מ כתי' ושאבתם מים בששון וששון הוא מד' גבוה משמחה<sup data-n=\"6078\">11</sup>, וכן אי' חסידים הראשונים הי' מרקדין<sup data-n=\"6079\">12</sup> ואבוקה של אור בידיהן, שזהו\"ע מד' גבוה, וכן אי' מי שלא ראה שמבה\"ש לא ראה שמחה מימיו<sup data-n=\"6080\">13</sup> משמע מזה דנה\"מ גבוה יותר, וצ\"ל למה לא מבואר בתו' נה\"מ. אך י\"ל דהיא הנותנת מחמת שנה\"מ הוא מד' גבוה ע\"כ לא תוכל להתלבש באותי' התורה.\n<b>ולהבין</b> זה צ\"ל בכלל ענין הנסכים הנה ארז\"ל כל הקורא ק\"ש בלא תפילין<sup data-n=\"6081\">14</sup> כאלו הקריב עולה בלא מנחה וזבח בלא נסכים, וענין הנסכים הוא בכלל המשכות<sup data-n=\"6082\">15</sup>, ובנסכים הי' ג' דברים שמן יין וסולת<sup data-n=\"6083\">16</sup>, שמן הוא חכ'<sup data-n=\"6084\">17</sup> יין הוא בינה<sup data-n=\"6085\">18</sup> וסולת הו\"ע דעת<sup data-n=\"6086\">19</sup> כמארז\"ל אין התינוק יודע לקרוא אבא<sup data-n=\"6087\">20</sup> עד שיטעום טעם דגן ומאחר שמפעיל דעת ה\"ה בעצמו דעת, ובכלל הוא המשכות חב\"ד, וע\"כ כל הקורא כו' עולה בלא מנחה עולה הוא העלייה ממטלמ\"ע שעולה כולה כליל<sup data-n=\"6088\">22</sup> ומנחה הוא מ\"נ ח\"ה<sup data-n=\"6089\">23</sup> שע\"י העליות מ\"ן ממשיכים מחכ' בה' בהבראם בה' בראם<sup data-n=\"6090\">24</sup>, או למעלה יותר ח' הוא ממזל שמיני ונוצר<sup data-n=\"6091\">25</sup> ממשיכים בה' בראם, וזבח הוא מלמטלמ\"ע<sup data-n=\"6092\">21</sup> בלא נסכים המשכה מלמעלמ\"ט ובנסכים הי' ב' מד' נה\"י ונה\"מ.",[["6075","8","<b>נסה\"מ. . הלמ\"מ</b>: בלקו\"ת סוכות (כאן) עט, ד מציין: ”סוכה ל\"ד א' זבחים ק\"י ע\"ב\". רמב\"ם שבהערה 3."],["6076","9","<b>רבנן סמכוה על רמז דקרא</b>: שבת קג, סע\"ב. תענית ב, סע\"ב."],["6077","10","<b>א\"ל</b>: אי לא."],["6078","11","<b>וששון. . גבוה משמחה</b>: ראה גם אוה\"ת מג\"א ע' קנב. מאמרי אדה\"א דרושי חתונה ח\"ב ע' תקפז."],["6079","12","<b>חסידים הראשונים הי' מרקדין</b>: ראה סוכה נא, סע\"א ואילך (במשנה)."],["6080","13","<b>מי שלא ראה. . מימיו</b>: סוכה נא, א (במשנה)."],["6081","14","<b>כל הקורא ק\"ש בלא תפילין</b>: ברכות יד, סע\"ב. ראה (ולהבא בסמוך בפנים) לקו\"ת שלח מב, א. מאמרי אדה\"א במדבר ח\"ג ס\"ע א'רא ואילך. אוה\"ת על מארז\"ל ע' יא. סה\"מ תרל\"ח ע' מ ואילך."],["6082","15","<b>נסכים. . המשכות</b>: ראה בהערה שלפנ\"ז."],["6083","16","<b>ובנסכים. . שמן יין וסולת</b>: שלח פט\"ו."],["6084","17","<b>שמן הוא חכ'</b>: ראה גם לעיל ח\"א (בחלק המאמרים) המשך זאת חנוכת המזבח פ\"ט ובהערה 159."],["6085","18","<b>יין הוא בינה</b>: ראה זהר נשא קכז, א. מאמרי אדה\"א ויקרא ח\"א ע' לג. וש\"נ. בראשית ע' תקעא."],["6086","19","<b>וסולת הו\"ע דעת</b>: לקו\"ת שלח מב, א."],["6087","20","<b>אין התינוק יודע לקרוא אבא</b>: ראה ברכות מ, סע\"א. מאמרי אדה\"א דברים ח\"א ע' רמה. וש\"נ. תו\"ח בא ח\"א צה, ב. וש\"נ."],["6088","22","<b>שעולה כולה כליל</b>: ויקרא א, ט. רמב\"ם הל' מעשה הקרבנות רפ\"ו."],["6089","23","<b>מנחה. . מ\"נ ח\"ה</b>: ראה תו\"א וישלח כה, ד. (לעיל בחלק המאמרים) בהמאמר כאן הערה 18."],["6090","24","<b>בהבראם בה' בראם</b>: בראשית ב, ד. ראה מנחות כט, ב. ב\"ר פי\"ב, ב. פרש\"י עה\"פ."],["6091","25","<b>ממזל. . ונוצר</b>: כ\"ה בכ\"מ ומהם — מאמרי אדה\"א בראשית ע' רנה. במדבר ח\"ב ע' תעו. דברים ח\"ב ע' שעז. וש\"נ."],["6092","21","<b>עולה. . ממטלמ\"ע. . וזבח הוא מלמטלמ\"ע</b>: ראה סה\"מ תרמ\"ד ע' רסז."]]],[2000480563,"<b>ולהבין</b> ב' מד' אלו הנה ע' נה\"י הוא כמ\"ש החדלתי את תירושי<sup data-n=\"6093\">26</sup> המשמח אלקי' ואנשים וארז\"ל אם אנשים משמח אלקי' מה<sup data-n=\"6094\">28</sup> משמח מכאן שאין אומרים שירה אלא על היין<sup data-n=\"6095\">27</sup>, וצ\"ל ענין המשמח אלקי'. הנה אלקי' הוא כח הפועל<sup data-n=\"6096\">29</sup> בנפעל<sup data-n=\"6097\">30</sup>, ל\"ב פעמים אלקי' שבמע\"ב<sup data-n=\"6098\">31</sup>, ושרש התהות העולמות הוא ממדות<sup data-n=\"6099\">32</sup> כמ\"ש כי אמרתי עולם חסד יבנה<sup data-n=\"6100\">33</sup>, אף שזהו רק חסד, אך החסד הוא מדה ראשונה לכן חשיב רק חסד וכן כולם, או י\"ל דחסד הוא כולל כל המדות כמ\"ש יומם יצוה ד' חסדו<sup data-n=\"6101\">34</sup> שחסד הוא יומם דאזיל עם כולי' יומין, או י\"ל דעיקר קיום העולמות הוא מחסד כמארז\"ל בתחילה עלה ברצונו<sup data-n=\"6102\">35</sup> לברוא את העולם במדה\"ד ראה שאין העולם מתקיים שיתף עמו מדה\"ר ורחמים מטה כלפי חסד וה\"ה חסד וממנו עיקר קיום העולמות וע\"כ כתי' זכור רחמיך וחסדיך כי מעולם המה<sup data-n=\"6103\">36</sup> כי רחמים וחסדים שייך לעולם, אף כי הפי' הפשוט כי מעולם פון אייביק<sup data-n=\"6104\">37</sup> ן<sup data-n=\"6105\">38</sup>, אך גם זאת אמת שמדות שייכים לעולם כמו שאנו רואים באדם שאימתי יכולים המדות להתגלות דוקא לזולתו שא\"ל הזולת הנה העצם המדה ופעולת המדה יבטל הי' כלא הי', אבל חכ' אנו רואים שיכול לישב ביחידות<sup data-n=\"6106\">39</sup> ולהשכיל השכלות וזולת לא ידע כלל, כי אנו רואים שיש חכמים מחוכמים אשר אין יודעין מהם כלל אך לעת מן העיתים שבא העת שצריך להתגלות אז נתגלה, איז ער ד ך מיט „מ ל ניט גיוו רין איין חכם, בודאי הי' קודם ג\"כ חכם אך עד עתה הי' חכ' בפ\"ע, המדות<sup data-n=\"6107\">40</sup> אינם שייכים אלא שיש זולת, וכן למעלה אינו שייך מדות אלא כשיש עולם, ושרש בריאות העולמות<sup data-n=\"6108\">41</sup> נמשכים ממדות אלו, ומצד זה נמשך שיהי' עולם לשון העלם<sup data-n=\"6109\">42</sup> שמעלים ומסתיר על א\"ס שבתוכו כי באמת התחלת התהות הגשמיות הוא מהרוחני', ואולי<sup data-n=\"6110\">43</sup> יסתלקו",[["6093","26","<b>החדלתי את תירושי</b>: ס' שופטים ט, יג."],["6094","28","<b>מה</b>: אוצ\"ל: במה."],["6095","27","<b>אם אנשים משמח. . שירה אלא על היין</b>: ברכות לה, א."],["6096","29","<b>אלקי' הוא כח הפועל בנפעל</b>: ראה גם לקו\"ת בחוקותי מט, ב. מאמרי אדה\"ז תקס\"ז ע' רי. ש\"א לו, א. פח, ב. פט, ב."],["6097","30","<b>כח הפועל בנפעל</b>: בלקו\"ת שלח מז, א: בספרים. ראה הנסמן במ\"מ לשם. ספר הישר (לר\"ת ) סוף ש\"ג."],["6098","31","<b>ל\"ב פעמים אלקי' שבמע\"ב</b>: נמנו בפרטיות בתקז\"ח קיב, ג. ראה מאמרי אדה\"א ויקרא ח\"ב ע' תרכה. וש\"נ. שעה\"י קלב, א ובהערה 3."],["6099","32","<b>התהוות העולמות הוא ממדות</b>: ראה גם (לעיל בחלק המאמרים) בהמאמר כאן הערה 22."],["6100","33","<b>כי אמרתי עולם חסד יבנה</b>: תהלים פט, ג."],["6101","34","<b>יומם יצוה ד' חסדו</b>: תהלים מב, ט. ראה לעיל ח\"א (בחלק המאמרים) בסוף מאמר ד\"ה ואעשך לגוי גדול שמציין: זח\"ג אמור קג, ע\"ב. ראה גם הנסמן במאמרי אדה\"א דברים ח\"ג ע' א'לה."],["6102","35","<b>בתחילה עלה ברצונו</b>: ראה רש\"י בראשית א, א. הנסמן במאמרי אדה\"א דברים ח\"ד ע' א'תכ."],["6103","36","<b>זכור רחמיך. . המה</b>: תהלים כה, ו [בדילוג השם]."],["6104","37","<b>הפי' הפשוט. . אייביק אן</b>: ראה רש\"י לתהלים שם."],["6105","38","<b>פון אייביק אן</b>: ראה גם (לעיל בחלק המאמרים) בהמאמר כאן הערה 31."],["6106","39","<b>שמדות שייכים לעולם. . חכ'. . ביחידות</b>: ראה (לעיל בחלק המאמרים) בהמאמר כאן ובהערה 22. המשך יונתי ובהערה 261."],["6107","40","<b>המדות</b>: כנראה שחסר כאן. ואוצ\"ל: אבל המדות."],["6108","41","<b>בריאות העולמות</b>: ראה גם תניא פכ\"א כז, א ובליקוטי לוי יצחק שם."],["6109","42","<b>עולם לשון העלם</b>: ראה ספר הבהיר ס\"י. תו\"ח שמות ח\"א יח, ד הערה 783."],["6110","43","<b>ואולי</b>: אוצ\"ל: ואם."]]],[2000480564,"הרוחני' על רגע א' הי' מן הגשמי' אין ואפס, ולסוף מצד ההעלם וההסתר ק ן זיך לייגין „ז עולם כמנהגו נוהג<sup data-n=\"6111\">44</sup>, וו ס קען זיין גרעשירע הגשמה מזה שמהדבר שמקבל חיות לא ירגיש, וכן עולמות העליונים הלא לפ\"ע התהותם ולפ\"ע גילוים זהו ג\"כ ענין העלם. אך זהו רק עולמות השייכים למדות אבל באמת יש עולמות למעלה מעולמות הללו. כמ\"ש ועל ראשי החיות רקיע<sup data-n=\"6112\">45</sup> כעין הקרח, שהוא חו\"ג<sup data-n=\"6113\">46</sup> עילאין שהן האבות<sup data-n=\"6114\">47</sup> והאבות הן הן המרכבה<sup data-n=\"6115\">48</sup> מד'<sup data-n=\"6116\">49</sup> דאצי' ועל המדות יש רקיע כעין הקרח המפסיק והקרח הזה הוא כמ\"ש מבטן מי יצא הקרח<sup data-n=\"6117\">50</sup>, מי הוא בינה<sup data-n=\"6118\">51</sup>, שמבינה למדות יש פרסא<sup data-n=\"6119\">52</sup> המכסה על האור כמו שהוא בבינה שהו\"ע עלדאת\"כ<sup data-n=\"6120\">53</sup> שלא יבוא למדות עלדאת\"ג<sup data-n=\"6121\">54</sup>.\n<b>וזהו</b> יין המשמח אלקים, ענין משמח כי שמחה שייך לבינה<sup data-n=\"6122\">55</sup> השגה והבנה, כמו שאנו רואים באדם אימתי יש לו שמחה דוקא כשמבין ומשיג הענין, וכן בעבודה כשמתבונן דכולא קל\"ח<sup data-n=\"6123\">56</sup> שזהו\"ע יחו\"ע, וכשמתבונן כראוי אז נתמלא שמחה מזה, וכן כתי' אם הבנים שמחה<sup data-n=\"6124\">57</sup> כשנמשך מאם בחי' בינה אז שייך ענין שמחה, וזהו המשמח אלקי' שהשמחה יהי' גם בש' אלקי' מקור העולמות מחמת שנמשך מבינה. וזה הי' ע\"י נסה\"י יין המשמח, כי א\"ר<sup data-n=\"6125\">58</sup> שיש ביין כח להוציא מהעלם אל הגילוי<sup data-n=\"6126\">59</sup> כמשא\"ר באדם שעפ\"י שכל שכלו<sup data-n=\"6127\">60</sup> מצמצם הדבר שלא יגלה זאת לזולתו מחמת איזה טעם הכמוס אצלו וכששותה יין נתבלבל השכל ונאבדו הטעמים ואז יוכל להתגלות דברים אשר א\"ל היין לא הי' מגלה זאת בשום ענין ואופן כמו אגבירו חמרא אדרדקי<sup data-n=\"6128\">61</sup> כי היכא דלימרא מלתא, שבלא היין לא הי'",[["6111","44","<b>עולם כמנהגו נוהג</b>: ע\"ז נד, ב. ראה גם לעיל הנחה ד\"ה אני לדודי הב' על יד הערה 109."],["6112","45","<b>ועל ראשי החי' רקיע</b>: ראה (לעיל בחלק המאמרים) מאמר ד\"ה להבין שרש ענין מקיפים דבינה הערה 10."],["6113","46","<b>חו\"ג</b>: אוצ\"ל: חיון. או שצ\"ל: חג\"ת."],["6114","47","<b>שהן האבות</b>: ראה הערה 9 שבמאמר שבהערה 45."],["6115","48","<b>והאבות הן הן המרכבה</b>: ב\"ר פמ\"ז, ו. פפ\"ב, ו. ראה מאמרי אדה\"א דברים ח\"א ע' רטו. וש\"נ. תו\"ח נח מט, ד ובהערה 42. משפטים ח\"ב ש, ג. סה\"מ תרכ\"ט ע' רלח. וש\"נ."],["6116","49","<b>מד'</b>: מדות."],["6117","50","<b>מבטן מי יצא הקרח</b>: איוב לח, כט. ראה גם סידור שחרית סד, א. אוה\"ת איוב כרך א ע' תרצב."],["6118","51","<b>מי הוא בינה</b>: זהר משפטים קיז, ב. לקו\"ת פקודי ד, ג. תו\"ח פקודי ח\"ב תמג, ד ובהערה 78."],["6119","52","<b>שמבינה למדות יש פרסא</b>: ראה הערות 9. 11 שבמאמר שבהערה 45."],["6120","53","<b>בבינה שהו\"ע עלדאת\"כ</b>: ראה לקו\"ת סוכות עט, ד. הועתק לעיל ח\"א (בחלק המאמרים) המשך מצה זו פל\"ח ובהערה 1185."],["6121","54","<b>עלדאת\"כ. . עלדאת\"ג</b>: ראה זהר בראשית יח, א. ויצא (ס\"ת) קנב, א. קנח, ריש ע\"ב. וארא כט, ב. ת\"ז בהקדמה א, סע\"א ואילך. תניא פכ\"ו."],["6122","55","<b>שמחה שייך לבינה</b>: ראה לקו\"ת שמ\"ע פח, ד. לעיל ח\"א (בחלק המאמרים) המשך זאת חנוכת המזבח הערה 208."],["6123","56","<b>דכולא קל\"ח</b>: ראה זהר בהקדמה יא, ב. ראשית חכמה שער היראה ש\"א, פ\"ז [ז, רע\"א]. מאמרי אדה\"ז תקס\"ו ע' שמא. מאמרי אדה\"א דברים ח\"ב ע' תרנג."],["6124","57","<b>אם הבנים שמחה</b>: תהלים קיג, ט."],["6125","58","<b>א\"ר</b>: אנו רואים."],["6126","59","<b>שיש ביין. . הגילוי</b>: ראה גם לעיל ח\"א (בחלק המאמרים) המשך מצה זו פל\"ז. סה\"מ תרכ\"ט ס\"ע שפג ואילך. וש\"נ."],["6127","60","<b>שעפ\"י שכל שכלו</b>: אוצ\"ל: שעפ\"י שכל."],["6128","61","<b>אגבירו חמרא אדרדקי</b>: סנהדרין לח, א. ראה גם מאמרי אדה\"א נ\"ך ע' רפג. שם ע' רפט. וש\"נ."]]],[2000480565,"אומרים שהי' בהעלם וע\"י היין מגלה זאת, וכח הזה נמצא ביין כי התהותו הוא מהעלם אל הגילוי כי קודם הי' היין כנוס בהענבים<sup data-n=\"6129\">62</sup>, וע\"י הדריכה בגת יוצא מהעלם אל הגילוי, לכן פעולתו ג\"כ שיוכל להוציא מהעלם אל הגילוי שזהו נכנס יין יצא סוד<sup data-n=\"6130\">63</sup>, סוד הוי' ליראיו<sup data-n=\"6131\">64</sup>. וזהו שע\"י נסה\"י נמשך השמחה בש' אלקי' שהי' ממשיכים גילוים מעלדאת\"כ לעלדאת\"ג, ועי\"ז הי' מסירים הצמצום אשר מש' אלקי'<sup data-n=\"6132\">65</sup>, וע\"כ הי' הנסה\"י ע\"ג השיטין<sup data-n=\"6133\">66</sup> שתהי' יורד השמחה עד התהום, כי מים תחתונים בוכין<sup data-n=\"6134\">67</sup> אנן בעינן למהוי קדם מלכא, כי עד שלא נברא העולם הי' מים במים<sup data-n=\"6135\">68</sup>, שמים עליונים לא הי' בתכלית העילוי ומים תחתונים לא הי' בתכלית הירידה, ואח\"כ המים עליונים נתעלו עד רום המעלות ומים תחתונים ירדו למטה מטה וע\"כ הם בוכים, וע\"י נסה\"י פעלו שמחה גם בהם כי ע\"י נסה\"י המשיכו גילוים מעלדאת\"כ עד למטה מטה.\n<b>אך</b> צ\"ל ההפרש שבין נה\"י של כל השנה לנה\"י שהי' בחג, הענין הוא כי ידוע שיש ב' אופנים בשמחה כי פעם כתי' תחת אשר לא עבדת<sup data-n=\"6136\">69</sup> את ד' אלקיך בשמחה ובטוב לבב מרוב כל או עבדו את ה' בשמחה<sup data-n=\"6137\">71</sup>, ופעם כתי' שמחו צדיקים<sup data-n=\"6138\">70</sup> בהוי'<sup data-n=\"6139\">72</sup> שלכאורה אינו מובן הלא מ\"ע<sup data-n=\"6140\">73</sup> צדיקים שמקיימים תומ\"צ והלא כל ישראל מקיימים תומ\"צ אלא שיאמר כי באמת ועמך כולם צדיקים<sup data-n=\"6141\">74</sup> כתי' הלא זהו עבדו את ד' בשמחה ומהו ענין שמחו צדיקים דוקא. אך באמת יש ב' בחי' בשמחה, יש שמחה שהשמחה מוסתר אצלו בפנימי' ואינו בגילוי וז\"ע עבדו את ד' בשמחה שהשמחה היא מסותרת בהעבודה, שבגילוי תהי' רק העבודה וטו\"ת בזמנו ציצית<sup data-n=\"6142\">75</sup> בזמנו סוכה בזמנה ד\"מ שבלולב אך יהי' שמח מהעבודה, אף כי איך הוא העבודה עבודת עבד אך אינו דומה אצל מי הוא עבד שיש עבד טבח ויש עבד ושר<sup data-n=\"6143\">76</sup> הטבחים ויש עבד",[["6129","62","<b>הי' היין כנוס בהענבים</b>: ראה פסחים לג, ב. סה\"מ תרכ\"ט ע' שפד."],["6130","63","<b>נכנס יין יצא סוד</b>: ערובין סה, סע\"א. ראה גם תו\"ח ויחי רלו, ב."],["6131","64","<b>סוד הוי' ליראיו</b>: תהלים כה, יד."],["6132","65","<b>הצמצום אשר מש' אלקי'</b>: ראה שער היחוה\"א רפ\"ו. תו\"ח שמות ח\"א לד, ד. וש\"נ."],["6133","66","<b>הנסה\"י ע\"ג השיטין </b>[כנצ\"ל: השיתין]: ראה רמב\"ם הל' מעשה הקרבנות פ\"ב, ה\"א. הל' תמידין ומוספין פ\"י ה\"ז. אוה\"ת על מארז\"ל ס\"ע ג ואילך."],["6134","67","<b>מים תחתונים בוכין</b>: ראה ת\"ז ת\"ה (יט, ב). לעיל ח\"א (בחלק המאמרים) המשך זאת חנוכת המזבח פי\"ט. וש\"נ."],["6135","68","<b>עד שלא נברא. . מים במים</b>: ראה ב\"ר פ\"ה, ב. לעיל ח\"א (בחלק המאמרים) מאמר ד\"ה כמגדל דוד צוארך ובהערה 5."],["6136","69","<b>תחת אשר לא עבדת</b>: תבוא כח, מז."],["6137","71","<b>עבדו את ה' בשמחה</b>: תהלים ק, ב."],["6138","70","<b>תחת. . מרוב כל. . שמחו צדיקים</b>: ראה לקו\"ת תבוא מב, סע\"ג [ובהנסמן במ\"מ לשם]. סה\"מ תר\"ל ע' קיד. עטר\"ת ע' רעז ואילך. מאמר ד\"ה כי תשא תשי\"ז."],["6139","72","<b>שמחו צדיקים בהוי'</b>: תהלים צז, יב. ראה גם תניא ספ\"י. אגה\"ק סי\"ח (הובא בלקו\"ת תבוא מג, א)."],["6140","73","<b>מ\"ע</b>: מהו ענין."],["6141","74","<b>ועמך כולם צדיקים</b>: ישעי' ס, כא."],["6142","75","<b>וטו\"ת. . ציצית</b>: (לעיל בחלק המאמרים) בהמאמר כאן בסמיכות להערה 62: שמתעטף בציצית או מניח תפילין."],["6143","76","<b>עבד טבח ויש עבד ושר</b>: אוצ\"ל: עבד הטבח ויש עבד לשר."]]],[2000480566,"מלך, שעבד מלך מלך<sup data-n=\"6144\">77</sup> קרב לגבי דהינא ואידהין<sup data-n=\"6145\">78</sup>, הדבק<sup data-n=\"6146\">79</sup> לשחרר<sup data-n=\"6147\">80</sup> וישתחוה לך, וכשמתבונן שהוא עבד לממה\"מ הקב\"ה<sup data-n=\"6148\">81</sup> הי'<sup data-n=\"6149\">82</sup> לו מזה שמחה, אך השמחה היא מסותרת, אבל מד'<sup data-n=\"6150\">83</sup> שמחו צדיקים הוא כמו אחד ששמח והשמחה היא בנגלות כמו אחד שיוצא מגדר הכלי ומרנן ומרקד שהשמחה היא בגילוי. אך אין המשל דומה לנמשל, כי במשל הוא שמח מעצמו, אבל בנמשל הוא שמחו צדיקים בהוי' איך שהוא הי' הוה ויהי'<sup data-n=\"6151\">84</sup>. וזהו\"ע נסה\"י שבכל השנה שאף שע\"י נה\"י פעלו שמחה להמשיך גילוים מבינה אך זהו רק הארה מבינה אבל במועדים שהם מועדים לשמחה<sup data-n=\"6152\">85</sup> ובפרט בחג שהוא זמן שמחתינו<sup data-n=\"6153\">86</sup> שנותן כח לשמחה של מצוה לכל השנה אז השמחה שנמשך ע\"י נסה\"י הוא כמו שמחו צדיקים שהשמחה היא בגילוי שאז נמשך עצם הבינה.\n<b>ומעתה</b> צ\"ל ענין נסה\"מ שניתוסף בחג, הענין הוא כי ההפרש שבין יין למים א\"ר שיין יש בו גוון, אף שיש חמר חווריין<sup data-n=\"6154\">87</sup> אך גם זהו גוון אך שהוא לבן מאדום אבל מ\"מ ה\"ז גוון אבל מים אין בו שום גוון<sup data-n=\"6155\">88</sup> רק שנצטייר לפי צורת הכלי שהוא מקבל עליו כל השינויים אבל עצם המים לא נשתנה כלל, שזהו בכלל ההפרש שבין חכ'<sup data-n=\"6156\">89</sup> לבינה, ובעבודה הו\"ע עבודת הלוים ועבודת הכהנים שענין עבודת הלוים הי' לארמא קלא<sup data-n=\"6157\">90</sup> כי בלוים כתי' ועבד הלוי הוא<sup data-n=\"6158\">91</sup>, הוא פי' בינה<sup data-n=\"6159\">92</sup>, שעבודתם הי' להמשיך מבינה גילוים, וע\"כ הי' עבודתם לארמא קלא, שהקול שהוא בהעלם והם המשיכו לגילוי, אך עבודת הכהנים הי' בהשתחואה שזהו בחשאי<sup data-n=\"6160\">93</sup> שזהו מד' ביטול בחי' חכ'<sup data-n=\"6161\">94</sup>, וההפרש הוא כידוע שיש רזין ורזין דרזין<sup data-n=\"6162\">95</sup>, סתימין",[["6144","77","<b>שעבד מלך מלך</b>: ב\"ר פט\"ז, ג. רש\"י בהעלותך יב, ח. הנסמן לקמן הערה 79."],["6145","78","<b>קרב לגבי דהינא ואידהין</b>: שבועות מז, ב. ספרי ורש\"י דברים שבהערה הבאה. וראה גם לקח טוב בראשית ב, יב."],["6146","79","<b>הדבק לשחוור וישתחוה </b>[כנשצ\"ל: וישתחוו]<b> לך</b>: ספרי דברים א, ז. הובא ברש\"י שם ובפ' לך טו, יח."],["6147","80","<b>לשחרר</b>: כ\"ה גם (לעיל בחלק המאמרים) בהמאמר כאן. ראה שם הערה 60."],["6148","81","<b>לממה\"מ הקב\"ה</b>: ברכות כח, ב."],["6149","82","<b>הי'</b>: אוצ\"ל: יהי'."],["6150","83","<b>מד'</b>: מדריגת."],["6151","84","<b>בהוי'. . הי' הוה ויהי'</b>: ראה שער היחוד והאמונה פ\"ז. תו\"ח מקץ ריט, ד הערה 62."],["6152","85","<b>מועדים לשמחה</b>: נוסח תפלת העמידה וקידוש ליו\"ט. ראה גם לקו\"ת צו טו, ב. שמ\"ע פח, ד."],["6153","86","<b>זמן שמחתינו</b>: נוסח תפלת העמידה וקידוש ליו\"ט. ראה גם לקו\"ת שמ\"ע פט, א."],["6154","87","<b>חמר חווריין</b>: כריתות ו, א."],["6155","88","<b>מים אין בו שום גוון</b>: ראה פרדס שער עצמות וכלים שער ד, פ\"ד. סה\"מ תרל\"ג ח\"ב ע' תקמג. וש\"נ. תרל\"ח ע' קמה. וש\"נ."],["6156","89","<b>המים. . חכ'</b>: ראה תניא פ\"ג ובמ\"מ הגהות והע\"ק שם. לעיל ח\"א (בחלק המאמרים) המשך מצה זו ספמ\"ב."],["6157","90","<b>הלוים. . לארמא קלא</b>: ראה זהר שמיני לט, א. קרח קעז, ב. לעיל ח\"א (בחלק המאמרים) המשך מצה זו פט\"ל. וש\"נ."],["6158","91","<b>ועבד הלוי הוא</b>: קרח יח, כג."],["6159","92","<b>הוא פי' בינה</b>: ראה ביאוה\"ז בלק — להצ\"צ כרך א — ע' תקכ ואילך. וש\"נ. לעיל ח\"א (בחלק המאמרים) המשך מצה זו פל\"ח. וש\"נ."],["6160","93","<b>עבודת הכהנים. . בחשאי</b>: ראה לעיל שם פט\"ל. וש\"נ."],["6161","94","<b>הכהנים. . חכ'</b>: ראה גם (לעיל בחלק המאמרים) בהמאמר כאן פ\"ג. לעיל המשך מצה זו שם פט\"ל. תו\"ח בשלח ח\"א קסב, ד. וש\"נ."],["6162","95","<b>ורזין דרזין</b>: ע\"פ לשון הזהר בכ\"מ. ראה זהר בראשית מה, ב."]]],[2000480567,"וסדכ\"ס<sup data-n=\"6163\">96</sup>, שעבודת הלוים הי' להמשיך מרזין ועבודת הכהנים הי' להמשיך מרזין דרזין.\n<b>וביאור</b> הענין הנה כתי' אנכי אנכי הוא מוחה פשעיך<sup data-n=\"6164\">97</sup> למעני שלכאורה אינו מובן מהו\"ע ב\"פ אנכי, הנה אנכי הראשון קאי על מד' סוכ\"ע ואנכי השני קאי על מד' שלמעלה מבחי' סוכ\"ע, וכדי שיהי' מוחה פשעיך צ\"ל שימשך מב\"פ אנכי אלו בהוא, שיהי' מוחה פשעיך, שהוא, הו\"ע בינה שתבוא אימא ותקנח לבנה<sup data-n=\"6165\">98</sup>. אך ע\"י מה מגיעים לב' האנכי הנ\"ל, ע\"ז כתי' ממעמקים קראתיך<sup data-n=\"6166\">99</sup>, שיש ב' עומקים, יש עומק הלב שפי' לב הוא בינה, בינה ליבא<sup data-n=\"6167\">100</sup>, ועמק הלב פי' פנימי' בינה<sup data-n=\"6168\">101</sup>. אך יש תעלומות לב<sup data-n=\"6169\">102</sup> שאז מוכרח לומר שלב הו\"ע ל\"ב נ\"ח<sup data-n=\"6170\">103</sup> ותעלומת לב הוא פנימי' אבא פנימי' עתיק<sup data-n=\"6171\">104</sup>. וע\"י עומק הלב פנימי' בינה ממשיכים מאנכי הסוכ\"ע, וע\"י תעלומת לב פנימי' חכ' ממשיכים מאנכי שלמעלה מסוכ\"ע.\n<b>אך</b> עדיין צ\"ל למה לא כתיבה מצות נסה\"מ בפירוש בתורה. הענין הוא דהנה אנו רואים ההפרש שבין תושב\"כ לתושבע\"פ כי תושב\"כ העיקר הוא האותיות כי אם יש נגיעה באות פסול<sup data-n=\"6172\">105</sup> כל הספר אפי' בסדר<sup data-n=\"6173\">106</sup> הקודם ג\"כ אסור לקרות אף שתינוק יכול לקרוא אותה מ\"מ פסול שהעיקר הם האותיות, אבל בתושבע\"פ אנו רואים שהאותיות אינם מעכבים כלל כמשא\"ר שכמה פוסקים מביאים דין אחד זה באותיות אלו וזה באותיות אלו כי העיקר הוא ההשכלה. והענין הוא דהנה אי' בשלשה ספרים ברא הקב\"ה את עולמו בספר וסופר וסיפור זהו אי' בס\"י<sup data-n=\"6174\">107</sup>. ורז\"ל אמרו בשלשה דברים ברא הקב\"ה<sup data-n=\"6175\">108</sup> את עולמו בחכ' ובתבונה ובדעת שנא' הוי' בחכמה יסד ארץ כונן שמים בתבונה<sup data-n=\"6176\">109</sup> בדעתו תהומות נבקעו<sup data-n=\"6177\">110</sup>. ובאמת לא פליגי כי ספר הו\"ע ס\"ת בחי' בינה וסופר הוא שסופר את הספר הוא חכ' וסיפור הוא דיבור שהו\"ע דעת<sup data-n=\"6178\">111</sup> כמ\"ש מפיו דעת<sup data-n=\"6179\">112</sup>, וכמו שאנו רואים בתינוק שאין בו דעת",[["6163","96","<b>וסדכ\"ס</b>: ראה זהר בהקדמה ב, א. ועוד."],["6164","97","<b>אנכי אנכי הוא מוחה פשעיך</b>: ישעי מג, כה. ראה גם להבא להלן לקו\"ת נצבים מה, ד. מאמרי אדה\"ז תקס\"ה ח\"ב ע' תתפ-תתפא."],["6165","98","<b>תבוא אימא ותקנח לבנה</b>: ראה במדב\"ר פי\"ט, ח. תנחומא חוקת ח."],["6166","99","<b>ממעמקים קראתיך</b>: תהלים קל, א."],["6167","100","<b>בינה ליבא</b>: ת\"ז בהקדמה יז, א."],["6168","101","<b>בינה. . פנימי' בינה</b>: ראה גם לקו\"ת סוכות עח, ד. עט, ג."],["6169","102","<b>תעלומות לב</b>: ראה (לעיל בחלק המאמרים) בהמאמר כאן ובהערה 90."],["6170","103","<b>שלב הו\"ע ל\"ב נ\"ח</b>: ראה גם מאמרי אדה\"א שמות ח\"ב ע' תמב ואילך. וש\"נ."],["6171","104","<b>פנימי' אבא פנימי' עתיק</b>: ראה גם מאמרי אדה\"ז תקס\"ה ח\"ב ע' תתסה. לקו\"ת נצבים מט, ד. תו\"ח שמות ח\"א כג, א הערה 951."],["6172","105","<b>נגיעה באות פסול</b>: ראה שו\"ע יו\"ד סעד\"ר, ס\"ד. שו\"ע אדה\"ז הל' תפילין סל\"ב, ס\"ה. ראה גם (לעיל בחלק המאמרים) בהמאמר כאן פ\"ד. ד\"ה ולקחתם לכם פ\"ה."],["6173","106","<b>בסדר</b>: אוצ\"ל: בספר."],["6174","107","<b>בשלשה ספרים. . בס\"י</b>: ראה שם פ\"א, מ\"א."],["6175","108","<b>בשלשה דברים ברא הקב\"ה</b>: ראה תנחומא ויקהל ה. שמו\"ר פמ\"ח, ד."],["6176","109","<b>הוי' בחכ'. . בתבונה</b>: משלי ג, יט."],["6177","110","<b>בדעתו תהומות נבקעו</b>: משלי שם, כ."],["6178","111","<b>ספר הו\"ע ס\"ת. . דעת</b>: ראה (לעיל בחלק המאמרים) בהמאמר כאן פ\"ד. וש\"נ."],["6179","112","<b>מפיו דעת</b>: משלי ב, ו."]]],[2000480568,"אינו יכול לדבר והדיבור הוא לפ\"ע הדעת. וע\"ז אמרז\"ל עריבים עלי ד\"ס<sup data-n=\"6180\">113</sup> יותר מיינה של תורה, ד\"ס הוא מד' הסופר שהוא למעלה מיינה של תורה שהוא בינה. ובזה יובן מה שנה\"מ שהוא חכ' אינה יכולה להתלבש בתורה שהיא בינה וע\"כ היא הלכה למשה מסיני, אך ברמז מצינו אותה בתורה ע\"ד די לחכימא ברמיזא<sup data-n=\"6181\">114</sup> שחכ' מרומז ברמז לבד וכמו קוצו של יו\"ד לגבי יו\"ד<sup data-n=\"6182\">115</sup> שהוא רק ברמז.\n<b>אך</b> עדיין צריך להבין מדוע מצינו מצות רמות ונשגבות שכתובים בתורה, הלא מצות התשובה<sup data-n=\"6183\">116</sup> שכתי' בה כי המצוה<sup data-n=\"6184\">117</sup> אשר אנכי<sup data-n=\"6185\">118</sup> שע\"י מצות התשובה מגיעים באנכי<sup data-n=\"6186\">119</sup> מי שאנכי<sup data-n=\"6187\">120</sup> הלא כתובה בתורה, וכן מצות פרה אדומה שעלי' כתי' אמרתי אחכמה והיא רחוקה ממני<sup data-n=\"6188\">122</sup> והיא כתובה בתורה<sup data-n=\"6189\">121</sup>. אך בפ\"א י\"ל שתירוצה היא בצידה כמ\"ש זאת חוקת התורה<sup data-n=\"6190\">123</sup> שהיא חוקה, אבל בענין תשובה דכתי' בתורה שהיא מצוה גדולה, הענין הוא כי תשובה הוא כשפגם ברצון, וע\"כ צריך להגיע לאוא\"ס שקודם הצמצום שלמעלה מרצון שעי\"ז יכול לעשות רצון חדש, וע\"כ תוכל המצוה הזאת להתלבש באותיות התורה, כי אותיות שרשם מהרשימה<sup data-n=\"6191\">124</sup> שלא נגע בה הצמצום<sup data-n=\"6192\">125</sup> שלמעלה מרצון אותיות צינור<sup data-n=\"6193\">126</sup>, אבל נה\"מ הוא מצוה פרטיות ורצון פרטי אך שהיא מבחי' חכ' ע\"כ לא תוכל להתלבש באותי' התורה. ועוד כי ענין נה\"מ הוא יחוד חו\"ב ע\"כ לא תוכל להתלבש בתורה אלא בדרך רמז.\n<b>וזהו\"ע</b> ושאבתם מים בששון שכל השנה הי' נסה\"י שהוא מד' שמחה אבל בחג הו\"ע נה\"מ שגם בינה תבוא למד' ששון וזהו יחוד חו\"ב<sup data-n=\"6194\">127</sup> אף כי",[["6180","113","<b>עריבים עלי ד\"ס</b>: ראה ע\"ז לה, א וברש\"י שם. סה\"מ תרח\"ץ ע' סד הערה 74."],["6181","114","<b>די לחכימא ברמיזא</b>: ראה רשב\"ם ח\"ש כג, טז. מדרש משלי כב, טו. זהר בראשית כו, ב. הנסמן במאמרי אדה\"ז על פרשיות התורה ח\"ב לע' תשנב."],["6182","115","<b>קוצו של יו\"ד לגבי יו\"ד</b>: ראה גם אגה\"ת פ\"ד. סה\"מ תרח\"ץ ע' סד הערה 76."],["6183","116","<b>מצות התשובה</b>: ראה הנסמן (לעיל בחלק המאמרים) בהמשך יונתי רפ\"כ."],["6184","117","<b>מצות התשובה. . כי המצוה</b>: ראה רמב\"ן נצבים ל, יא. לקו\"ת נצבים מה, ג. מאמרי אדה\"ז תקס\"ה ח\"ב ע' תתעו. לקו\"ש נצבים כרך יד ע' 112 הערה 24."],["6185","118","<b>כי המצוה אשר אנכי</b>: נצבים ל, יא [בדילוג]."],["6186","119","<b>מצות התשובה. . באנכי</b>: ראה לקו\"ת נצבים מה, ג-ד. סה\"מ תרל\"ג ח\"ב ע' תקיט ואילך."],["6187","120","<b>באנכי מי שאנכי</b>: ראה תניא מהדו\"ק ספמ\"ט. לקו\"ת להאריז\"ל תולדות כז, יט בשם הזהר. אבן עזרא תולדות שם. מאמרי אדה\"ז תקס\"ב ח\"א ע' יד. פרשיות התורה ח\"א ע' רט ובהנסמן במ\"מ לשם."],["6188","122","<b>אחכמה והיא רחוקה ממני</b>: קהלת ז, כג. ראה זהר רע\"מ פינחס רכג, א."],["6189","121","<b>מצות פרה אדומה. . כתובה בתורה</b>: ראה לקו\"ת ר\"פ חוקת."],["6190","123","<b>זאת חוקת התורה</b>: חוקת יט, ב."],["6191","124","<b>אותיות שרשם מהרשימה</b>: ראה גם לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה אז ישיר הערה *39. לקו\"ת הוספות לויקרא נא, סע\"ב. סה\"מ ליקוט ח\"ג ע' א ואילך."],["6192","125","<b>מהרשימה שלא נגע בה הצמצום</b>: ראה גם לעיל ח\"א (בחלק המאמרים) המשך מצה זו פ\"ו-ז."],["6193","126","<b>מרצון אותיות צינור </b>[אוצ\"ל: צנור]: ראה זהר הרקיע לזהר בראשית נא, א (כה, ב בדפי הספר). מאמרי אדה\"א בראשית ע' לו. וש\"נ."],["6194","127","<b>ושאבתם. . יחוד חו\"ב</b>: ראה לקו\"ת סוכות כאן פ, ב."]]],[2000480569,"זווגייהו תדיר<sup data-n=\"6195\">128</sup>, אך זהו בחיצוני'<sup data-n=\"6196\">129</sup> לצורך קיום העולמות אבל היחוד שבהנסכים הוא יחוד פנימי' ולכן הי' הב' ספלין בקירוב<sup data-n=\"6197\">130</sup> שמורה על היחוד דחו\"ב. וענין ממעייני הישועה כי יש ב' מעיינות<sup data-n=\"6198\">131</sup> וכשחופרין מעיין צריך לחפור העפר עד שיבוא לגידי המים, ויש ב' מיני עפר יש מד' ונפשי כעפר לכל תהי'<sup data-n=\"6199\">132</sup> ע\"כ צריך לחפור אם הוא באמת, ותורה ג\"כ נק' עפר שהוא גוש עפר<sup data-n=\"6200\">133</sup> כמ\"ש מי מנה עפר יעקב<sup data-n=\"6201\">134</sup> שאינו בגדר מספר, ותורה נתלבשה בדברים גשמים, וצריך להשיב אותה לשרשה ומקורה והרוח תשוב אל<sup data-n=\"6202\">135</sup> כו'. וזהו ע\"י ונפשי כעפר עי\"ז יעשה פתח לבי בתורתיך<sup data-n=\"6203\">136</sup>. ולמעלה ענין ב' מעיינות אלו הוא ב' מזלות ונוצר ונקה<sup data-n=\"6204\">137</sup>.",[["6195","128","<b>חו\"ב. . זווגייהו תדיר</b>: ראה זהר אד\"ז האזינו רצ, ב. ע\"ח שער הכללים פי\"ג. לקו\"ת שה\"ש כ, ב ואילך. סה\"מ תרל\"ח ע' פח. וש\"נ."],["6196","129","<b>חו\"ב. . זווגייהו. . בחיצוני'</b>: ראה ע\"ח שער הכללים ספ\"ה. פי\"ג. שער הזיווגים שט\"ו, פ\"א. שער הנסירה שכ\"ט, רפ\"ב. פרדס שער מהות והנהגה ש\"ח, פי\"ד. סה\"מ תרל\"ח ע' פח ואילך. וש\"נ."],["6197","130","<b>הי' הב' ספלין בקירוב</b>: ראה סוכה מח, סע\"א ואילך (במשנה) וברש\"י שם."],["6198","131","<b>ממעייני הישועה. . ב' מעיינות</b>: להבא להלן ראה לקו\"ת סוכות עט, סע\"ג-ד."],["6199","132","<b>ונפשי כעפר לכל תהי'</b>: ברכות יז, א. סיום תפלת העמידה (אלקי נצור)."],["6200","133","<b>ותורה. . גוש עפר</b>: לקו\"ת בלק סח, ב."],["6201","134","<b>מי מנה עפר יעקב</b>: בלק כג, י."],["6202","135","<b>והרוח תשוב אל</b>: קהלת יב ז."],["6203","136","<b>ונפשי כעפר. . פתח לבי בתורתיך</b>: ראה גם (לעיל בחלק המאמרים) בהמאמר כאן הערה 134."],["6204","137","<b>ב' מעיינות אלו. . ונוצר ונקה</b>: בלקו\"ת שבהערה 131 מציין: וע' במ\"ח דכ\"א א' ב'."]]],[2000480570,"<h3>ביום השמיני עצרת</h3>\n<b></b><b>בס\"ד ש\"ת שנת תרמ\"א ליובאוויטש</b>\nש\"ת\n<b>ביום</b> השמיני עצרת<sup data-n=\"6205\">1</sup> תהי' לכם<sup data-n=\"6206\">2</sup> כל מלאכת עבודה לא תעשו והקרבתם עולה אשה ריח ניחוח להוי' פר אחד איל אחד<sup data-n=\"6207\">3</sup> וכו' ואי' במד\"ר<sup data-n=\"6208\">4</sup> משל למלך שעשה סעודה שבעה ימים וזימן כל אדם שבמדינה בז' ימי המשתה, לאחר שעברו ז' ימי המשתה אמר לאוהבו כבר יצאנו ידי חובותינו מכל בני המדינה נגלגל אני ואתה במה שתימצא ליטרא בשר או ירק או דג כך ביום הראשון הי' מקריבים י\"ג פרים<sup data-n=\"6209\">5</sup> וביום השני י\"ב פרים<sup data-n=\"6210\">6</sup>, ובכלל הי' שבעים פרים כנגד שבעים אומות<sup data-n=\"6211\">7</sup> ביום השמיני אמר הקב\"ה לישראל עצרת תהי' לכם גלגלו במה שאתם מוציאים<sup data-n=\"6212\">8</sup> בפר אחד איל אחד.",[["6205","1","<b>ביום השמיני עצרת</b>: הנחה ממאמר ד\"ה זה שנדפס לעיל בחלק המאמרים. וש\"נ.\nהכותרת שמופיעה כאן בריש המאמר נמצאת בבוך הכת\"י בסוף המאמר. וראה לעיל בחלק המאמרים בריש המאמר כאן ששם נרשם בהכותרת: שמע\"צ."],["6206","2","<b>ביום השמיני עצרת תהי' לכם</b>: פינחס כט, לה."],["6207","3","<b>והקרבתם עולה. . איל אחד</b>: שם כט, לו."],["6208","4","<b>במד\"ר</b>: ראה במד\"ר פכ\"א, כד בשינויים."],["6209","5","<b>ביום הראשון. . י\"ג פרים</b>: פינחס כט, יג."],["6210","6","<b>וביום השני י\"ב פרים</b>: פינחס שם, יז."],["6211","7","<b>שבעים פרים כנגד שבעים אומות</b>: סוכה נה, ב. במד\"ר שם."],["6212","8","<b>מוציאים</b>: אצ\"ל: מוצאים."]]],[2000480571,"<b>ולהבין</b> ענין זה יש להקדים ענין הקרבנות שלכאורה אינו מובן שכשאדם חטא מביא קרבן בהמה גשמי'<sup data-n=\"6213\">9</sup> ומעלה אותה ונתכפר עונו וצ\"ל איך הוא בערך שע\"י בהמה גשמי' תכופר העון, אף שצריך תשובה<sup data-n=\"6214\">10</sup> ג\"כ אבל באמת הרי הקרבן מכפר. אך הנה באמת אי' בזהר שהקרבן אינו לש' אלקים אלא לש' הוי'<sup data-n=\"6215\">11</sup>, וע\"ז כתי' ריח ניחוח להוי'<sup data-n=\"6216\">12</sup>. ולכאורה אינו מובן איך הוא בערך שהקרבן יגיע לש' הוי', שגם הוי' הוא התהות<sup data-n=\"6217\">13</sup> אך הוא בדרך מאיליו וממילא<sup data-n=\"6218\">14</sup> כמ\"ש כי הוא ציוה ונבראו<sup data-n=\"6219\">15</sup> מאליו וממילא ולא כמו ש' אלקים שהוא כח הפועל בנפעל<sup data-n=\"6220\">16</sup> שהו\"ע ל\"ב פעמים אלקים דמע\"ב<sup data-n=\"6221\">17</sup> בעשרה מאמרות<sup data-n=\"6222\">18</sup> בחילופים ותמורות<sup data-n=\"6223\">19</sup> ותמורה תמורות, ולכאורה איך הוא בערך שהבהמה שהתהותה הוא מפרט וחילוף אחד מצירוף אחד דש' אלקים יהי' מזה נ\"ר להוי'. ועוד צ\"ל מאחר דש' אלקים אינו נתרצה הלא מדת הדין מעכב. ועוד י\"ל מה שנת' בספרים דע\"י קרבן נעשה קירוב הכוחות והשמות<sup data-n=\"6224\">20</sup> למעלה ולכאורה איך הוא בערך.\n<b>אך</b> הענין הוא דהנה ארז\"ל מלמד שהי' הקב\"ה בונה עולמות ומחריבן דין הניין לי' יתהון לא הניין<sup data-n=\"6225\">21</sup> שזהו\"ע תהו כמ\"ש דבר ציוה לאלף דור<sup data-n=\"6226\">22</sup>, ויש ע\"ז ב' דיעות א' שקאי על מצות מילה ב' על תורה, ולדעה הא' שקאי על מצות מילה שניתנה לכ' דורות תתק\"פ דורות נקנטו ולדעה הב' שקאי על תורה שניתנה לכ\"ו דורות תתקע\"ד דורות<sup data-n=\"6227\">23</sup> נקנטו<sup data-n=\"6228\">24</sup>, וזהו\"ע התוהו שהי' השבירה<sup data-n=\"6229\">25</sup> והאורות נסתלקו למעלה",[["6213","9","<b>שכשאדם חטא. . בהמה גשמי'</b>: ראה גם לעיל ח\"א (בחלק המאמרים) מאמר ד\"ה סמוכים לעד ובהערה 7."],["6214","10","<b>קרבן בהמה גשמי'. . תשובה</b>: ראה שבועות יג, א. רמב\"ם ריש הל' תשובה."],["6215","11","<b>שהקרבן אינו לש' אלקים אלא לש' הוי'</b>: ראה זהר משפטים קח, א. ויקרא ה, א. לעיל (בחלק המאמרים) בהמאמר כאן ובהערה 17."],["6216","12","<b>ריח ניחוח לה'</b>: ויקרא א, ט. ראה גם לקו\"ש ויקרא כרך לב ע' 1 ואילך."],["6217","13","<b>הוי' הוא התהות</b>: ראה זהר רע\"מ פינחס רנז, סע\"ב. פרדס שער עשר ולא תשע ש\"א, פ\"ט. שער עצמות וכלים שער ד, ספ\"י. שער היחוה\"א פ\"ד. פ\"ז. הערה בסה\"מ ת\"ש ע' 40. וראה ג\"כ לעיל ח\"א (בחלק המאמרים) המשך מצה זו פמ\"ז."],["6218","14","<b>התהות. . בדרך מאיליו וממילא</b>: ראה גם לקו\"ת שה\"ש יד, ג. (לעיל בחלק המאמרים) במאמר כאן ובהערה 12."],["6219","15","<b>כי הוא צוה ונבראו</b>: תהלים קמח, ה. ראה סה\"מ תרל\"ג ח\"ב ע' תלא. וש\"נ. בהערה שלפנ\"ז."],["6220","16","<b>ש' אלקים שהוא כח הפועל בנפעל</b>: ראה גם (לעיל בחלק ההנחות) הנחה ד\"ה ושאבתם מים ובהערות 29-30."],["6221","17","<b>ל\"ב פעמים אלקים דמע\"ב</b>: נמנו בפרטיות בתקז\"ח קיב, ג. ראה מאמרי אדה\"א ויקרא ח\"ב ע' תרכה. וש\"נ. שעה\"י קלב, א ובהערה 3."],["6222","18","<b>בעשרה מאמרות</b>: אבות רפ\"ה."],["6223","19","<b>בחילופים ותמורות ותמורה תמורות</b>: ראה שער היחוד והאמונה פ\"א. המשך תער\"ב ח\"ב ע' א'קב. סה\"מ תרס\"ח ע' קה."],["6224","20","<b>דע\"י קרבן. . קירוב הכוחות והשמות</b>: ראה בחיי ויקרא א, ט (ע' תא). (וראה גם שם) במדבר ז, י. פינחס כט, יג. דברים א, א. אוה\"ת פינחס ע' א'פז. סה\"מ תרכ\"ז ע' עה. וש\"נ. ע' שנא."],["6225","21","<b>מלמד שהי' הקב\"ה. . יתהון לא הניין</b>: ראה ב\"ר פ\"ג, ז. פ\"ט, ב. לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה ר' אבהו פתח והמה כאדם הערה 100."],["6226","22","<b>דבר ציוה לאלף דור</b>: תהלים קה, ח."],["6227","23","<b>מצות מילה. . תורה. . תתק\"פ. . תתקע\"ד דורות</b>: ראה ב\"ר פכ\"ח, ד. תנחומא לך יא. יתרו ט. ראה גם אוה\"ת מטות ע' א'שכב."],["6228","24","<b>נקנטו</b>: כצ\"ל: נקמטו."],["6229","25","<b>התהו שהי' השבירה</b>: ראה ע\"ח שער הכללים פ\"א. לעיל ח\"א (בחלק המאמרים) המשך זאת חנוכת המזבח פי\"ג. וש\"נ."]]],[2000480572,"והכלים נפלו<sup data-n=\"6230\">26</sup> למטה להחיות דצח\"ם<sup data-n=\"6231\">27</sup>, והמכוון הוא כדי שישיבו הניצוץ לשרשו וע\"י שמקריבין הבהמה ע\"ג המזבח, ומי הוא המקריב הוא הכהן איש החסד<sup data-n=\"6232\">28</sup>, ובב\"ר הי' אש שלמטה ואש שלמעלה<sup data-n=\"6233\">29</sup>, ארי' דאכיל קורבנא<sup data-n=\"6234\">30</sup>, ופני ארי' אל הימין<sup data-n=\"6235\">31</sup> שהוא ימין מקרבת<sup data-n=\"6236\">32</sup> ועי\"ז מקריבין הניצוץ לשרשו ומזה נעשה שמחה למעלה<sup data-n=\"6237\">33</sup> עד<sup data-n=\"6238\">34</sup> כמו שני אוהבים נאמנים שהי' בתכלית הקירוב ונתרחקו בריחוק גדול שהריחוק הזה גורם שהקירוב שיהי' אח\"כ יהי' בשמחה גדולה, ולכאורה אינו מובן ממה הוא השמחה אם מחמת המצוה הלא יש כמה מצות ובפרט ת\"ת שכנגד כולם<sup data-n=\"6239\">35</sup> וכן שבת ששקולה כנגד כל המצות<sup data-n=\"6240\">36</sup> ובה יש מ\"ע ול\"ת<sup data-n=\"6241\">37</sup> ושבת הוא אינו אלא עונג ולא שמחה<sup data-n=\"6242\">38</sup>, ואפי' מועדים שהם שמחה<sup data-n=\"6243\">39</sup> מ\"מ אנו רואים ששמחת נשואין הוא בגשמי' שמחה יותר. אך הנה כתיב לזאת יקרא אשה<sup data-n=\"6244\">40</sup> כי מאיש לקחה זאת שחוה נלקחה מצלעותיו של אדה\"ר<sup data-n=\"6245\">41</sup> שאז לא הי' גופים אחרים אלא הוא אחד<sup data-n=\"6246\">42</sup> מצלעותיו, וכן אח\"כ שהי' כמה גופים וגופות מ\"מ שרשן הוא אדם וחוה ושרש שרשן הוא אדם כי גם חוה שרשה מאדה\"ר וזהו בגופים וכן בנשמות ידוע שכל הנשמות הי' כלולים באדה\"ר<sup data-n=\"6247\">43</sup> ואפי' נשמות חדשות שרשן הוא מבחי' עטרה שע\"ג<sup data-n=\"6248\">44</sup> ראשיהן<sup data-n=\"6249\">45</sup> שעטרה",[["6230","26","<b>והאורות נסתלקו למעלה והכלים נפלו</b>: ראה גם ע\"ח שער רפ\"ח ניצוצין שי\"ח, פ\"א. סה\"מ תרל\"ח ע' שנג ואילך. וש\"נ."],["6231","27","<b>והכלים נפלו למטה להחיות דצח\"ם</b>: ראה ע\"ח שער מ\"ן ומ\"ד של\"ט, דרוש ג. לקמן פיסקא אך י\"ל [ושם: דצ\"ח]."],["6232","28","<b>הכהן איש החסד</b>: ראה זהר נשא קמה, ב. צו כז, א. מאמרי אדה\"א דברים ח\"ג ע' תתעג. וש\"נ."],["6233","29","<b>ובב\"ר. . ואש שלמעלה</b>: יומא כא, ב."],["6234","30","<b>ארי' דאכיל קורבנא</b>: ראה זהר בהקדמה ו, ב. מאמרי אדה\"א ויקרא ח\"ב ע' תקלא. וש\"נ. שה\"א עט, ב הערה 13. לעיל ח\"א (בחלק המאמרים) המשך זאת חנוכת המזבח פ\"ה."],["6235","31","<b>ופני ארי' אל הימין</b>: יחזקאל א, י."],["6236","32","<b>ימין מקרבת</b>: סוטה מז, א."],["6237","33","<b>מקריבין הניצוץ לשרשו. . נעשה שמחה למעלה</b>: ראה גם הגהת כ\"ק אדמו\"ר מהר\"ש באוה\"ת בראשית כרך ו ע' 2116. סה\"מ תרכ\"ט ע' קיא."],["6238","34","<b>עד</b>: כנצ\"ל: ע\"ד."],["6239","35","<b>ת\"ת שכנגד כולם</b>: פאה פ\"א, מ\"א. ראה מאמרי אדה\"א שמות ח\"ב ע' תקעא. תו\"ח תצוה ח\"ב שלו, א."],["6240","36","<b>שבת ששקולה כנגד כל המצות</b>: ראה ירושלמי ברכות פ\"א, ה\"ה. נדרים פ\"ג, ה\"ט. שמו\"ר פכ\"ה, יב."],["6241","37","<b>שבת. . יש מ\"ע ומל\"ת</b>: ראה רמב\"ם ריש הל' שבת שתי מ\"ע ושלש מל\"ת."],["6242","38","<b>ושבת. . עונג ולא שמחה</b>: ראה שו\"ע אדה\"ז הל' שבת רסרמ\"ב. מאמרי אדה\"ז תקס\"ה ח\"ב ע' תשנח. פרשיות התורה ח\"ב ע' תקכ. אוה\"ת ברכה כרך ו ע' ב'תקפא ואילך. סה\"מ תש\"ט ע' 130 ובהערות לשם. לקו\"ש דברים כרך ד ע' 1090 הערה 31. בהעלותך כרך יג ע' 25 הערה 13. כרך לג ע' 62 ואילך ובהנסמן שם."],["6243","39","<b>מועדים שהם שמחה</b>: ראה שו\"ע אדה\"ז הל' יו\"ט סתקכ\"ט, ס\"ו. ס\"ז. בהערה שלפנ\"ז."],["6244","40","<b>לזאת יקרא אשה</b>: בראשית ב, כג."],["6245","41","<b>שחוה נלקחה מצלעותיו של אדה\"ר</b>: שם ב, כא-כב."],["6246","42","<b>הוא אחד</b>: אוצ\"ל: היא אחת."],["6247","43","<b>שכל הנשמות הי' כלולים באדה\"ר</b>: ראה תנחומא תשא יב. שמו\"ר פ\"מ, ג. אגה\"ק ס\"ז. לעיל (בחלק המאמרים) בהמאמר כאן ובהערה 36."],["6248","44","<b>נשמות חדשות. . עטרה שע\"ג ראשיהן</b>: ראה רמ\"ז תולדות קלד, ב (ד\"ה יתקיימו). צויין אליו בלקו\"ת צו ז, ג. וש\"נ. פלח הרמון צו ע' כז ואילך. וש\"נ.\nראה גם בענין נשמות חדשות תו\"ח ויקהל ח\"ב תכט, ב. וש\"נ. ובענין נשמות חדשות בשבת לעיל ח\"א (בחלק המאמרים) המשך מצה זו פל\"א. וש\"נ."],["6249","45","<b>עטרה שע\"ג ראשיהן</b>: ראה ברכות יז, א."]]],[2000480573,"לגבי הנשמה היא התחדשות. ולכאורה י\"ל מאחר שמצד הגוף הם אחד ומצד הנפש הם אחד<sup data-n=\"6250\">46</sup> מ\"ע הזיווג, ובאמת מצינו שארז\"ל עד עכשיו מה הוא עושה יושב ומזווג זיווגים<sup data-n=\"6251\">47</sup>, וכן ארז\"ל קשה לזווגם<sup data-n=\"6252\">48</sup> וגבי מטרוניתא דין מוחא קטיעא<sup data-n=\"6253\">49</sup> כו', ולכאורה אינו מובן כיון שמצד הגוף ומצד הנפש הכל שרשן הוא מאדה\"ר היינט וויימען<sup data-n=\"6254\">50</sup> מי וועט נעמען איז אלץ איינש.\n<b>אך</b> הענין הוא דהנה אי' בכהאריז\"ל שאף שכל הנשמות הי' כלולים באדה\"ר אבל לא כולם ממקום אחד יש שהי' כלולים במצחו<sup data-n=\"6255\">51</sup> בחוטמו בעיינין באודנין בשערותיו בפאותיו<sup data-n=\"6256\">52</sup>, וכדי שיהי' עזר וגם כנגדו<sup data-n=\"6257\">53</sup> צ\"ל שניהם ממקום אחד. ונמצא שאחד שנושא אחת יוכל להיות שהי' בתכלית ההתאחדות ונתרחקו בריחוק גדול והוא נתגדל אצל אביו ואמו והיא נתגדלה אצל אביה ואמה והם בעירות רחוקות זמ\"ז וע\"פ הגמ' בן י\"ח לחופה<sup data-n=\"6258\">54</sup> שזהו זמן רחוק ואח\"כ בא איש הבינים ואמר לו שבעיר ההוא יש איש אחד שברצונו לעשות שידוך עמך, וקודם לכן לא הי' יודע כלל אפי' ש' העיר ואינו מכירה וצריך לעשות ריבוי חקירה ודרישה גין זה, אך האיש הבינים הוא מייגע ומשתדל ביז וואנעט ער פירט זיי צונויף, ואח\"כ היחוד הוא להוליד בדומה לו כי איש ואישה י\"ה שורה ביניהם ואח\"כ מולידים בן ובת שהוא ו\"ה<sup data-n=\"6259\">55</sup>, ולע\"ל נא' והי' ביום ההוא יהי' ב\"פ י\"ה<sup data-n=\"6260\">56</sup>, נמצא שו\"ה יהי' ג\"כ י\"ה שהוא בדו\"ל<sup data-n=\"6261\">57</sup>. ע\"כ השמחה היא שמחה גדולה מחמת שקודם הי' בתכלית הקירוב ואח\"כ נתרחקו בריחוק כזה שהוא לא הי' מכירה הנה הריחוק הזה גורם שהקירוב יהי' בשמחה ע\"ד שני אוהבים נאמנים. אך באמת לא נוכל להמציא משל מכל<sup data-n=\"6262\">58</sup> על זיווג הנשמות למעלה, אך מזה נוכל להבין קצת כמו שני אוהבים נאמנים שהי' בתכלית הקירוב ואח\"כ נתרחקו בריחוק גדול שלא הי' יודעים זמ\"ז הריחוק הזה גורם שהקירוב שיהי' אח\"כ יהיה בשמחה. וכן יובן בענין הקרבנות שע\"י שמקריבין הבהמה שהניצוץ הי' קודם בהתאחדות עם השרש ואח\"כ נתרחק ונפל למטה מטה וכשמקרבין הניצוץ לשרשו נעשה מזה שמחה למעלה ועי\"ז",[["6250","46","<b>שמצד הגוף. . ומצד הנפש הם אחד</b>: ראה גם לעיל (בחלק המאמרים) בהמאמר כאן ובהערה 33."],["6251","47","<b>עד עכשיו. . ומזווג זיווגים</b>: ראה ב\"ר פס\"ח, ד."],["6252","48","<b>קשה לזווגם</b>: סוטה ב, א. ראה מאמרי אדה\"ז תקס\"ה ח\"א ע' רלב. ס\"ע רלד ואילך. מארז\"ל ע' צ. שער האמונה נד, ב ואילך. מאמרי אדה\"א ויקרא ח\"א ע' ערב."],["6253","49","<b>וגבי מטרוניתא דין מוחא קטיעא</b>: ראה ב\"ר שם."],["6254","50","<b>וויימען</b>: אוצ\"ל: וועמען."],["6255","51","<b>בכהאריז\"ל. . כלולים במצחו</b>: ראה גם מדרשים שבהערה 43."],["6256","52","<b>בשערותיו בפאותיו</b>: ראה גם לעיל (בחלק המאמרים) בהמאמר כאן ובהערה 40."],["6257","53","<b>עזר. . כנגדו</b>: בראשית ב, יח."],["6258","54","<b>וע\"פ הגמ' בן י\"ח לחופה</b>: אבות פ\"ה, מכ\"א (ולגי' אדה\"ז בסידורו מכ\"ב)."],["6259","55","<b>איש ואשה. . י\"ה. . בן ובת. . ו\"ה</b>: ראה זהר ויקרא יא, ב. רע\"מ צו לד, א. ת\"ז תנ\"ה פח, א. תנ\"ו פט, ב. ביאוה\"ז ח\"ש קל, א."],["6260","56","<b>והי' ביום ההוא יהיה ב\"פ י\"ה</b>: זכרי' יד, ט [בדילוג]. לקו\"ת להאריז\"ל שם. ראה הנסמן במאמרי אדה\"א נ\"ך ע' קנב. סה\"מ תרכ\"ט ע' קכג. וש\"נ."],["6261","57","<b>בדו\"ל</b>: בדומה לו."],["6262","58","<b>מכל</b>: אוצ\"ל: מכוון."]]],[2000480574,"נתבשם ש' אלקים שהגם שאינו נתרצה אבל מ\"מ נתבשם שהשמחה ממתיק הדינים<sup data-n=\"6263\">59</sup>.\n<b>אך</b> י\"ל ענין ריח ניחוח להוי' דמשמע שש'<sup data-n=\"6264\">60</sup> הוי' מועיל ג\"כ שאינו כמו ש' אלקים שרק נתבשם, ועוד דבש' הוי' אינו שייך נתבשם כי ש' הוי' הוא רחמים<sup data-n=\"6265\">61</sup> אלא ע\"כ שגם נתרצה מועיל ג\"כ. הענין הוא דהנה תהו קדם לתיקון<sup data-n=\"6266\">62</sup> ופי' קדם אינו קדם בזמן כי לא הי' רק סדר זמנים<sup data-n=\"6267\">64</sup> אבל לא זמן, אך פי' קדם הוא במעלה<sup data-n=\"6268\">63</sup> שענין התהו הי' ריבוי אור ומיעוט הכלים ובתיקון הוא ריבוי כלים ומיעוט האור<sup data-n=\"6269\">65</sup> ומזה הי' השבירה שנפלו הכלים למטה להחיות דצ\"ח. וענין השבירה יובן כמו תיבת ברו\"ך שבעת שאות ברו\"ך שעומדים כאחת נושאים עליהם ההשכלה ברוך ל' גיבענצט<sup data-n=\"6270\">67</sup> אך כשנתפזרו האותיות<sup data-n=\"6271\">66</sup> ב' בפ\"ע ור' בפ\"ע וכן כולם אז הגם כי האותיות ישנם אך ההשכלה אינו נושא, כך יובן למעלה הנפילה שהיא השבירה שהאותיות נפלו למטה להחיות דצ\"ח ומאחר שאנו רואין שלמטה החי הוא במדריגה תחתונה שהותרה שחיטה<sup data-n=\"6272\">68</sup> ונחירה בשביל האדם<sup data-n=\"6273\">69</sup> מוכרח לומר ששרשו הוא גבוה יותר במעלה וכמשל החומה<sup data-n=\"6274\">70</sup> שהאבן שבראש החומה נופל למטה יותר.\n<b>וענין</b> ריבוי אור<sup data-n=\"6275\">71</sup> אין הפי' שרק ריבוי אור, כי לא לבד שהאורות דתהו מרובים על אורות דתיקון באמת זה האור אחר גמור, כמו שמצינו ויעש אלקים את שני המאורות הגדולים<sup data-n=\"6276\">72</sup> ואח\"כ אמר לכי ומעטי א\"ע<sup data-n=\"6277\">73</sup> שנק' מיעוט, ואנו רואים כי אור הלבנה לגבי אור השמש לבד שהאור הוא במיעוט באמת זהו אור אחר שאינו בערך כלל וזהו רק גדול, ומכש\"כ באורות דתהו שנק' ריבוי מכש\"כ שהוא אור אחר אינו בערך כלל. וכן אנו רואים באור היום שנק' אור, ויקרא לאור יום<sup data-n=\"6278\">74</sup>, לגבי אור השמש",[["6263","59","<b>שהשמחה ממתיק הדינים</b>: ראה גם תו\"א ח\"ש טו, ד. וארא נז, ד. תו\"ח וארא ח\"א סט, ג ואילך. וש\"נ."],["6264","60","<b>שש'</b>: אצ\"ל: שלשם."],["6265","61","<b>ש' הוי' הוא רחמים</b>: ראה ספרי ואתחנן ג, כד. לקח טוב שם. רש\"י ר\"פ בראשית. זהר ויקרא יא, א. אחרי סה, א."],["6266","62","<b>תהו קדם לתיקון</b>: ראה תו\"א בשלח סה, ד. לקו\"ת אמור לז, ד. וש\"נ."],["6267","64","<b>סדר זמנים</b>: ראה ב\"ר פ\"ג, ז. ראה גם סה\"מ תרכ\"ח ריש ע' קסט. פלח הרמון אמור ע' רמו."],["6268","63","<b>תהו קדם לתיקון. . קדם הוא במעלה</b>: ראה גם לעיל (בחלק המאמרים) בהמאמר כאן ובהערה 51."],["6269","65","<b>התהו הי' ריבוי אור. . ובתיקון. . ומיעוט האור</b>: ראה ע\"ח שער הכללים פ\"א ואילך. (לעיל בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה ואהבת את ה' אלקיך הא' ובהערה 81."],["6270","67","<b>ברוך ל' גיבענצט</b>: ראה גם (לעיל בחלק המאמרים) בהמאמר כאן ובהערה 54."],["6271","66","<b>הכלים. . השבירה. . כשנתפזרו האותיות</b>: ראה גם כנפי יונה ח\"ג סנ\"ו. סקמ\"א. תו\"א וישב כז, ג. לעיל ח\"א (בחלק המאמרים) המשך מצה זו הערה 221."],["6272","68","<b>שהותרה שחיטה</b>: פ' ראה יב, כא. סהמ\"צ להרמב\"ם מ\"ע קמו. רמב\"ם הל' שחיטה רפ\"א."],["6273","69","<b>שהותרה. . ונחירה בשביל האדם</b>: נח ט, ג-ד. חולין יז, א. לג, א."],["6274","70","<b>וכמשל החומה</b>: ראה גם לעיל ח\"א (בחלק המאמרים) מאמר ד\"ה גור ארי' יהודה פ\"א. וש\"נ."],["6275","71","<b>וענין ריבוי אור</b>: ראה גם (לעיל בחלק המאמרים) בהמאמר כאן ובהערה 57."],["6276","72","<b>ויעש. . המאורות הגדולים</b>: בראשית א, טז."],["6277","73","<b>לכי ומעטי א\"ע</b>: ראה חולין ס, ב."],["6278","74","<b>ויקרא לאור יום</b>: בראשית א, ה [בדילוג]."]]],[2000480575,"שהוא אור אחר. ויובן זה יותר מע' אור שנברא ביום הראשון הי' אדם צופה ומביט מסוף העולם ועד סופו<sup data-n=\"6279\">75</sup> וידוע הקושי' הי' צריך לכתוב מתחילת העולם כו'. אך הנה כתי' ועלמות אין מספר<sup data-n=\"6280\">76</sup> שיש עולמות הרבה, אך בכלל הם נכללים בשתי עולמות עלדאת\"כ ועלדאת\"ג<sup data-n=\"6281\">77</sup> כמ\"ש ברוך הוי' מעולם ועד עולם<sup data-n=\"6282\">78</sup> פי' עלדאת\"כ ועלדאת\"ג. וזהו הי' אדם צופה ומביט מסוף עלדאת\"כ מלמטלמ\"ע עד סוף עלדאת\"ג מלמעלמ\"ט, ואח\"כ כשנתמעט הראי' כמה יוכל האדם לראות פרסא או מיל<sup data-n=\"6283\">79</sup>, ונמצא כי לבד שהאור הוא מיעוט בכמות קלענירער אור, אלא ממש אחר הוא וזהו בתיקון מיום ראשון, וכש\"כ בריבוי דתהו בודאי אור אחר הוא שלא בערך כלל ומצד זה הי' השבירה. כי באמת מוכרח לומר שעיקר השבירה הי' מצד ריבוי אור ולא מצד מיעוט הכלים. גם זאת אמת שהי' מיעוט הכלים ג\"כ אבל עיקר השבירה מוכרח לומר שהי' מצד ריבוי אור, כי מצד מיעוט הכלים א\"ר<sup data-n=\"6284\">80</sup> בתיקון שהמיעוט מחזיק המרובה<sup data-n=\"6285\">81</sup> כמו הראש שהוא קטן הרבה מהיד והרגל ובהם לא נמצא רק כח אחד כמו כח ההילוך ברגל אבל בראש נמצא כוחות הרבה, ראשונה ג' מוחין חב\"ד ראי' ושמיעה טעם וריח<sup data-n=\"6286\">82</sup> ורק מוכרח לומר שלא מצד מיעוט הכלים הי' השבירה אלא מצד ריבוי האור. וע\"כ ע\"י שמקריבין הבהמה ששרשה היא מריבוי אורות דתהו ועי\"ז נמשך תוס' מרובה בכלים דתיקון וזהו ניחוח להוי' פי' ניחוח נחות דרגא<sup data-n=\"6287\">83</sup> בהוי' דתיקון.\n<b>וענין</b> ריח לא הוא ש' העצם ריח שע\"י הקרבת הקרבן אלא הוא ש' המושאל שא\"ר פעולת הריח שמשיב את הנפש<sup data-n=\"6288\">84</sup> כשאדם נתעלף ע\"י שמריחין לו ריח חזק עי\"ז משיבין לו את הנפש, ופי' נתעלף אינו הסתלקות הכוחות לגמרי כי אז לא הי' מועיל לו הריח, כי למת בלתי חי אינו מועיל ריח, אף שמצד הריח אפשר שהי' מועיל אך המריח איננו, כי לעצם הנפש לא ביכולת להגיע ומריח מצד הגוף איננו, אלא פי' שנתעלף שבאמת החיות נמצאת בלב וההרגש בהכוחות אך חסר הרו\"ש קמיטה וסגירת הלב והכוחות נתעלם<sup data-n=\"6289\">85</sup> למקור אחיזת הנפש עם הגוף והריח",[["6279","75","<b>אור שנברא. . אדם. . ועד סופו</b>: ראה חגיגה יב, א. לעיל (בחלק המאמרים) בהמאמר כאן ובהערה 59."],["6280","76","<b>ועלמות אין מספר</b>: שה\"ש ו, ח. ת\"ז בהקדמה (יד, ב). ראה לעיל ח\"א (בחלק המאמרים) המשך מצה זו רפנ\"ב. וש\"נ."],["6281","77","<b>עלדאת\"כ ועלדאת\"ג</b>: ראה זהר בראשית יח, א. ויצא (ס\"ת) קנב, א. קנח, ריש ע\"ב. וארא כט, ב. ת\"ז בהקדמה א, סע\"א ואילך. תניא פכ\"ו."],["6282","78","<b>ברוך הוי' מעולם ועד עולם</b>: דהי\"א כט, י [בדילוג]. בלקו\"ת פ' ראה יט, ב מציין: זח\"א ויצא קנח, ב. ראה גם לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה כי הנה יוצר הרים על יד הערה 15. תו\"ח שמות ח\"א יח, ג. וש\"נ."],["6283","79","<b>יוכל האדם לראות פרסא או מיל</b>: ראה גם (לעיל בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה ואהבת את ה' אלקיך הא' ובהערה 84."],["6284","80","<b>א\"ר</b>: אנו רואים."],["6285","81","<b>שהמיעוט מחזיק המרובה</b>: ע\"פ ב\"ר פ\"ה, ז. שמו\"ר פי\"א, ה. ויק\"ר פ\"י, ט."],["6286","82","<b>וריח</b>: לעיל (בחלק המאמרים) בהמאמר כאן ניתוסף: ודבור ומחשבה."],["6287","83","<b>ניחוח נחות דרגא</b>: ראה יבמות סג, א. ראה גם לעיל ח\"א (בחלק המאמרים) המשך מצה זו פמ\"ב ובהערה 1312."],["6288","84","<b>הריח שמשיב את הנפש</b>: ראה גם (לעיל בחלק המאמרים) בהמאמר כאן ובהערה 67."],["6289","85","<b>נתעלם</b>: אוצ\"ל: נתעלמו."]]],[2000480576,"מגיע לשם ומעורר ע\"כ משיב את הנפש. ועוד אי' ריח הוא שהנשמה נהנה<sup data-n=\"6290\">86</sup> ממנו ולא הגוף ולא כמו אכילה אף שאכילה פועל קישור הנפש עם הגוף אבל העיקר הוא הגוף אבל ריח העיקר הוא להנשמה ונשמה הוא למעלה מגוף שאין למעלה הימנה ולשם מתייחסת הריח, וכך יובן שע\"י הקרבת הבהמה נעשה מזה ריח שמגיע לאורות דתהו כמו שהם למעלה מאחיזת אורות עם כלים. ועוד י\"ל שענין הריח הוא להשיב הנפש פי' הכוחות שהי' קודם בהתפשטות בגוף ואח\"כ נתעלו לשרשן, הריח פועל להשיב אותם שיתפשטו שנית בגוף שיכול להלוך ברגל ולעשות ביד ולראות בעין ולשמוע באוזן, כך יובן ענין ריח למעלה שע\"י הקרבת הבהמה ממשיכים אורות דתוהו בכלים דתיקון וזהו ריח ניחוח לשון המשכה, ועי\"ז נמשך סליחת עונות. כי הנה ברית כרותה ליגמדה\"ר<sup data-n=\"6291\">87</sup> שאינם חוזרים ריקם שהו\"ע י\"ג מדות מי אל כמוך נושא עון<sup data-n=\"6292\">88</sup> וכו' ויש יגמדה\"ר דמיכה וי\"ג מדות הרחמים דמשה<sup data-n=\"6293\">89</sup>, שע\"י נמשך סליחת עונות שמגיעים למדריגה אם חטאת<sup data-n=\"6294\">90</sup> כו' שאינו מגיע שם חטא כו', והוא ע\"י ממעמקים קראתיך הוי'<sup data-n=\"6295\">91</sup>, שיש שני מיני הוי', הוי' שבסדר השתל' והוי' שלמעלה מסדר השתל'<sup data-n=\"6296\">92</sup>, וע\"י ממעמקים מגיעים לש' הוי' שלמעלה מסדר השתלשלות. ונמצא מה במדות שהם בתיקון אף שהם מדות גבוהים אבל מ\"מ הם מצומצמים כש\"כ ע\"י קרבן שמגיעים בריבוי אורות דתהו שבודאי אינו תופס מקום כלל, וגם אצל הקרבן הי' תשובה ג\"כ ענין ממעמקים, ע\"כ נמשך סליחה ומחילה.",[["6290","86","<b>ריח הוא שהנשמה נהנה</b>: ראה ברכות מג, ב. ראה גם לעיל ח\"א (בחלק המאמרים) המשך זאת חנוכת המזבח פ\"ח ובהערה 134."],["6291","87","<b>ברית כרותה ליגמדה\"ר</b>: ראה ר\"ה יז, ב. לעיל ח\"א (בחלק ההנחות) הנחה ד\"ה הנה אנכי כורת עמך ברית הערה 63."],["6292","88","<b>מי אל כמוך נושא עון</b>: מיכה ז, יח."],["6293","89","<b>יגמדה\"ר דמיכה. . דמשה</b>: ראה לקו\"ת פ' ראה לד, ב. סה\"מ תרל\"ח ע' תפב ואילך. וש\"נ."],["6294","90","<b>אם חטאת</b>: איוב לה, ו."],["6295","91","<b>ממעמקים קראתיך הוי'</b>: תהלים קל, א."],["6296","92","<b>הוי' שבסדר השתל' והוי' שלמעלה מסדר השתל'</b>: ראה לקו\"ת ר\"ה נט, א ואילך. סה\"מ תרל\"ח ע' נה. וש\"נ."]]],[2000480577,"<h3>הוספות</h3>\n<b></b><b>נסיעת כ\"ק אדמו\"ר מהר\"ש למאנטרע<sup data-n=\"6297\">1</sup> </b>\n<b>יו\"ד<sup data-n=\"6298\">2</sup></b>\nב\"ה, מוצאי מנוחה ליו' א' ה' אלול תרט\"ל\nד' הטוב יטיב הכוה\"ח<sup data-n=\"6299\">3</sup> לכ' אה' ידידי הרא\"א<sup data-n=\"6300\">4</sup> נ\"י\nמכ' מויובלון( ) הגיעני נכון, ובד' הקאפטל והמכנסי' כבר אמרתי לו שיותר טוב שיהי'..., ובד' שילוחם לפה, לדעתי אינו נצרך כי ע\"פ עצת הדאק' בעס' חושב אני לנסוע צלחה אחר יו\"ט הבע\"ל אי\"ה למאנטרע. וכמדומה לי אשר הדרך היותר קרובה היא דרך בריסק וארשאו ווין מינחען למאנטרע, וכפי החשבון נשבות אי\"ה",[["6297","1","<b>לפנינו ה' אגרות קודש[ednref_351_א], בקשר לנסיעת כ\"ק אדמו\"ר מהר\"ש, ע\"פ הוראת הרופא דאק' בעס', אל מעיינות הרפואה למאנטרע, בשנת תר\"ם ושהיותו שם. עד שבא חזרה לליובאוויטש. </b>\n<b>נסיעה זאת הי' אמור לצאת מליובאוויטש[ednref_352_ב] ביום ג' פ' נח כ\"ז תשרי תר\"מ ולהיות ש\"ק נח בווין, או בפאריז[ednref_353_ג], וליותר דיוק</b>: נבוא אי\"ה צלחה 45:9 יום ו' עש\"ק בקר לפאריז.\nאמנם מצינו לכה\"פ ב' דרושים[ednref_354_ד] (שנדפסו לעיל ח\"א ע' א וע' ז) שנאמרו לכאורה בליובאוויטש והם: א) ד\"ה לה\"ע ר\"ח שנרשם עליו שר\"ח מ\"ח נח. ב) ד\"ה ואעשך לגוי גדול שלא נרשם עליו תאריך ונאמר לכאורה בפ' לך[ednref_355_ה].\nבמכתבו הק' מכ\"ז מ\"ח ה' לפ' תולדות מאנטרעאוקס[ednref_356_ו] כותב כ\"ק אדמו\"ר מהר\"ש עד יום ד' שבוע העברה (היינו פ' ח\"ש) היתה ישיבתינו.\nבד' אגרות שלפנינו פונה רבינו אל הר' אברהם אבלי פרסון ובהם מבקש שיברר עבורו את הדרך הכי קלה לנסיעה מליובאוויטש למאנטרע דרך ווין, כי שם יוכל לפגוש את בת וחתן אחותו [הרבנית ראדע פריידא] הר' חיים ישעי' וחי' עטא ברלין. לאידך באם א\"א לקיים הפגישה, אז מעדיף לנסוע בדרך קרובה וקלה יותר.\nד' אפשריות נרשמים כאן באופן הנסיעה, בצירוף מפת דרכים.\nזמן חזירתו לליובאוויטש בדיוק אינו ידוע לע\"ע[ednref_357_ז], וראה לעיל (ח\"א ע' ל) שבפ' מקץ התחיל את ההמשך הנודע זאת חנוכת המזבח."],["6298","2","גרות קודש אדמו\"ר מהר\"ש ע' טז."],["6299","3","כתיבה והחתימה."],["6300","4","רב ר' אברהם אבלי בר' נחום[ednref_358_ח] פרסון. ראה אודותיו אג\"ק אדמו\"ר מהורש\"ב ח\"א ע' ע ואילך. התמים [חוברת ו ע' ח] ע' 542 ואילך. ע' שיב ואילך. לקו\"ד ח\"ד[ednref_359_ט] ע' 1360 ואילך. ס' השיחות קיץ ה'ש\"ת ע' 42. תד\"ש ע' 20. ע' 83-4. תש\"ה ע' 9. תש\"ח ע' 207 ואילך. אג\"ק אדמו\"ר מהר\"ש־ אדמו\"ר מהורש\"ב ח\"ה־ אדמו\"ר מהוריי\"צ חי\"ב במפתח שמות אנשים בערכו. ס' תולדות אברהם חיים ראזענבוים ע' נב-נג. ע' סא.\n\n[edn_351_א] כולם נדפסו באגרות קודש שלו (ס\"י-סי\"ג. סס\"ד כדלהלן, ורק על האחרון שבהם בא כ\"ק אדמו\"ר מהר\"ש על החתום), ומשם הועתק חלק חשוב מהערות הבאות לקמן. וכן מכתבי רש\"ק.\n\n[edn_352_ב] כדלקמן אגרת יא.\n\n[edn_353_ג] כדלקמן אגרת יג.\n\n[edn_354_ד] לעיל (שם ע' טו) נדפס עוד מאמר ד\"ה כמגדל דוד, ונדפס מאמר זה שם ע\"פ הנרשם ברשימת המאמרים שבספר התולדות שלו ובראשו הכותרת: ?תולדות\". אבל אולי תיבת “תולדות\" נעתקה כאן מהמאמר דשנת תר\"ל [שהוא המאמר הנ\"ל]. או שמאמר זה לא נאמר בליובאוויטש. ראה לעיל בח\"א שם הערה 1. ראה גם הערות התמימים ואנ\"ש 770 חוב' רצג.\n\n[edn_355_ה] אמנם זמנו בדיוק אימתי בפ' לך נאמר האם בימי החול או בש\"ק (ש\"פ לך ? ח' מ\"ח) אינו ידוע.\n\n[edn_356_ו] לקמן אגרת סד.\n\n[edn_357_ז] ראה לקמן אגרת סד.\n\n[edn_358_ח] אג\"ק אדמו\"ר מהר\"ש ע' כב.\n\n[edn_359_ט] נדפס גם בס' השיחות תרפ\"ז ע' 248."]]],[2000480578,"בש\"ק פ' נח בווין. ובקשתי להודיעני איזה הוטעל טוב אשר נוכל להשיג בשם דגים שיהי' כשרים בלי פקפוק.\nוהשי\"ת יעזור לו ויצליח לו ככל מאוויי נפשו.\n<b>כן</b> יודיעני אם לזמן הנ\"ל יהי' מעל' בווין או בדע\"ב<sup data-n=\"6301\">5</sup>.\n<b>יא</b><sup data-n=\"6302\">6</sup>\nב\"ה, ד' ח' אלול תרט\"ל\nד' הטוב יטיב הכוה\"ח בתוך כ\"י<sup data-n=\"6303\">7</sup>\nלכ' אה' ידידי הרא\"א נ\"י פערסאן\nמוש\"ק העבר כתבתי לו המארשרוט<sup data-n=\"6304\">8</sup> מנסיעתי צלחה, אחר יו\"ט הבע\"ל, שלפ\"ד הדרך היותר קרובה היא ברעסט ווארשאו ווין מענחין מאנטרע הסמוכה לזינווע (גענף).\n<b>כעת</b> כאשר ראיתי בקארט<sup data-n=\"6305\">10</sup>, הדרך מן מינחען לזינווע שהיא עצמה היא הדרך למאנטרע, יש ביניהם מי הים הנק' באדין זיע, ולכן הגם כי מצאתי שפוטניק<sup data-n=\"6306\">11</sup> כמה משלמים מן מינחען<sup data-n=\"6307\">9</sup> עד זינווע, א\"כ הולך מסילת הברזל. אך אולי צריכין לילך מעט בפיראחד<sup data-n=\"6308\">12</sup> על המים, אשר זה איני רוצה, כי לא נסיתי כלל.\n<b>לכן</b> בקשתי לחקור על הוואגזאל<sup data-n=\"6309\">13</sup> דווין אם הולך מסילת הברזל ישר מן מינחען עד מאנטרע. גם אם הולך 3 קלאס, כי חושב אני לנסוע צלחה עם ב' אנשים, אשר לשלם עבורם 2טין קלאס יעלה הוצאה יתירה. גם כפי הנרשם בשפוטניק, המקח מן ווין לזינווע 2 קלאס הוא 93.50 מארק, ומן ווין למענחין 35.75 מארק וממענחין לזינווע 39.80 ס\"ה 75.55 מארק. נמצא דרך מענחין הוא פחות, קרוב לסך 18 מארק. ומסתמא הדרך קצרה. ונמצא כי מווין למאנטרע יש ב' דרכים. את כל זה בקשתי לחקור היטיב בוואגזאל ולהודיעני.\n<b>גם</b> יודיעני אם הבאן<sup data-n=\"6310\">14</sup> מן ברעסט לוארשא ומוארשא לווין הולכים גישלאסין<sup data-n=\"6311\">15</sup> שאין צריכים להמתין בבריסק ובוארשא ובקראקא או צריכים להמתין. ואם כשניסע",[["6301","5","דענענבורג (דווינסק)."],["6302","6","אג\"ק שם ע' יז."],["6303","7","לל ישראל."],["6304","8","רך הנסיעה."],["6305","10","מפה."],["6306","11","וח הנסיעות."],["6307","9","פיסקאות הבאות כותב לפעמים מענחין, ולפעמים (וכן באגרת שלפנ\"ז) מינחען."],["6308","12","ני'."],["6309","13","חנת הרכבת."],["6310","14","כבת."],["6311","15","גורים."]]],[2000480579,"צלחה יום ג' פ' נח מפה הנוכל לבוא על ש\"ק נח לווין, שנבוא לכה\"פ יום ועש\"ק כחצות<sup data-n=\"6312\">16</sup>. כן האכסני' בווין יודיעני.\n<b>יום</b> א' העבר<sup data-n=\"6313\">17</sup> נסעו ב\"א<sup data-n=\"6314\">18</sup> כו' מ' פרומא<sup data-n=\"6315\">19</sup> תי' ומ' חי' עטא<sup data-n=\"6316\">20</sup> תי' לווין, ע\"פ הדיפעש<sup data-n=\"6317\">21</sup> אשר כתבתי להם מוויט' עצת הדאק' בעס', יפ\"ש גיני ויאמר להם שיקיימו כפי הנכתב בדיפעש.\n<b>שבוע</b> זו יהי' פה ח\"א<sup data-n=\"6318\">22</sup> מהר\"י נ\"י מריגא אם יהי' לו באפשרו אראה שיסע ג\"כ לוין ישר מפה.",[["6312","16","אה גם באגרת שלאח\"ז."],["6313","17","' אלול."],["6314","18","נות אחותי — הרבנית ראדע פריידא[ednref_360_י]. חתונתה בשנת תקצ\"א[ednref_361_יא] עם הרה\"ח ר' שניאור שניאורסאהן[ednref_362_יב] בן הרה\"ק הרה\"ח ר' מנחם נחום בן כ\"ק אדמו\"ר האמצעי. נפטרה בחיי אבי' כ\"ק אדמו\"ר הצ\"צ[ednref_363_יג]."],["6315","19","וקרמן. בעלה ר' בנימין ממהוליב. היא גודלה בבית זקנה כ\"ק אדמו\"ר הצ\"צ אחר מות אמה בילדותה (ס' הצאצאים ע' 169 מס' 82). נז' באג\"ק אדמו\"ר מהורש\"ב ח\"ד מאור יום ועש\"ק ט\"ו טבת תרס\"ח ע' רמב לרפו\"ש."],["6316","20","<b>ברלין. בעלה ר' חיים ישעי' ברלין — ראה בסמוך הערה 23. ועד\"ז מופיע שמה בדאמען- פעראיין מא' מרחשון תרע\"ב-תרע\"ג</b>: ”בערלין חיי' עטע, ריגא\"[ednref_364_יד].\nבאוה\"ת סידור ע' רפא כותב[ednref_365_טו]: ”בהמפתח שבתחילת כת\"י 1059 [תרי\"ט] רשום (וכנראה שהיא העתקה מכי\"ק אדמו\"ר הצ\"צ): ”חתונת נכד[ת]י איטקא תי' מה יפו פעמיך בנעלים[ednref_366_טז]\". [”נכד[ת]י איטקא\" הנ\"ל אולי היא מרת חוה אסתר (אטא)[ednref_367_יז] ברלין בת הרבנית ראדע פריידע[ednref_368_יח] בתו של כ\"ק אדהצ\"צ]\".\nראה גם אג\"ק אדמו\"ר מהורש\"ב ח\"ג ע' רנג מ\"ש לר\"י ברלין: ”כי זוגתי תי' כמדומה שכתבה לזוגתו ב\"ד בדבר נסיעתי לפאריז\"."],["6317","21","מברק."],["6318","22","תן אחותי [הרבנית ראדע פריידא — ראה לעיל הערה 18].\n\n[edn_360_י] כ\"ה ב”היום יום\" בתחלתו בשלשלת היחס כ\"ק אדמו\"ר הצ\"צ ס\"ג מערכת בנותיו. במכתב אדמו\"ר הריי\"צ מאוורוטש לאביו כ\"ק אדהצ\"צ מאור ליום ב' ח' מר\"ח כותב: אחותי ראזע פריידע*.\n\n[edn_361_יא] הדרושים שאמרו בעת החתונה ראה רשימת מאמרי דא\"ח של כ\"ק אדמו\"ר הצ\"צ ע' יג.\n\n[edn_362_יב] ראה אג\"ק אדמו\"ר מהוריי\"צ ח\"ד ע' תקט.\n\n[edn_363_יג] שהרי ר' שניאור נשא עוה\"פ בשנת תר\"ט או תר\"י (לקו\"ד ח\"א ע' 204).\n\n[edn_364_יד] כרם חב\"ד ג ע' 200.\nושם: בהיות דודי מוהר\"נ [ נחום, בן כ\"ק אדמו\"ר האמצעי] מנעזין פה הי' מתפלא מאד על העדר ידיעה מכלתו אחותי ראזע פריידע תי' אשר כבר הגיע עתה להמליט, וכהיו' כותב ג\"כ שע\"ע לא קבל שום מכתב מבנו מוהר\"ש [ שניאור], ויש לו צער מזה, וממילא ג\"א [ גם אני] אינני מקבל נחת מזה, לכן להודיעני משלומה ומלידתה למז\"ט.\n\n[edn_365_טו] ומשם לרשימת מאמרי דא\"ח של כ\"ק אדמו\"ר הצ\"צ ע' קלז. פלח הרמון ויקרא ע' תקנז.\n\n[edn_366_טז] רשימת הדרושים שנאמרו בעת חתונתה ראה אוה\"ת ופלח הרמון הנ\"ל.\n\n[edn_367_יז] ב\"ספר היחס\" למשפחת ריבלין (ירושלים תרצ\"ה) ע' 20 מס' 169 היא ? ?מרת חי' עטא-איטקא\" מוזכרת בטעות כבתו של ר' זלמן ריבלין משקלוב. בעוד הנכון הוא שהיתה נינתו. ב”תולדות משפחת הרב מלאדי\" (תל-אביב תש\"ו) ע' 28 מס' 115: ?חי' אסתר (איטא)\", וב”ספר הצאצאים\" ע' 169 מס' 82 נשתבש: ?חוה. . \".\n\n[edn_368_יח] ראה גם לעיל הערה 18."]]],[2000480580,"<b>יב</b><sup data-n=\"6319\">24</sup>\nב\"ה, יו' א' י\"ט אלול תרט\"ל\nד' הטוב יטיב הכוה\"ח בתוך כ\"י\nלאה'<sup data-n=\"6320\">25</sup> ידידי מהרא\"א נ\"י\nמכ' מן ג' החלף הגיעני מוש\"ק. וידע כי עיר ווין אינה נצרך לי כלל למטרת נסיעתי צלחה, כ\"א להתראות עם ח\"א שי' וב\"א<sup data-n=\"6321\">26</sup> תי'. וכאשר קבלתי מכ' מח\"א שי' אשר נעלם ממנו אם יהי' בעת הנ\"ל בווין אינה צריכה לי כלל.\n<b>והדרך</b> שכ' מעל' מווין ללונדוא — לונדוא סאנגליא בערין, מקומות לונדוא וסאנגלי' לא מצאתים במפה. וכפי הנראה הדרך היותר קרובה היא מוארשא לפראג. מפראג דרך שטראסבורג ובאזעל בערין מאנטריע, או מוארשא דרך ברלין פפ\"ד לבאזעל בערין מאנטרא. לכן בקשתי לחקור היטיב בוואגזאל, הדרך על היבשה היותר קרובה מוארשא למאנטרע או לבערין, כי הכל חד. ושיהי' איזה מקום שנוכל לשבות שם, שכאשר נסע צלחה יום ה' בקר מוארשא אזי נבוא למקום ההוא לכה\"פ ביום ועש\"ק קודם חצי היום, או תיכף אחר חצי היום.\n<b>כן</b> אם יאמרו לו שהדרך היותר קרובה וישרה היא דרך ווין דוקא אזי בקשתי להודיעני הוטעל (אכסניא) של א\"י<sup data-n=\"6322\">27</sup>, כי דרכי להתאכסן יותר טוב בהוטעל של א\"י מפני האיבה, שמאחר שאין אני אוכל ממאכלם יותר טוב שלא להתאכסן אצלם, כי חוששני מפני האיבה. גם בכלל ההוטעלין הם יותר טובי' ובמנוחה יותר מכמו אצל יהודי בעל אכסני'. לכן יודיעני הוטעל טוב סמוך לאכסניא של ר' מרדכי וואייסמאן חיות, בכדי שיהי' בנקל להתראות עם ח\"א וב\"א שי', אם יהי' אז בווין, וגם להשיג ממנו דגים על ש\"ק.\n<b>וגם</b> בקשתי לזרז תשובתו, ולא ימשיך תשובתו כ\"כ כמו שעל ב' מכ' הקודמי' המשיך התשובה הרבה.\nלדון וכו'<sup data-n=\"6323\">28</sup> תו\"מ<sup data-n=\"6324\">29</sup> אחר הקריאה.\n<b>מוס\"פ</b> מכ' ימחול למסור לח\"א מהר\"י<sup data-n=\"6325\">23</sup> נ\"י שזוג' ב\"א לא תראה כשימסור לו.",[["6319","24","אג\"ק שם ע' כ."],["6320","25","<b>לאה'. . מהרא\"א וכן הוא גם באגרת שלאח\"ז. בשני האגרות שלפנ\"ז</b>: לכ' אה'. . הרא\"א."],["6321","26","בת אחותי — מ' חי' עטא ברלין — ראה לעיל הערה 20."],["6322","27","ינו יהודי."],["6323","28","אגרת בשריפה."],["6324","29","יכף ומיד."],["6325","23","ורינו הרב ר' ישעי' ברלין. ראה אודותיו ס' השיחות תש\"ח ע' 177 ואילך. וש\"נ. מפתח השמות באג\"ק אדמו\"ר מהר\"ש־ אדמו\"ר מהורש\"ב ח\"ה־ אדמו\"ר מהוריי\"צ חי\"ב־ חי\"ג בערכו. חי\"ד ע' קנג־ חט\"ו ע' יב. ס' המשפיע כפי שנסמן במפתח שמות בערכו. אגרות בעל התורת חסד ירושלים תשס\"א. קובץ יגדיל תורה נ. י. חוב' נט ע' ריב וע' רטז.\nזוגתו מרת חי' עטא — ראה לעיל הערה 20."]]],[2000480581,"<b>יג</b><sup data-n=\"6326\">30</sup>\nב\"ה, אור ליו' ב' ה' תשרי תר\"ם לפ\"ק\nד' הטוב יטיב החוגמ\"ח<sup data-n=\"6327\">31</sup> בתוך כ\"י\nלאה' ידידי מהרא\"א נ\"י\nשני מכ' מן יועש\"ק ואור ליו' ב' הגיעני. כן קבלתי מכ' מח\"א מהר\"י נ\"י אשר קיבל ב' דיפעשין מאחיו<sup data-n=\"6328\">32</sup> מריגא שיבא לריגא (מסתמא רצונם לנסוע אל<sup data-n=\"6329\">33</sup> חה\"ס או יוהכ\"פ לביתם) ואשר א\"א לו להניח זוג' ב\"א תי' בעצמה בווין לכן תיסע עמו ג\"כ לריגא, וא\"כ אין לי כלל מה לנסוע דרך ווין. ולכן חושב אני לנסוע אי\"ה צלחה דרך דענ\"ב ועדקון ברלין פאריז למאנטרע, למען להתראות עם הפ'<sup data-n=\"6330\">34</sup> דפאריז אשר ב' המקומות אשר אני נוסע לשם הם בפראיינקרייך, אשר על מקומם יודעים תהלוכותם יותר טוב. רק ר' לויק<sup data-n=\"6331\">35</sup> נ\"י יסע דרך ווין כי נצרך לו לנסע דרך וארשא.\n<b>הגם</b> שזהו רחוק שישאר ח\"א וב\"א יחי' בווין עד זמן נסיעתי צלחה, עכ\"ז אולי כו' ורצונם הי' להתראות עמי, אזי יבואו למאנטרע, אשר לא רחוק הוא מווין שעולה הנסיעה רק ערך 28 רו\"כסף, רוביל סיג' שלנו, 2טע קלאס.\n<b>חושב</b> אני לשבות אי\"ה פ' נח בפאריז, כי לפי החשבון נבוא אי\"ה צלחה שעה 9.45 יום ועש\"ק בקר לפאריז, ומשם הוא 18 שעות למאנטרע.\n<b>סד</b><sup data-n=\"6332\">36</sup>\nב\"ה, יום ה' ך\"ז מ\"ח תרום<sup data-n=\"6333\">37</sup> לפ\"ק\nמאנטרעאוקס\nכ' אה' ידידי עוז הרה\"ח המופ' וו\"ח י\"א\nמו\"ה שמואל דובער<sup data-n=\"6334\">38</sup> נ\"י\nת\"ל<sup data-n=\"6335\">39</sup> על החוה\"ש<sup data-n=\"6336\">40</sup> כה לחי נכון יצוה חסדו עלהבא.\n<b>מכ'</b> נשלח לי מביתי וקבלתיו היום, והנני למלאות מבוקשו להודיע לו משלומי",[["6326","30","אג\"ק שם ע' כא"],["6327","31","חתימה וגמר חתימה."],["6328","32","רב ר' שלמה זלמן ברלין. ראה אודותיו אג\"ק אדמו\"ר מהורש\"ב ח\"ה במפתח השמות בערכו. ס' המשפיע במפתח השמות בערכו. ראה גם כרם חב\"ד ג במפתח השמות בערכו."],["6329","33","<b>אוצ\"ל</b>: על."],["6330","34","פרופסור."],["6331","35","<b>ר' לוי יצחק אידלעויץ, נאמן בית רבינו. נזכר בכ\"מ ומהם</b>: לקו\"ד ח\"א ע' לו. ע' קו. ס' השיחות תש\"ב ע' 101 ואילך. תד\"ש ע' 4. ע' 18. ע' 149. תש\"ה ע' 30. ע' 101."],["6332","36","אג\"ק שם (מהדורת תשס\"ב) ע' קיא."],["6333","37","<b>אוצ\"ל</b>: תר\"ם."],["6334","38","יפקין מבאריסאב (תקס\"ח-תרמ\"ט) — ראה אודותיו מאמרי אדה\"א קונטרסים ע' תקכו הערה 13. רשימת הרב\"ש במפתח אנשים."],["6335","39","ודה לא-ל."],["6336","40","חיים והשלום."]]],[2000480582,"ישר מפה, ות\"ל כי שלום לנו, והתחלתי להרגיש תועלת<sup data-n=\"6337\">41</sup> בעזהשי\"ת. בפה האויר חם וטוב. עד יום ד' שבוע העברה היתה ישיבתינו ביעועאי, אך מפני כי בפה מאנטרעאוקס האויר יותר חם ויותר זך לכן קבענו ישיבתינו פה עד יום א' פ' וישלח נסע שלו' וצלחה לבאיעריטש, ואם האויר חם שם עד שאוכל לרחוץ במי הים נשב שם ג\"ש<sup data-n=\"6338\">42</sup> אי\"ה, ואם איננו חם כ\"כ אזי נסע לבתינו שלו' דרך ‘„ריז.\nקבלתי הסכום כפי שהבטיח ר\"מ נ\"י כץ לרא\"פ.\nת\"ל ישיבתינו הוא במנוחה, ובאמת גם מתחלה לא הי' כלל ממה כו'.\n<b>ויקבל</b> החוה\"ש והברכה מאד\"ש<sup data-n=\"6339\">43</sup> כנפשו וידידו עוז דו\"ש מלונ\"ח<sup data-n=\"6340\">44</sup>\n<b>שמואל </b>",[["6337","41","הנסיעה למעיינות הרפואה."],["6338","42","לשה שבועות."],["6339","43","אדון השלום."],["6340","44","ורש שלומו מלב ונפש חפצה."]]],[2001910073,"<h3>הקבצו ושמעו בנ\"י</h3>\n<b>בס\"ד, ויחי מ\"ט ב'\nש\"פ ויחי ש' אמ\"ת וצד\"ק לפ\"ק (נא' לעת ערב)</b>\n<b>הקבצו</b> ושמעו בנ\"י<sup data-n=\"1\">1</sup>, ושמעו אל ישראל אביכם<sup data-n=\"2\">2</sup>, ופי' ברבות במקומו<sup data-n=\"3\">3</sup> שמכאן זכו ישראל לק\"ש כו', וע' בגמ' פסחים<sup data-n=\"4\">4</sup>, ומסיים במד\"ר הנ\"ל שמע ישראל ממערת המכפלה, אותו דבר שצויתנו עדיין הוא נוהג בנו ה' אלקינו הוי' אחד<sup data-n=\"5\">5</sup>, וצ\"ל מה\"ע דקדוק הלשון אותו דבר כו' עדיין נוהג כו', והיתכן שלא יהי' נוהג ח\"ו שהרי זהו מ\"ע<sup data-n=\"6\">6</sup> בפרט, וגם כוללת כל המצות<sup data-n=\"7\">7</sup> כמ\"ש וזאת המצוה<sup data-n=\"8\">8</sup> כו' וכמשי\"ת<sup data-n=\"9\">9</sup>, וגם מהו בנו דוקא, ויובן בהקדם ענין ק\"ש שאומרים הוי' אלקינו הוי' אחד, וצ\"ל מהו ב' פעמים הוי', ואיתא בספרים (ע' בס' כד הקמח<sup data-n=\"10\">10</sup> אות יו\"ד מהבחיי בשם הר\"א מגרמיזא<sup data-n=\"11\">11</sup>) שג' שמות הוי' אלקינו הוי' רומז על מ\"ש אני ראשון ואני אחרון<sup data-n=\"12\">12</sup>",[["1","1","<b>הקבצו ושמעו בנ\"י</b>: מאמר זה לאחרי הפתיחה מיוסד על מאמר ד\"ה שמע ישראל משנת תרל\"א (סה\"מ תרל\"א ח\"ב נמצא בדפוס). ונדפס גם בסה\"מ תרל\"ג בתוך ד\"ה וידבר כו' אנכי ע' קלד ואילך. וש\"נ. תרס\"ה ע' קכח ואילך (והוא המאמר דכאן בתוס' הגהות וכו'). סה\"מ ליקוט ח\"ב ע' רכו ואילך. סה\"מ תש\"ד ע' 142 ואילך המשך וידבר אלקים אכה\"ד [וכן צ\"ל בסה\"מ תרל\"ג כאן ע' קלג], והמאמרים שלאח\"ז.\nבבוך זה 1130 — גוכתי\"ק וחלק בכת\"י הר\"ש סופר — נרשם בהמפתח מאמר הראשון ד\"ה שמע ישראל (דף א), אמנם דפים אלו אינם נמצאים בהבוך. ומאמר דידן מתחיל מדף ו.\nדרוש זה נזכר במאמר (שנדפס לאח\"ז) ד\"ה קדש ישראל לה' פ\"ד על יד הערה 140.\nהנחת כ\"ק אדמו\"ר מהורש\"ב מדרוש זה נדפסה לקמן בחלק הנחותיו [ומשם נעתקו התיבות שבהכותרת: ”ש\"פ . . ערב)\"]."],["2","2","<b>הקבצו . . ישראל אביכם</b>: ויחי מט, ב (כנרשם בהכותרת)."],["3","3","<b>ברבות במקומו</b>: ראה ב\"ר פצ\"ח, ג."],["4","4","<b>וע' בגמ' פסחים</b>: נו, א."],["5","5","<b>שמע ישראל . . ה' אלקינו הוי' אחד</b>: ואתחנן ו, ד."],["6","6","<b>שהרי זהו מ\"ע</b>: ראה שו\"ע אדה\"ז ריש הל' ק\"ש."],["7","7","<b>כוללת כל המצות</b>: ראה גם מאמרי אדה\"א ויקרא ח\"ב ע' תקסט. וש\"נ. סה\"מ תרל\"ט ח\"ב ע' תפג. וש\"נ. פלח הרמון אמור ע' שעח. וש\"נ."],["8","8","<b>וזאת המצוה</b>: ואתחנן ו, א. ראה לקו\"ת ואתחנן ד, א. ט, א. מאמרי אדה\"א הנחות תקע\"ז ע' רנה. וש\"נ. לקמן מאמר ד\"ה קדש ישראל לה' רפ\"ה ובהנסמן שם."],["9","9","<b>וכמשי\"ת</b>: ראה לקמן ספ\"ג. בהמאמר שם."],["10","10","<b>בס' כד הקמח</b>: במהדורת שעוועל כתבי רבינו בחיי ס\"ע קצז. מובא גם בסה\"מ תר\"ם ח\"ב ס\"ע תרצד ובהערה 16."],["11","11","<b>הר\"א מגרמיזא</b>: ר' אלעזר מגרמיזא בעל הרוקח."],["12","12","<b>אני ראשון ואני אחרון</b>: ישעי' מד, ו."]]],[2001910074,"ומבלעדי אין כו' שע\"ז רומז תי' אלקינו שמבלעדי אין אלקים, וצ\"ל זה, ויובן בהקדם פי' וענין תיבת אחד<sup data-n=\"13\">13</sup>, הנה נודע שבתיבת אחד הד' הוא ד' רבתי<sup data-n=\"14\">14</sup>, וד' הוא בחי' דבור שבדבר הוי' שמים נעשו<sup data-n=\"15\">15</sup>, לעולם הוי' דברך נצב בשמים<sup data-n=\"16\">16</sup>, שהדבור מחי' ומהוה אותם תמיד מאין ליש כו', שאל\"כ הי' חוזר לאין ואפס כו' כמ\"ש בסש\"ב ח\"ב<sup data-n=\"17\">17</sup>, והנה בחי' ד' רבתי הוא בחי' דבור שבמח'<sup data-n=\"18\">18</sup> דהיינו מקור הדבור ונקרא בחי' במאמר אחד יכול להבראות שהוא בחי' בראשית נמי מאמר הוא<sup data-n=\"19\">19</sup> שהוא מאמר כללי שכולל כל עשרה מאמרות דהיינו שהוא דבור שבמח', ועד\"מ למטה באדם שקודם שמדבר צריך לסדר הדבור במח' איך לדבר, דהנה יש ב' בחי' הא' הוא בחי' מח' שבדבור והב' דבור שבמח', שהרי האדם כשמדבר דבר שכל בהכרח שיחשוב בעת דבורו מה הוא מדבר כו', ומ\"מ עיקרו הוא הדבור רק שצריך להחזיק מוחו ולחשוב דבורו שמדבר לבד, אבל בחי' דבור שבמח' העיקר הוא המח' שחושב בעיון השכל לבד, ולא נק' דבור שבמחשבה רק מפני שענין המחשבה זו הוא שמסדר איך יהי' דבורו לכן על שם זה נק' דבור שבמח', ואפ\"ל עוד ע\"ד שמצינו בר\"א בר\"ש בזבחים דק\"ב<sup data-n=\"20\">20</sup> הובא בש\"ע<sup data-n=\"21\">21</sup> ה' ת\"ת ספ\"ג, שמחמת עיון מחשבתו בד\"ת הוציא ד\"ת מפיו גם במקום שאין רשאי לדבר שם בד\"ת, שגם דבור זה בכלל דבור שבמח' יחשב, שהרי התירו זה בש\"ע ה' ת\"ת הנ\"ל, והנה המכוון הוא שהגם שנתהוה בחי' אחד שהוא ז' רקיעים וארץ וד' רוחות העולם<sup data-n=\"22\">22</sup> שזהו פירוש אחד, כמארז\"ל כד אמליכתי'<sup data-n=\"23\">23</sup> כו' ולד' רוחות תו לא צריכת, מ\"מ הם בבחי' אחד דהיינו שהם בבחי' ביטול. ולהבין זה איך הם בחי' אחד, אך הענין הוא דהנה למעלה אינו כמו למטה, דהנה למטה אנו רואים שהדבור נעשה נפרד לעצמו, אבל למעלה א\"א לומר כן<sup data-n=\"24\">24</sup> שהרי אין לך דבר שחוץ ממנו, וכמ\"ש את השמים ואת הארץ אני מלא<sup data-n=\"25\">25</sup>, וא\"כ א\"א לומר שהדבור נעשה דבר נפרד, אלא הוא בבחי' ביטול, ומה שנראה העולם ליש ודבר נפרד היינו רק בבחי' השתלשלו' שנעשה ע\"י צמצומים עי\"ז, או שם<sup data-n=\"26\">26</sup> נראה ליש ודבר נפרד, אבל לגבי עצמותו אין שייך לומר",[["13","13","<b>ויובן בהקדם . . אחד</b>: ראה בכ\"ז אמרי בינה בתחלתו. בסידור שער הק\"ש. סה\"מ תרל\"ג כאן בהערה."],["14","14","<b>אחד . . ד' רבתי</b>: מסורה גדולה ואתחנן ו, ד וריש בראשית. זהר בהקדמה יב, א. פינחס רלו, ב."],["15","15","<b>שבדבר הוי' שמים נעשו</b>: תהלים לג, ו."],["16","16","<b>לעולם הוי' דברך נצב בשמים</b>: תהלים קיט, פט."],["17","17","<b>בסש\"ב ח\"ב</b>: פ\"א."],["18","18","<b>ד' רבתי . . דבור שבמח'</b>: ראה גם מאמרי אדה\"א דברים ח\"א ע' רפג ואילך."],["19","19","<b>במאמר אחד . . בראשית נמי מאמר הוא</b>: אבות רפ\"ה. בראשית א, א. ר\"ה לב, א. ראה מאמרי אדה\"א דברים ח\"ב ע' תעז. וש\"נ. סה\"מ תרכ\"ז ע' רפב ואילך. לקמן מאמר ד\"ה כי תבואו וכו' ושבתה הארץ פ\"ב ואילך. סה\"מ מלוקט ג' ע' קסד [וכן צ\"ל במאמרי אדה\"א קונטרסים ע' תקלו] ואילך. וש\"נ."],["20","20","<b>דק\"ב</b>: ע\"ב."],["21","21","<b>בש\"ע</b>: אדה\"ז."],["22","22","<b>ז' . . וד' רוחות העולם</b>: ראה לקמן מאמר ד\"ה להבין וכו' בענין הציץ הערה 55."],["23","23","<b>כד אמליכתי'</b>: ראה ברכות יג, ב. אמרי בינה פתח השער בתחילתו."],["24","24","<b>למטה . . שהדבור . . למעלה א\"א לומר כן</b>: ראה תניא פכ\"א. ראה גם לקמן מאמר ד\"ה במשנה וכו' ר' נהוראי אומר פ\"א."],["25","25","<b>את השמים . . מלא</b>: ירמי' כג, כד."],["26","26","<b>עי\"ז, או שם</b>: בסה\"מ תרל\"א ותרל\"ג כאן ע' קלה: עי\"ז."]]],[2001910075,"בחי' דבר נפרד לפי שכולא קמי' כלא חשיב<sup data-n=\"27\">27</sup> כנודע ואין לך דבר שחוץ ממנו וע\"כ הדבור שם בתכלית הביטול, ולכן גם העולמות שנתהוו מבחי' דבור גם הם בטלים. וביאור הענין דהנה גם דבור של האדם ג\"כ א\"א לומר שהוא נעשה נפרד<sup data-n=\"28\">28</sup> לגמרי מן האדם שהרי אנו רואים שמי שקיבל מרבו שלמדו חכ' ה\"ה מקושר לו בתכלית עד שתלמידו משליך כל עניני עצמו ועוסק לטובת רבו, עד שגם אבידת רבו קודמת לאבידת אביו שאם<sup data-n=\"30\">30</sup> היות שהטעם הוא מפני שרבו שלמדו חכמה הביאו לחיי העוה\"ב<sup data-n=\"29\">29</sup> מ\"מ הרי בן נמשך ממוח האב<sup data-n=\"31\">31</sup> שזהו המשכה עצמיות כמשנ\"ת במ\"א, ע' בד\"ה וכל שיח השדה<sup data-n=\"32\">32</sup>, ובבה\"ז בראשית בד\"ה לא טוב היות<sup data-n=\"33\">33</sup> האדם לבדו, ובמאה\"ז<sup data-n=\"34\">34</sup> ע\"פ הנ\"ל, ורבו שלמדו חכ' לא השיג ממנו כ\"א הארת חכמתו ע\"י דבורו לבד, שהרי על עצם חכמתו לא קאים אינש אדעתי' דרבי'<sup data-n=\"35\">35</sup> עד מ' שנין שנא' ולא נתן כו' עד היום הזה<sup data-n=\"36\">36</sup>, שהוא סוף ארבעים שנה, ומ\"מ בחי' הדבור דרבו עדיף מעצם כח האב שבבן כו', וע' במ\"א בענין ג' ד' גמול דלים<sup data-n=\"37\">37</sup> שההשפעה הוא חלק עשירי<sup data-n=\"38\">38</sup>, והוא רק עשירי במספר, אבל לא באיכות, והוא מפני שקאי על הדבור כו', ומאחר שפועל התקשרות בזולתו כנ\"ל עכצ\"ל שאינו נעשה נפרד לגמרי מן האדם המדבר הדבור כו', אלא שמה שאומרים שהדבור נעשה נפרד זהו שנראה לעין זולתו כאלו הוא נפרד, אבל באמת אינו כן, וכ\"ש דבורו של ממה\"מ הקב\"ה חי וקיים לעולם ואינו נפרד ח\"ו אפי' רגע, רק שכך עלה ברצונו שע\"י העבודה יהי' נמשך בחי' חידוש הישינו' שעיקר בחי' זו הוא בשביל לזכות את האדם שע\"י עבודתו יומשך זה כו' כמו שכל העולם לא נברא אלא לצוות לזה<sup data-n=\"39\">39</sup> כו', וזהו ענין אחד דהיינו שהגם שנתהוו מבחי' דבור ז' רקיעים וארץ ולמעלה הוא בחי' ז'",[["27","27","<b>שכולא קמי' כלא חשיב</b>: ראה זהר בהקדמה יא, ב. ראשית חכמה שער היראה ש\"א, פ\"ז [ז, רע\"א]. מאמרי אדה\"ז תקס\"ו ע' שמא. מאמרי אדה\"א דברים ח\"ב ע' תרנג."],["28","28","<b>דבור . . א\"א לומר . . נפרד</b>: ראה לקמן מאמר ד\"ה כי תבואו וכו' ושבתה הארץ רפ\"ד ושם מציין: ”בד\"ה וככה תאכלו\" — תרל\"ז פע\"ט. סה\"מ תר\"ם ח\"א ע' שטו וע' תמח."],["30","30","<b>שאם</b>: כ\"ה בכ\"מ — ראה גם (לקמן בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה תקעו בחדש שופר על יד הערה 33. סה\"מ תרל\"ח ע' ה. וש\"נ."],["29","29","<b>אבידת רבו קודמת . . לחיי העוה\"ב</b>: ראה ב\"מ לג, א במשנה. לקו\"ת ויקרא ו, רע\"א. סה\"מ תר\"ם ח\"ב ע' תרה. וש\"נ."],["31","31","<b>הרי בן נמשך ממוח האב</b>: ראה תניא פ\"ב. תו\"ח בא ח\"א קטז, סע\"ב. וש\"נ. לקו\"ש שמות כרך יא ע' 5 הערה 48."],["32","32","<b>בד\"ה וכל שיח השדה</b>: ראה סה\"מ תר\"ם ח\"ב ע' תרב ואילך ובהנסמן שם."],["33","33","<b>ובבה\"ז . . לא טוב היות</b>: בראשית ב, ב."],["34","34","<b>ובמאה\"ז</b>: ביאוה\"ז להצ\"צ כרך ב ע' תריד ואילך."],["35","35","<b>לא קאים אינש אדעתי' דרבי'</b>: ראה ע\"ז ה, ב. מאמרי אדה\"א ויקרא ח\"ב ע' תמד. וש\"נ. תו\"ח בשלח ח\"א ריז, ג הערה 418. המשך וככה תרל\"ז ספל\"ה. סה\"מ תרנ\"ב ע' צה. תרנ\"ז ס\"ע מט ואילך."],["36","36","<b>ולא נתן . . היום הזה</b>: תבוא כט, ג."],["37","37","<b>ג' ד' גמול דלים</b>: שבת קד, א."],["38","38","<b>שההשפעה הוא חלק עשירי</b>: ראה גם תו\"א יתרו ע, סע\"ב ואילך. עא, ד. לקו\"ת ברכה צג, ב. סה\"מ תרל\"ח ע' תפח. וש\"נ. תר\"ם ח\"א ע' קכו. וש\"נ. לקמן מאמר ד\"ה קדש ישראל לה' ובהערה 100."],["39","39","<b>שכל העולם . . לצוות לזה</b>: ראה ברכות ו, ב."]]],[2001910076,"היכלות<sup data-n=\"41\">41</sup> ז' מדות<sup data-n=\"42\">42</sup>, וזהו ח'<sup data-n=\"40\">40</sup>, וד' הוא בחי' ד' רוחות, ד' חיות המרכבה פני ארי' פני שור<sup data-n=\"43\">43</sup> כו', וארי' הוא מקור ושרש של כל החיות<sup data-n=\"44\">44</sup> ושור הוא שרש ומקור של כל הבהמות<sup data-n=\"45\">45</sup> ונשר של כל העופות<sup data-n=\"46\">46</sup> ובחי' אדם היינו שרש ומקור של שכלים<sup data-n=\"48\">48</sup> נבדלים<sup data-n=\"47\">47</sup> מ\"מ גם הם בטלים שם, וכדי שיהי' בחי' אחד זה צ\"ל תחלה ש' הוי' וז\"ע ה' אחד, דהיינו כדי שיתהוה בחי' הדבור עליון צ\"ל מקודם בחי' הוי' דהיינו יו\"ד צמצום ה' התפשטות<sup data-n=\"49\">49</sup> וי\"ו המשכה וזהו הוי' אחד.\nב) <b>ואמנם</b> פי' וענין הוי' אלקינו היינו ענין נשמות כי נשמות ישראל עלו במח'<sup data-n=\"50\">50</sup> מח' עילאה שאינו שייך אל הדבור, וכנ\"ל שיש דבור שבמח', וממילא מובן שכשם שבבחי' הדבור יש ב' בחי' דבור בעצם שכולל בתוכו מח' שבדבור ודבור שבמח', כן במח' עצמה יש בחי' מחשבה השייכה לדבור כנ\"ל כו' ויש מח' שהוא עצם בחי' המח' עצמה שאינה שייכה כלל לדבור עדיין, וזהו כמ\"ש בזהר מחשבה ויובלא<sup data-n=\"51\">51</sup> כו' שהכוונה זהו על בחי' החכ' עילאה עצמה, ושם שרש נש\"י, והנה כמו שהמח' של אדם מתאחד עם עצם הנפש יותר מבחי' דבור כי הדבור נראה עכ\"פ שנעשה נפרד מעצמותו, אבל מח' מתאחד כו', כמו\"כ נש\"י מתאחדים ביחוד אמיתי עם אוא\"ס והוא ע\"י אותיות התורה כי ישראל מתקשראן באוריי'<sup data-n=\"52\">52</sup> ואורייתא בקוב\"ה, כי שרש ס\"ר נשמות<sup data-n=\"53\">53</sup> ישראל<sup data-n=\"54\">54</sup> הם בחי' ס\"ר אותיות התורה<sup data-n=\"55\">55</sup>, ולכן",[["41","41","<b>ז' היכלות</b>: ראה זהר בראשית לח, א ואילך. פקודי רמד, ב ואילך. לקו\"ת שלח לו, ג. לז, ד. מאמרי אדה\"ז תקס\"ה ח\"ב ע' תתה (ובנו\"ש שם ע' תתו) ואילך. תקס\"ז ע' רכד ואילך. תקס\"ח ח\"א ע' תצא. מאמרי אדה\"א במדבר ח\"ג ע' תתקצה ואילך. אוה\"ת דברים ס\"ע יט ואילך. וישב כרך ו ע' תתרצה. פלח הרמון בחוקותי ע' תסו."],["42","42","<b>ז' מדות</b>: ראה תניא פ\"ג."],["40","40","<b>ולמעלה . . ז' היכלות . . וזהו ח'</b>: וכ\"ה בסה\"מ תרל\"א כאן. ועד\"ז הוא בסה\"מ תרס\"ה כאן ע' קלא. תש\"ד כאן ע' 152. תרל\"ג כאן ע' קלו (התיבות: ”וזהו ח'\" הי' כתוב בהנחה ונמחקו בגוכתי\"ק) . סה\"מ ליקוט ח\"ב כאן ע' רכח."],["43","43","<b>פני ארי' פני שור</b>: ראה יחזקאל א, י."],["44","44","<b>וארי' הוא מקור . . החיות</b>: ראה טעמי המצות להרח\"ו ר\"פ ויקרא. אור החיים אחרי יז, יד. לקו\"ת בהעלותך לא, ג. מאמרי אדה\"א דברים ח\"ד ע' א'רו וע' א'רפה. סה\"מ תרל\"ח ע' יז. וש\"נ."],["45","45","<b>ושור הוא שרש . . הבהמות</b>: ראה בהערה שלפנ\"ז. מאמרי אדה\"א שמות ח\"א ע' כח. וש\"נ. סה\"מ תרכ\"ט ע' קי. וש\"נ. סה\"מ תרל\"ח ע' יח. וש\"נ."],["46","46","<b>ונשר של כל העופות</b>: ראה לעיל הערה 44. לקו\"ת נשא כח, ג. תו\"ח יתרו ח\"ב ער, א. סה\"מ תרכ\"ט שם."],["48","48","<b>שכלים נבדלים</b>: ראה גם לקמן מאמר ד\"ה זכור רפ\"ה. וש\"נ."],["47","47","<b>אדם . . של שכלים נבדלים</b>: ראה גם לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן על יד הערה 37. לעיל הערה 44. סה\"מ תרל\"א כאן ותרל\"ג כאן ע' קלו (והגם שהמלאכים."],["49","49","<b>הוי' . . יו\"ד צמצום ה' התפשטות</b>: ראה אגה\"ת פ\"ד. לקו\"ת נצבים מה, ג. מאמרי אדה\"ז תקס\"ה ח\"ב ס\"ע תתעז ואילך. סה\"מ תרל\"ח ע' קו. וש\"נ."],["50","50","<b>נשמות ישראל עלו במח'</b>: ראה ב\"ר פ\"א, ד. לקו\"ת שה\"ש יז, ד. יט, ב. לקמן מאמר ד\"ה אז ישיר פ\"ה (ד\"ה ואמנם). מאמר ד\"ה זכור ספ\"ב ובהנסמן שם. תו\"ח שמות ח\"א לב, ב ובהערה 248. סה\"מ תר\"ם ח\"א ע' שטז. וש\"נ."],["51","51","<b>מחשבה ויובלא</b>: ראה זהר ח\"ש קכג, א."],["52","52","<b>ישראל מתקשראן באוריי'</b>: ראה זהר אחרי עג, א."],["53","53","<b>שרש ס\"ר נשמות . . אותיות התורה</b>: ראה לקו\"ת בהר מא, ב."],["54","54","<b>ס\"ר נשמות ישראל</b>: ראה רמב\"ן בדרשת תורת ה' תמימה [כתבי הרמב\"ן ח\"א ירושלים תשכ\"ד ע' קסב]: וקבלת רז\"ל כי לא נבראו בשנוי פרצופים אלא בששים רבוא. תניא פל\"ז. מאמרי אדה\"ז תקס\"ו ס\"ע קצ ואילך. תק\"ע ע' קד. סה\"מ תרמ\"ד ע' רסה. תרע\"ח ע' שיב."],["55","55","<b>ס\"ר אותיות התורה</b>: ראה ז\"ח שה\"ש עד, ד. מג\"ע אופן קפו. לקו\"ש טו\"ב כסלו תשמ\"א כרך כ ע' 419 בהערה. שו\"ת הצ\"צ חאבהע\"ז סרמ\"ט (צה, א)."]]],[2001910077,"ישראל ר\"ת יש ששים רבוא<sup data-n=\"56\">56</sup> אותיות לתורה, וז\"ע מ\"ש ישראל עלה במח' היינו במח' של אותיות התורה<sup data-n=\"57\">57</sup>, ולכן נקראו בנים וכמ\"ש בנים אתם להוי' אלקיכם<sup data-n=\"58\">58</sup> כו', והיינו כמו שהבן נמשך ממוח האב כמו\"כ נש\"י נמשכים מח\"ע, והענין כי פי' ה' אלקיכם היינו זו\"נ<sup data-n=\"59\">59</sup> כנודע, ויש לפרש זה לפי משנ\"ת לעיל ששרש נש\"י מבחי' מח' שהוא ע\"פ מ\"ש בזהר מח' ויובלא כו', שקאי על נשמות הגבוהות שזוכים לבחי' חיה ונשמה מחו\"ב וכמ\"ש בזהר ר\"פ משפטים דצ\"ד ב' זכה יתיר יהבין לי' נשמתא מסט' דאו\"א, שמבואר בכתבי האריז\"ל שמאותו זיווג העליון דאו\"א יוצאין משם נשמת בנ\"א כו', אלא שעדיין אינם ראויות ואינם נשלמות עד שיזדווגו זו\"נ דאצי' ואז הם יוצאין מזיווג ההוא, וכ\"כ בע\"ח שער מ\"ן ומ\"ד דרוש ד', ונשמות אלו הם אחים וריעים לזו\"נ דאצי' מפני ששרשם מאו\"א, אך לפמשנ\"ת בסש\"ב פי\"ח, הנה גם בנשמות דבי\"ע ג\"כ יתכן לפרש כן, שהרי גם מי שיש לו רק נפש ממל' דמל' דעשי'<sup data-n=\"60\">60</sup> כו' בתוכו בחי' חכ' שבה אוא\"ס, וזהו שנת' כאן שע\"י התו' שהיא בז\"א<sup data-n=\"61\">61</sup> כמ\"ש זאת התורה אדם<sup data-n=\"62\">62</sup> שקאי על רמ\"ח אברי' דז\"א<sup data-n=\"63\">63</sup>, וע\"י אמצעי' התורה שישראל מתקשראין באורייתא ואורייתא בקוב\"ה עי\"ז באים לשרשם ומקורם הוא בחי' חו\"ב שז\"ע ה' אלקינו שאומרים בק\"ש שקאי על חו\"ב דאצי'<sup data-n=\"64\">64</sup> כו', וזהו ג\"כ דכתי' בישראל (ישעי' מ\"ו ג') העמוסים מני בטן, דהנה כמו שיש עיבור למטה כמו\"כ קודם התגלות ולידת הנשמה הוא בבחי' עיבור בבטן אימא (דהיינו בבחי'<sup data-n=\"66\">66</sup> מל'<sup data-n=\"65\">65</sup>) וכמ\"ש חי הוי' אשר עמדתי לפניו<sup data-n=\"67\">67</sup>, והנה ארז\"ל כשהתינוק במעי אמו נר דולק על ראשו ומלמדין אותו כל התורה<sup data-n=\"68\">68</sup>, דהיינו מ\"ש נש\"י עלו במח' דהיינו במח' דאותיות",[["56","56","<b>ישראל ר\"ת יש ששים רבוא</b>: ראה מגלה עמוקות שם. סידור מהרי\"ק שער חג המצות ע' סה. פני יהושע קדושין ל, א ד\"ה ת\"ר."],["57","57","<b>במח' של אותיות התורה</b>: ראה ז\"ח רות פח, ד."],["58","58","<b>בנים אתם להוי' אלקיכם</b>: פ' ראה יד, א."],["59","59","<b>ה' אלקיכם היינו זו\"נ</b>: ראה גם לקו\"ת שמיני יט, א. סה\"מ תרל\"ג ח\"ב ע' תעא. תר\"ם ח\"ב ע' תרה וע' תשפז. לקמן בהנחה כאן על יד הערה 58. תרס\"ה כאן ע' קלא."],["60","60","<b>נפש ממל' דמל' דעשי'</b>: בתניא שם: נפש דנפש דמל' דעשי'. ראה גם סה\"מ תרל\"ח ע' תפג. וש\"נ. תר\"ם ח\"א ע' תיט. וש\"נ. הגהת כ\"ק אדמו\"ר מהר\"ש באוה\"ת בראשית כרך ו ע' תתרכא.\nבאוה\"ת שם נדפס: בסש\"ב פ\"כ. ולכאו' צ\"ל כבפנים: פי\"ח."],["61","61","<b>התו' שהיא בז\"א</b>: ראה ע\"ח שער הכללים ספ\"א. שער המוחין ש\"כ, פ\"ג. שער דרושי הצלם שכ\"ה, דרוש ח (קרוב לתחילתו). שער יעקב ולאה של\"ז, פ\"א. מבוא שערים ש\"ב ח\"ג, פ\"ו. זהר פקודי רלח, ב ובהגהות מהרח\"ו ומק\"מ שם."],["62","62","<b>זאת התורה אדם</b>: חוקת יט, יד. ראה לקו\"ת האזינו עה, א."],["63","63","<b>רמ\"ח אברי' דז\"א</b>: ראה מ\"ח סדר מועד מס' הבריאה דערבית פ\"י, מט\"ו. לקמן מאמר ד\"ה אז ישיר משה הערה 81."],["64","64","<b>ה' אלקינו . . חו\"ב דאצי'</b>: ראה זהר ואתחנן רסג, א. ת\"ז ת\"ע קלו, ב. פע\"ח שער הק\"ש ש\"ח, פ\"ז. פי\"א. סהמ\"צ להצ\"צ ע' קכד."],["66","66","<b>דהיינו בבחי' מל'</b>: וכ\"ה בסה\"מ תרל\"א כאן. בסה\"מ תרל\"ג כאן ע' קלז ליתא — ראה סה\"מ תרס\"ה כאן ע' קלב."],["65","65","<b>עיבור בבטן אימא . . מל'</b>: זהר בהקדמה יג, סע\"א."],["67","67","<b>חי ה' אשר עמדתי לפניו</b>: לשון הכתוב מלכים-ב ה, טז. בסה\"מ תש\"ד כאן ע' 153 צויין: ראה מ\"א יז, א (זח\"ג סח, ב. זח\"א רלג, ב)."],["68","68","<b>כשהתינוק . . כל התורה</b>: ראה נדה ל, ב. מפרשי הע\"י שם. לקו\"ת שלח מד, א. תו\"ח בא ח\"א קכט, א. וש\"נ. בשלח קפ, ג. וש\"נ. לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן על יד הערה 65."]]],[2001910078,"התורה, והנה עי\"ז שהוא בבחי' עיבור ומלמדין אותו עי\"ז נותנין לו הכח לקיים תו\"מ למטה כו', וזהו נר דולק על ראשו, נר היינו מ\"ש נר הוי' נשמת אדם<sup data-n=\"69\">69</sup> והוי' יו\"ד ה' הוא בחי' תושב\"כ ותושבע\"פ ו\"ה הוא בחי' מצות<sup data-n=\"70\">70</sup>, דהיינו שעי\"ז יכולה הנשמה לקיים תו\"מ למטה, וזהו העמוסים מני בטן העמוסים לשון יום יום יעמס לנו<sup data-n=\"71\">71</sup>, או מל' אבי העמיס עליכם<sup data-n=\"72\">72</sup> כו', שהוא בחי' עול שנותנין להנשמה כח לקיים תו\"מ, ונמצא מבואר איך שרש נש\"י הם מאו\"א, והנה גם לבחי' זו צ\"ל ג\"כ בחי' הוי' דהיינו יו\"ד צמצום ה' התפשטות כו', כדי שיעלו במח', רק מ\"מ מאחר שעלו במח', וגם היו בעיבור בטן אימא כו', ולכן שייך לומר ואהבת<sup data-n=\"73\">73</sup>, מה שלכאו' קשה איך שייך הציווי על אהבה<sup data-n=\"74\">74</sup> הלא היא מדה שבלב, ואיך שייך ציווי ע\"ז, דמ\"נ אם יש לו אהבה א\"צ לציווי, ואם לאו מה מועיל הציווי כו', אך משום כי נשמות ישראל נקראו בנים למקום ע\"כ האהבה טבעית אצלם כי ממילא נמשך להם אהבה כמו אהבת הבן אל האב, ולכך יש באדם כח למסור נפשו על קדושת השם, וזהו כמ\"ש ברע\"מ פ' תצא כברא דאשתדל<sup data-n=\"75\">75</sup> בתר אבוי ואימיה דרחים לון יתיר מגרמיה ונפשי' ורוחי'<sup data-n=\"76\">76</sup> ונשמתי' כו' כמובא בסש\"ב ס\"פ יו\"ד, והגם שזהו ענין בני עלי' שמועטי' המה<sup data-n=\"77\">77</sup>, מ\"מ",[["69","69","<b>נר הוי' נשמת אדם</b>: משלי כ, כז."],["70","70","<b>מצות</b>: בסה\"מ תש\"ד כאן ע' 153 ניתוסף: ו' הם מצות וה' אחרונה תפלה."],["71","71","<b>יום יום יעמס לנו</b>: תהלים סח, כ."],["72","72","<b>אבי העמיס עליכם</b>: מלכים-א יב, יא. דברי הימים-ב י, יא."],["73","73","<b>בטן . . ואהבת</b>: אוצ\"ל: בבטן . . ואתחנן ו, ה."],["74","74","<b>הציווי על אהבה</b>: ראה גם לקמן מאמר ד\"ה ראה קראתי בשם פ\"ב פיסקא והענין. וש\"נ. (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן על יד הערה 71. סהמ\"צ להצ\"צ ע' קצט[ednref_1_א]. רה, ב ד\"ה להבין [ובמהדורת אותיות מרובעות נשמט]. מאמרי אדה\"א בראשית ע' תקמ. ויקרא ח\"ב ע' תשלז. סה\"מ תרל\"א ח\"א ע' ע. וש\"נ. ע' שלט ואילך. תרל\"ה ח\"א ע' קלא. תרל\"ח ע' רנו. וש\"נ. תר\"ם ח\"א ע' רפג. וש\"נ. פלח הרמון תזריע ע' קכח. ספר הערכים חב\"ד ח\"א ע' תרצב הערות 3-4. מאמר ד\"ה כי תשא תשי\"ג. ד\"ה אם בחוקותי תשמ\"ה.\nראה גם בשם המגיד שני המאורות ח\"ב להרי\"א עפשטיין ע' 30 [ושם: מהה\"מ דמעזריטש . . מהבעש\"ט]. סה\"מ תרצ\"ט ע' 8. תש\"א ע' 116. תש\"ט ע' 40 (הב'). סה\"ש תש\"ו ע' 11. אג\"ק מאת כ\"ק אדמו\"ר מהוריי\"צ ח\"ג ע' תכו[ednref_2_ב]. אג\"ק כ\"ק אדמו\"ר זי\"ע חי\"א ע' שכ. וראה גם סה\"מ מלוקט ב' ע' רמה בשם הבעש\"ט.\nבאג\"ק מהוריי\"צ ח\"ג שם: הצ\"צ סיפר שבש\"פ ואתחנן תקנ\"ו אמר אדה\"ז דרוש ע\"פ ואהבת את ה\"א. ויש לציין שדרוש בפתיחא זו משנת תקנ\"ו הנה לע\"ע אין ידוע ממ\"א — ראה מאמרי אדה\"ז הקצרים ע' תרטז. ויש להוסיף דרוש זה לרשימת מאמרי אדה\"ז שנה זו בכרם חב\"ד **4 ע' 358."],["75","75","<b>ברע\"מ פ' תצא כברא דאשתדל</b>: רפא, סע\"א (כפי שהובא בתניא כאן־ פמ\"ד (סג, א). פמ\"א (נח, רע\"א. לקו\"ת שה\"ש ו, ב)."],["76","76","<b>דאשתדל . . ורוחי'</b>: בזהר דאשתדל בהון . . רוחי'."],["77","77","<b>בני עלי' שמועטי' המה</b>: סוכה מה, ב. תניא כאן.\n\n[edn_1_א])והוא דרוש אדה\"ז משנת תקס\"ד. ראה סה\"מ תקס\"ד ע' שמט — ושם נרשם הדרוש בין ש\"פ בחוקותי לש\"פ במדבר.\n\n[edn_2_ב])באג\"ק שם ע' תכג בהערה כותב שהאגרת ”נדפסה בהתמים ח\"ב ע' (סז [פא]). קובץ מכתבים א\". אך זו טעות שנעתקה מהמכתב שנדפס שם לפנ\"ז ע' תכב. וצ\"ל: התמים ח\"ד ע' מד."]]],[2001910079,"ישנו בחי' בכאו\"א<sup data-n=\"78\">78</sup> רק שהוא בהעלם ע\"ש. והנה מה שהקדים תחלה ואמר שמע ישראל, הכוונה הוא דפי' שמע הוא לשון הבנה<sup data-n=\"79\">79</sup>, והיינו להוציא האהבה מהעלם אל הגילוי כו' שזהו ע\"י התבוננות דוקא כי תבונה אותיות בן ובת<sup data-n=\"80\">80</sup> היינו אהבה ויראה<sup data-n=\"81\">81</sup>, ובינה נק' אם הבנים<sup data-n=\"82\">82</sup> וכמ\"ש כי אם לבינה תקרא<sup data-n=\"83\">83</sup>, ובכדי להוציא את האהבה מהעלם לגילוי הוא ע\"י התבוננות שמתבונן איך שהוי' אלקינו נש\"י עלו במח' העצמי' שמתאחדת עם עצמות אוא\"ס, והוי' אחד היינו בחי' דבור שנתהוה מזה יש ודבר נפרד ומ\"מ הוא בבחי' אחד לפי שכולם בטלים אצלו דכולא קמי' כלא חשיב, ועי\"ז ממילא יבא לבחי' ואהבת, דהיינו שעי\"ז יוצא האהבה מהעלם אל הגילוי, וא\"ז בכלל ציווי כו', וכתי' גם את העלם נתן בלבם<sup data-n=\"84\">84</sup> פי' שלפי\"ע שכאו\"א פועל בעצמו להוציא מהעלם אל הגילוי בחי' האהבה המוסתרת לפי ערך זה ממש מברר חלקו בעולם שיזדכך העולם ע\"י עבודתו מחטא אדה\"ר ושבה\"כ כו', ולפ\"ז מובן ענין בחי' ג' שמות הוי' אלקינו הוי', שע\"י אמצעית בחי' אלקינו שפירושו אלקים שלנו כמ\"ש בלק\"ת<sup data-n=\"85\">85</sup> סוף ביאור כי כארץ תוציא צמחה עי\"ז נמשך יחוד אלקותו ית' בעולם עד שיהי' נראה לכל איך שהוי' אחד שז' רקיעים וארץ וד' רוחות העולם וכן כל מה שנחלק לז' וד' שנת\"ל בטלים בתכלית הביטול לבחי' אלף אלופו ש\"ע<sup data-n=\"86\">86</sup> כו', מה שעכשיו לא ניתנה רשות לעין לראות כמ\"ש בסש\"ב ח\"ב פ\"ג ע\"ש.\nג) <b>והנה</b> מעתה י\"ל מאחר דנש\"י עלו במח' העצמי' שהיא בחי' מח' עילאה שהיא בחי' גבוה מאד וא\"כ למה ירדה להתלבש בגוף ונה\"ב, שלכאו' היא ירידה גדולה מאד אלא ודאי שהוא ירידה צורך עלי'<sup data-n=\"87\">87</sup> וא\"כ מהו ענין העלי' שאח\"כ ומה יכול להיות עלי' יותר גדולה מבחי' מח' עילאה, אך הענין הוא דהנה כתי' ויקח רמח",[["78","78","<b>בחי' בכאו\"א</b>: וכ\"ה בסה\"מ תרס\"ה כאן. ואולי הפיענוח: בחינתה בכאו\"א. בסה\"מ תש\"ד כאן: בחי' ומדרי' זו בכאו\"א."],["79","79","<b>שמע הוא לשון הבנה</b>: ראה זהר אד\"ר נשא קלח, ב. לקו\"ת פינחס פ, א. מאמרי אדה\"א ויקרא ח\"ב ע' תשלו. וש\"נ. הנחות תקע\"ז ע' קמח. וש\"נ."],["80","80","<b>תבונה אותיות בן ובת</b>: ראה זהר (אד\"ז) האזינו רצ, ב. רצא, א. תניא פט\"ז ובמ\"מ הגהות והע\"ק לשם. לקו\"ת מסעי צ, א. מאמרי אדה\"ז תקס\"ה ח\"ב ע' תרכג. פרשיות התורה ח\"א ע' לג. שעה\"י קי, ב. תו\"ח בראשית כח, ד ובהערה 26. ביאוה\"ז להצ\"צ בלק כרך א ע' תקכ ואילך."],["81","81","<b>בן ובת היינו אהבה ויראה</b>: ראה תניא שם ובמ\"מ הגהות והע\"ק לשם. לקו\"ת ש\"ש סז, א. מאמרי אדה\"א ויקרא ח\"ב ע' תשפ. וש\"נ. שמות ח\"א ע' נג. וש\"נ."],["82","82","<b>ובינה נק' אם הבנים</b>: ראה זהר ויחי ריט, א. יתרו פד, א. פה, ב. פרדס שעה\"כ שכ\"ג, פ\"א מערכת אם הבנים. לקו\"ת שמ\"ע פח, ד. שעה\"י קי, ב ובהערה 19."],["83","83","<b>כי אם לבינה תקרא</b>: משלי ב, ג. ראה אוה\"ת משלי כרך א ע' תקמז."],["84","84","<b>גם את העלם נתן בלבם</b>: קהלת ג, יא. ראה גם לקו\"ת במדבר ה, ב. ו, ג. סה\"מ תרס\"ה כאן ע' קלג. תש\"ד כאן ע' 154. תר\"ם ח\"א ע' סט. וש\"נ. לקמן מאמר ד\"ה [נקדישך] וביאור הענין על יד הערה 39 ואילך."],["85","85","<b>אלקינו . . אלקים שלנו כמ\"ש בלק\"ת</b>: נצבים נג, סע\"ג (וראה גם הנסמן במ\"מ לשם). בלק עג, ב. אוה\"ת דברים כרך ו ע' ב'רסג. לקמן מאמר ד\"ה והי' אור הלבנה פ\"ב."],["86","86","<b>אלופו ש\"ע</b>: לשון ב\"ר פ\"כ, ב."],["87","87","<b>ירידה צורך עלי'</b>: ראה הנסמן באוה\"ת עקב ע' תפא."]]],[2001910080,"בידו<sup data-n=\"88\">88</sup> ופי' בזוה\"ק שהוא בחי' רמ\"ח תיבין שבק\"ש<sup data-n=\"89\">89</sup>, וכמ\"ש בחרבי ובקשתי ות\"א בצלותי ובעותי<sup data-n=\"91\">91</sup>, וצ\"ל מהו שייכות ענין רמח וקשת לק\"ש שנק' ק\"ש בשם רמח, וביאור הענין הוא, דהנה מה שנת\"ל ששרש נש\"י עלו במח' עילאה והאהבה אצלם היא טבעית היינו רק מצד שרש נפש האלקי' כו', שהוא חלק אלקה ממעל<sup data-n=\"92\">92</sup> כמ\"ש כי חלק ה'<sup data-n=\"93\">93</sup> כו' וכתי' חלקי ה' אמרה נפשי<sup data-n=\"94\">94</sup>, אבל שרש נה\"ב הוא רק מבחי' פני שור<sup data-n=\"95\">95</sup> שמהשמאל<sup data-n=\"96\">96</sup> ואפי' נפש השכלית של האדם הוא ג\"כ רק מבחי' פני אדם<sup data-n=\"97\">97</sup> שבמרכבה, ושרש המרכבה הוא רק מבחי' דבור ד' רבתי דאחד כנ\"ל שמזה נראה העולם ליש ודבר נפרד וע\"כ נה\"ב טבעה בהיפוך מנה\"א לימשך אחר תאוות עוה\"ז גשמי' וא\"כ המלחמה גדולה ביניהם שנה\"א טבעה ורצונה לאהבת הוי' וליכלל למעלה ונה\"ב רצונה בהיפך מזה לימשך אחר תאוות הגוף ורצונות זרים, וא\"כ ע\"י מה יוכל לנצח את המלחמה, זהו ע\"י רמ\"ח תיבין שבק\"ש<sup data-n=\"90\">90</sup> כי ע\"י ק\"ש נמשך קומה ש\"מ דהיינו בחי' ועל הכסא דמות<sup data-n=\"98\">98</sup> כמראה אדם עליו מלמעלה אדם אדמה לעליון<sup data-n=\"99\">99</sup> ועי\"ז ממילא נופל הקומה שלעו\"ז כי אור דוחה חשך, וזהו מ\"ש רוממות אל בגרונם<sup data-n=\"100\">100</sup> וחרב פפיות בידם, דהיינו שע\"י רוממות אל כו' עי\"ז נעשה חרב פפיות בידם לעשות נקמה בגוים, הוא בירור נה\"ב כמשי\"ת<sup data-n=\"101\">101</sup>, וזהו שנק' ק\"ש רמח בידו ועי\"ז נעשה בכל לבבך בשני יצריך<sup data-n=\"102\">102</sup> דהיינו ביצ\"ט וביצה\"ר, שגם נה\"ב תרצה ליכלל בקדושה כו', וזהו",[["88","88","<b>ויקח רמח בידו</b>: בלק כה, ז."],["89","89","<b>ופי' בזוה\"ק . . רמ\"ח תיבין שבק\"ש</b>: ראה זהר עקב רבע, א. לקו\"ת תצא לח, א ובהנסמן במ\"מ לשם. מאמרי אדה\"א ויקרא ח\"א ע' צא. וש\"נ. הערה בסה\"מ תש\"ד ס\"ע 83־ תרל\"ב ח\"א ע' נז."],["91","91","<b>בחרבי ובקשתי ות\"א בצלותי ובעותי</b>: ויחי מח, כב [ושם: בצלותי ובבעותי. וכ\"ה בסה\"מ תרל\"א ותרל\"ג כאן ע' קלט].\nבסה\"מ תש\"ד שם: בצלותא ובעותא [וכ\"ה לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן על יד הערה 80]. וכאן ע' 160 כבתרגום. ראה סה\"מ תר\"ם ח\"א ע' קנג. וש\"נ."],["92","92","<b>חלק אלקה ממעל</b>: איוב לא, ב. ראה גם לקמן מאמר ד\"ה וידעת היום הערה 34."],["93","93","<b>כי חלק ה'</b>: האזינו לב, ט."],["94","94","<b>חלקי ה' אמרה נפשי</b>: איכה ג, כד."],["95","95","<b>שרש נה\"ב . . פני שור</b>: ראה סידור שער האלול רל, א. ש\"א יז, א הערה 11. סה\"מ תר\"ם ח\"ב ע' תקפ. וש\"נ."],["96","96","<b>פני שור שמהשמאל</b>: ראה יחזקאל א, י."],["97","97","<b>נפש השכלית . . פני אדם</b>: וכ\"ה בסה\"מ תרל\"ג (כאן ע' קלט)־ תרס\"ה (כאן ע' קלה)־ תש\"ד (כאן ע' 160). לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן על יד הערה 82. ראה גם מאמרי אדה\"א דברים ח\"ד ע' א'רז. תו\"ח ח\"ש קל, ב.\nראה גם בענין נפש השכלית זהר (רע\"מ) צו כט, ב. לקו\"ת בחוקותי מז, ג. מאמרי אדה\"ז תקס\"ו ע' כה. אתהלך לאזניא ע' ריב. תו\"ח בא ח\"א קלב, ג. וש\"נ. קא, ג. וש\"נ. שמות מז, ב. וש\"נ. קיצורים והערות לתניא ס\"ע עה. סה\"מ תרנ\"ט ע' קו. סה\"ש תו\"ש ע' 142. סה\"מ קונטרסים ע' 160-158. ת\"ש ס\"ע 95-92. ס\"ע 98-95. תש\"ח ע' 85. פלח הרמון בחוקותי ע' תכט. וש\"נ."],["90","90","<b>רמ\"ח תיבין שבק\"ש</b>: ראה תנחומא קדושים ו. שערי זהר לשם קסד, ד."],["98","98","<b>ועל הכסא דמות</b>: יחזקאל א, כו [בדילוג]."],["99","99","<b>אדם אדמה לעליון</b>: ישעי' יד, יד. ראה עבוה\"ק ח\"א חלק היחוד פי\"ז. של\"ה תולדות אדם ג, א. מאמרי אדה\"א דברים ח\"א ע' קכב. וש\"נ. בראשית ע' קסב. וש\"נ."],["100","100","<b>רוממות אל בגרונם</b>: תהלים קמט, ו."],["101","101","<b>לעשות נקמה . . בירור נה\"ב כמשי\"ת</b>: תהלים שם, ז. ראה גם לקו\"ת תצא לה, ד. סה\"מ תר\"ם ח\"א ע' קנג. ע' שנט ואילך."],["102","102","<b>בכל לבבך בשני יצריך</b>: ואתחנן ו, ה ובספרי שם. ברכות נד, א במשנה. ראה גם סה\"מ תר\"ם ח\"א ע' לב. וש\"נ."]]],[2001910081,"עיקר ענין בירורה כו', והנה כאשר נה\"ב נתהפך לקדושה עי\"ז נעשה יתרון האור מן החשך<sup data-n=\"103\">103</sup> דכד אתכפי' סט\"א<sup data-n=\"104\">104</sup> אסתלק יקרא דקוב\"ה לפי שכך עלה ברצונו, ועי\"ז נעשה עלי' יותר גדולה מכמו שהיתה קודם ירידתה כו' לפי שקודם ירידתה היתה רק בבחי' עלה במח', והנה מח' הוא רק בחי' לבוש רק שהוא לבוש פנימי', ודבור הוא לבוש חיצוני'<sup data-n=\"105\">105</sup>, אבל מ\"מ הוא רק בחי' לבוש, אבל ע\"י ירידתה בגוף ונה\"ב ונתהפך החשך לאור עי\"ז יגיע<sup data-n=\"106\">106</sup> לבחי' לאשתאבא בגופא דמלכא<sup data-n=\"107\">107</sup> ממש שלמעלה מבחי' מח' שהוא רק לבוש לעצם הנפש, והגם שנת\"ל שבחי' עלו במחשבה הוא בחי' מח' ויובלא, עכ\"ז פי' לאשתאבא בגופא דמלכא זהו עלי' גדולה וכמ\"ש מזה במ\"א בענין בי נשבעתי, שפירשו היינו במה שמלובש בי<sup data-n=\"108\">108</sup> דהיינו בחי' האור, כענין בית יעקב כו' באור הוי'<sup data-n=\"109\">109</sup> שפירושו בבחי' האור שמאיר בש' הוי' כו', וזהו העלי' מבחי' גרמוהי לבחי' חיוהי<sup data-n=\"110\">110</sup> שנת' במ\"א בכמה דוכתי, שהוא עלי' נפלאה לאין קץ, וזהו מ\"ש עתידי' צדיקים שיאמרו לפניהם קדוש<sup data-n=\"111\">111</sup> כדרך כו' דהיינו שיתעלו לבחי' קדש העצמי' שלמעלה מבחי' קדוש<sup data-n=\"112\">112</sup> בוא\"ו וע\"כ יאמרו לפניהם קדוש. ואח\"כ אומרים בק\"ש והיו הדברים האלה וארז\"ל בד\"ת<sup data-n=\"113\">113</sup> הכתוב מדבר, זהו מפני שעיקר הכלי לבחי' המשכה זו הוא בחי' תורה כי אורייתא מח\"ע נפקת<sup data-n=\"114\">114</sup> שהוא ראש ומוח, והנה",[["103","103","<b>יתרון האור מן החשך</b>: ע\"פ קהלת ב, יג."],["104","104","<b>דכד אתכפי' סט\"א</b>: ראה זהר תרומה קכח, ב. יתרו סז, ב. הנסמן במאמרי אדה\"א שמות ח\"א ע' ה. אוה\"ת שלח כרך ו ע' א'תשעב. וש\"נ. שה\"ש כרך ב ע' תרצט."],["105","105","<b>מח' . . לבוש פנימי' . . חיצוני'</b>: ראה לקו\"ת בהר מא, א. ש\"ש סה, ד. מאמרי אדה\"ז תקס\"ה ח\"ב ע' תתקטז. אתהלך לאזניא ע' ריז. סה\"מ תרמ\"ו ע' תד ואילך. לקמן מאמר ד\"ה כי תבואו וכו' ושבתה הארץ רפ\"ד."],["106","106","<b>עי\"ז יגיע</b>: ראה סה\"מ תש\"ד כאן ע' 161 בהערה."],["107","107","<b>לאשתאבא בגופא דמלכא</b>: זהר ויחי ריז, ב. ראה גם סה\"מ תר\"ם ח\"א ע' צז. וש\"נ."],["108","108","<b>בי נשבעתי . . שמלובש בי</b>: וירא כב, טז. ראה זהר אד\"ר נשא קל, א ובקול ברמה שם. סה\"מ תרל\"ו ח\"ב ע' רצט. המשך תער\"ב ח\"ב ע' תתקצג. ח\"ג ע' א'תלה. אוה\"ת שבהערה הבאה."],["109","109","<b>בית . . באור הוי'</b>: ישעי' ב, ה. ראה זהר שם. תו\"א שמות נ, ג. אוה\"ת ישעי' כרך א' ע' קא. לקמן מאמר ד\"ה ומעתה צ\"ל מפני מה כל הנשמה ספ\"ד. סה\"מ תרכ\"ז ע' שכו. תרל\"ג ח\"ב ע' שסד. ע' שסח. תרל\"ט ח\"ב ע' תנז. דרושים שבהערה שלפנ\"ז."],["110","110","<b>העלי' מבחי' גרמוהי לבחי' חיוהי</b>: ראה תו\"א יתרו עא, א. עב, ב. לקו\"ת בלק ע, ב. פ' ראה כז, א ואילך. יוה\"כ ע, ג. סה\"מ תר\"ם ח\"ב ע' תקה ואילך. וראה גם לקמן מאמר ד\"ה וידעת היום על יד הערה 116 ואילך."],["111","111","<b>עתידי' צדיקים שיאמרו לפניהם קדוש</b>: ראה ב\"ב עה, ב. לקו\"ת בהעלותך־ נצבים־ יו\"כ שבהערה הבאה."],["112","112","<b>קדש . . שלמעלה מבחי' קדוש</b>: ראה זהר אמור צג, א. לקו\"ת בהעלותך ל, סע\"ג ואילך. נצבים נ, ב ואילך. יו\"כ סט, ב ואילך. שה\"ש כא, ב ואילך. לו, ד. אוה\"ת תזריע כרך ד ע' א'נג."],["113","113","<b>והיו הדברים האלה וארז\"ל בד\"ת</b>: ואתחנן ו, ו. וכ\"ה בכ\"מ ראה לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן ובהערה 91.\nראה זהר ואתחנן רסח, א. חינוך מצוה תיח. פני יהושע קדושין ל, א (ד\"ה רב ספרא). רבינו מיוחס ואתחנן שם. גור ארי' יתרו כ, א (ד\"ה ומה ת\"ל קרוב לסופו). ראשית חכמה שער האהבה פ\"ח (ד\"ה הרי מבואר). תניא פמ\"ט (ע' ע). אגה\"ת פ\"י (ע' צט). תו\"ח ויחי רמא, ד. לקו\"ש ואתחנן כרך לד ע' 32 ואילך ובהנסמן שם. וראה גם בפי' הספרי הקדמה לשער היחוד והאמונה עו, א. לקו\"ת חוקת סג, א. אוה\"ת בראשית כרך ג ע' תעג."],["114","114","<b>אורייתא מח\"ע נפקת</b>: זהר בשלח סב, א. יתרו פה, א. רע\"מ משפטים קכא, א. קדושים פא, א. חוקת קפב, א. ואתחנן רסא, א."]]],[2001910082,"אנו רואים למטה שעיקר גילוי כללות החיות של הנפש הוא במוח<sup data-n=\"115\">115</sup>, ואח\"כ מתפשט ממנה לכל האברים, ולכך יש גידים הנמשכים ממוח לכל האברים ואפי' ברגל<sup data-n=\"116\">116</sup> נמצאים גידי המוח, ועד\"ז יובן ג\"כ למעלה שראשית גילוי ההמשכה תחלה מתלבש בתורה שהוא ראשית בחי' ראש ומוח ששם שורה אוא\"ס לפי שהוא בחי' כח מ\"ה בחי' ביטול, ולכך ת\"ת כנגד כולם<sup data-n=\"117\">117</sup> וזהו מלמעלה למטה, אך הנה ארז\"ל כל האומר אין לי אלא תורה<sup data-n=\"118\">118</sup> אפי' תו' אין לו מפני שצ\"ל העלאה תחלה שז\"ע תפלה שבכלל גמ\"ח יחשב כמו שפרש\"י בשבת פ' מפנין<sup data-n=\"119\">119</sup> שעיון תפלה בכלל גמ\"ח כמ\"ש גומל נפשו איש חסד<sup data-n=\"120\">120</sup>, ולכן קודם התורה צ\"ל מקודם התפלה<sup data-n=\"121\">121</sup> דהיינו מפני כי לעורר ההמשכה הוא ע\"י התפלה שהיא ממטה למעלה וכמ\"ש סולם מוצב ארצה<sup data-n=\"122\">122</sup> וראשו מגיע השמימה לפי שהוא בחי' הרצוא לאלקות, דא\"א להיות המשכה מלמעלמ\"ט כ\"א שיהי' מקודם העלאה מלמטלמ\"ע וכמ\"ש אם ישים אליו לבו<sup data-n=\"123\">123</sup> רוחו ונשמתו אליו יאסוף, ולכך כתי' בק\"ש וזאת המצוה דהיינו שהוא כללות כל המצות והוא לפי שעיקר הרצוא שעי\"ז יהי' אח\"כ המשכה, ולכן אסור לאכול קודם התפלה<sup data-n=\"124\">124</sup> לפי שעדיין לא נמשכה המשכה אפי' במוח ונק' אז האדם רק בשם דם, כמ\"ש לא תאכלו על הדם<sup data-n=\"125\">125</sup> ופי' רז\"ל קודם שתתפללו על דמכם, אך אחר התפלה נק' בחי' אדם, שממשיך בחי' אלף אלופו ש\"ע בבחי' דם כו', ואז אדם בגימ' מ\"ה<sup data-n=\"126\">126</sup> כו', והיינו ע\"י שממשיך בחי' קומה ש\"מ שהוא בחי' ועל הכסא דמות כמראה אדם, וז\"ע פ' ראשונה של ק\"ש.",[["115","115","<b>שעיקר גילוי כללות החיות . . במוח</b>: ראה תניא פנ\"א."],["116","116","<b>גידים הנמשכים ממוח . . ברגל</b>: ראה גם לקו\"ת במדבר יז, א. מאמרי אדה\"ז תקס\"ג ח\"א ע' רפא ואילך. ע' רפח. תקס\"ה ח\"ב ע' תשי. תקס\"ט ע' רכד. תו\"ח ח\"ש קכב, ג ובהנסמן במ\"מ לשם."],["117","117","<b>ת\"ת כנגד כולם</b>: פאה פ\"א, מ\"א. ראה מאמרי אדה\"א שמות ח\"ב ע' תקעא. תו\"ח תצוה ח\"ב שלו, א. ראה גם לקמן מאמר ד\"ה א\"ר אלעזר א\"ר חנינא ת\"ח מרבים שלום ספ\"ב."],["118","118","<b>כל האומר אין לי אלא תורה</b>: ראה יבמות קט, ב. לקמן מאמר ד\"ה והנה תורה היא בחי' קו האמצעי ובהערה 191. ד\"ה ומעתה צ\"ל מפני מה כל הנשמה פ\"ו (רד\"ה אבל). סה\"מ תר\"ם ח\"ב ע' תפד ואילך. תש\"ח ע' 266 בהערה."],["119","119","<b>שפרש\"י בשבת פ' מפנין</b>: קכז, ריש ע\"ב ד\"ה ה\"ג."],["120","120","<b>גומל נפשו איש חסד</b>: משלי יא, יז. ראה גם סה\"מ תרל\"ח ע' מב ואילך ובהנסמן שם."],["121","121","<b>התורה צ\"ל מקודם התפלה</b>: ראה לקו\"ת ואתחנן ד, א. ברכה צו, ב. סה\"מ תרכ\"ז ע' רפח בשולי הגליון."],["122","122","<b>התפלה . . סולם מוצב ארצה</b>: ויצא כח, יב. ראה זח\"א בהשמטות רסו, ב. ח\"ג תוספת שו, ב. ת\"ז תמ\"ה פג, א. סה\"מ תרל\"ח ע' מה. וש\"נ. תש\"ח ע' 80."],["123","123","<b>אם ישים אליו לבו</b>: איוב לד, יד."],["124","124","<b>אסור לאכול קודם התפלה</b>: ברכות י, ב. ראה גם לקו\"ת צו ח, א. בלק עב, א. מאמרי אדה\"א ויקרא ח\"ב ע' תשנו. וש\"נ. שמות ח\"א ס\"ע קפב ואילך. וש\"נ. סה\"מ תרל\"ח ע' ריב. לקמן מאמר ד\"ה כי תבואו וכו' ושבתה הארץ פ\"א."],["125","125","<b>לא תאכלו על הדם</b>: קדושים יט, כו. ברכות י, ב. ראה לקו\"ת פינחס עט, ד. מאמרי אדה\"א הנחות תקע\"ז ע' קל. וש\"נ. סה\"מ תרכ\"ז ע' רפח. לקמן שם."],["126","126","<b>אדם בגימ' מ\"ה</b>: ראה ע\"ח שער התיקון ש\"י, פ\"ג. לקו\"ת ושער הפסוקים להאריז\"ל בראשית ג, כ. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תקסז ובהנסמן במ\"מ לשם. תו\"ח בראשית ט, א הערה 14."]]],[2001910083,"ד) <b>ומעתה</b> י\"ל מ\"ש בפ' שני' דק\"ש ואספת דגנך<sup data-n=\"127\">127</sup> כו', שלכאו' קשה מאי איכפת לי' אם יאסוף או לאו הלא אומר אח\"כ ואכלת ושבעת<sup data-n=\"128\">128</sup>, אך הענין הוא דהנה ארז\"ל עשה תורתך קבע<sup data-n=\"129\">129</sup> ומלאכתך עראי, והנה בבחי' קבע ועראי<sup data-n=\"130\">130</sup> אין הפי' דוקא בבחי' ריבוי ומיעוט דא\"כ למה לא אמר למוד הרבה אלא הפי' בעיקר הרצון, שעיקר כוונתו ורצונו יהי'<sup data-n=\"131\">131</sup> רק ללמוד תורה, דהיינו שאפי' אם עוסק במו\"מ יהי' המכוון מזה כדי שישתכר ויהי' לו פרנסה לפרנס א\"ע וב\"ב ועי\"ז יוכל ללמוד תורה וגם בכלל צדקה יחשב כמשרז\"ל ע\"פ עושה צדקות בכ\"ע<sup data-n=\"132\">132</sup> זה הזן<sup data-n=\"133\">133</sup> כו' וכן כה\"ג בכל מה שעושה, וזהו ואספת דגנך דהיינו שיאסוף הכל לבחי' אחד דהיינו לבחי' ביטול מעלמא דפרודא<sup data-n=\"134\">134</sup> לעלמא דיחודא. והנה אח\"כ מזכירין יצ\"מ, וצ\"ל מה שייכות ענין יצ\"מ לק\"ש, אך הענין הוא דהיינו שאל יאמר האדם איך יגיע לזה המדריגה הגדולה לנצח את המלחמה הנ\"ל עם היצה\"ר לכובשו שגם הוא יבא לבחי' ואהבת כו', כי ידע אינש בנפשו איך שהוא מלא עוונות, ועוונותיכם מבדילין<sup data-n=\"135\">135</sup> כו' כתיב, ומאן דנפח צריך שלא יפסיק<sup data-n=\"136\">136</sup> שום דבר כדי שיעלה הנפיחה, לא כן אני כי עוונותיכם מבדילין כו', ולכך מזכירין יצ\"מ דהיינו כי כמו שבמצרים היו ישראל מושקעים במ\"ט שע\"ט<sup data-n=\"137\">137</sup> ומ\"מ אחר יצ\"מ במשך נ' ימים קבלו את התורה<sup data-n=\"138\">138</sup> שהי' גילוי אלקות פב\"פ<sup data-n=\"139\">139</sup> כו', והיינו לפי שהי' אתעדל\"ע מעצמו<sup data-n=\"140\">140</sup> בלי שום אתעדל\"ת<sup data-n=\"141\">141</sup> כלל וכמ\"ש אני הוי' אלקיכם<sup data-n=\"142\">142</sup> אשר הוצאתי אתכם מאמ\"צ וכמשארז\"ל עד שנגלה עליהם ממה\"מ<sup data-n=\"143\">143</sup> הקב\"ה וגאלם, וזהו מ\"ש אנכי הוי' אלקיך<sup data-n=\"144\">144</sup> אשר הוצאתיך שע\"י יצ\"מ הי' התגלות בחי' אנכי מי שאנכי<sup data-n=\"145\">145</sup> כו', וכך גם עתה ע\"י תשובה גמורה יכול",[["127","127","<b>ואספת דגגך</b>: עקב יא, יד. ראה גם אוה\"ת בראשית כאן ע' 2044. סה\"מ תרל\"א ח\"א ע' ה. ותרל\"ג כאן ע' קלז. תרס\"ה כאן ע' קלג. תש\"ד כאן ע' 155. לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן על יד הערה 109."],["128","128","<b>ואכלת ושבעת</b>: עקב שם, טו."],["129","129","<b>עשה תורתך קבע</b>: רמב\"ם הל' ת\"ת פ\"ג, ה\"ז. ראה אבות פ\"א, מט\"ו. ברכות לה, ב. שו\"ע אדה\"ז הל' מו\"מ סקנ\"ו, ס\"א. הל' ת\"ת פ\"ג, ה\"ב ואילך."],["130","130","<b>קבע ועראי</b>: ראה לעיל הערה 127. סה\"מ תרכ\"ו ס\"ע קסח ואילך. ע' קעא. תרל\"ט ח\"ב ע' תסו. וש\"נ. וראה ג\"כ שע\"ת קכח, ג."],["131","131","<b>שעיקר כוונתו ורצונו יהי'</b>: ראה שו\"ע אדה\"ז חאו\"ח הל' מו\"מ סקנ\"ו, ס\"ב. וש\"נ."],["132","132","<b>עושה צדקות בכ\"ע</b>: תהלים קו, ג [ושם: צדקה — ראה גם סה\"מ תר\"ם ח\"ב ע' תשע]."],["133","133","<b>זה הזן</b>: כתובות נ, סע\"א."],["134","134","<b>מעלמא דפרודא</b>: ראה זהר בראשית כב, א."],["135","135","<b>ועוונותיכם מבדילין</b>: [וכ\"ה ב(תו\"א תצוה פג, א) סה\"מ תרל\"א ותרל\"ג כאן ס\"ע קלז. בסה\"מ תרס\"ה ע' קלד מבדילים] ישעי' נט, ב [בדילוג]. ראה גם לקמן מאמר ד\"ה והי' אור הלבנה פ\"ב."],["136","136","<b>ומאן דנפח . . יפסיק</b>: לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן (על יד הערה 117) בשם הזהר. באוה\"ת כאן ע' תתרכג מציין לאגה\"ת פ\"ה."],["137","137","<b>שבמצרים . . מושקעים במ\"ט שע\"ט</b>: ראה ז\"ח יתרו לא, א. סה\"מ תר\"ם ח\"א ע' קמב. וש\"נ."],["138","138","<b>במשך נ' ימים . . התורה</b>: ראה שו\"ע אדה\"ז חאו\"ח סדר תפלת חה\"ש סתצ\"ד, ס\"א. סה\"מ תר\"ם ח\"א ע' רז. וש\"נ."],["139","139","<b>גילוי אלקות פב\"פ</b>: ואתחנן ה, ד."],["140","140","<b>שהי' אתעדל\"ע מעצמו</b>: ראה לקו\"ת ויקרא ג, א. שה\"ש כד, ג."],["141","141","<b>אתעדל\"ע . . אתעדל\"ת</b>: נסמן לקמן במאמר ד\"ה להבין וכו' בענין הציץ הערה 215."],["142","142","<b>אני הוי' אלקיכם</b>: שלח טו, מא."],["143","143","<b>עד שנגלה עליהם ממה\"מ</b>: נוסח ההגדה."],["144","144","<b>אנכי הוי' אלקיך</b>: יתרו כ, ב."],["145","145","<b>אנכי מי שאנכי</b>: ראה תניא מהדו\"ק ספמ\"ט. לקו\"ת להאריז\"ל תולדות כז, יט בשם הזהר. אבן עזרא תולדות שם. מאמרי אדה\"ז תקס\"ב ח\"א ע' יד. פרשיות התורה ח\"א ע' רט ובהנסמן במ\"מ לשם."]]],[2001910084,"להיות יצ\"מ לצאת מהמצרים וגבולים כו', כי גם עתה יש יצ\"מ<sup data-n=\"146\">146</sup>, הגם שזה הי' זמן כביר אך התורה היא למעלה מהזמן ומקום<sup data-n=\"147\">147</sup> כמ\"ש מזה במ\"א, שלכן נק' אדם כו', ולכן חייב אדם לראות א\"ע כאלו הוא עצמו יצא ממצרים<sup data-n=\"148\">148</sup> כו', אך זהו ע\"י תשובה דוקא, וחז\"ל תקנו להקדים שתים לפני'<sup data-n=\"149\">149</sup> יוצר אור ואהבת עולם, והוא לפי שבימי משה הי' דור דיעה<sup data-n=\"151\">151</sup> ע\"כ מיד שהיו מתבונני' בפ' שמע ישראל מיד הי' נתעורר אוי\"ר כו' לפי שהיו נשמות גבוהות ולא היו צריכין להעמקת הדעת והרחב הביאור<sup data-n=\"150\">150</sup>, אבל עתה שנתמעטו הלבבות וראו שאין די בק\"ש לבד לפי שהוא בקיצור גדול, לזה תקנו שתים לפניה, ודרך כלל הוא בחי' ביאור פסוק שמע ישראל כי ברכת יוצר אור הוא ביאור על תיבות הוי' אחד<sup data-n=\"152\">152</sup>, דהיינו על עלמא דאתגלי'<sup data-n=\"153\">153</sup>, איך שהוא מחי' את כולם והאופנים כו' ברעש גדול כו', ואיך שהמלאכים משבחים באימה ואומרים ביראה, ששרשם מבחי' הדבור<sup data-n=\"154\">154</sup> כמ\"ש וברוח פיו כל צבאם<sup data-n=\"155\">155</sup>, ואח\"כ אהבת עולם הוא ביאור על הוי' אלקינו<sup data-n=\"156\">156</sup> כו', עלמא דאתכסי'<sup data-n=\"157\">157</sup> דהיינו איך שנש\"י אהבתיך בבחי' אהבה עצמי', ובהרחב הזמן שנתמעטו הלבבות יותר וראו שאין די בזה ואינו מספיק להוציא האהבה מהעלם אל הגילוי כו', תיקנו עוד פסוד\"ז<sup data-n=\"158\">158</sup> שהוא ביאור יותר רחב כו', ואחר ק\"ש בא הברכה דאמת ויציב שיש בה ט\"ו ווי\"ן<sup data-n=\"159\">159</sup>, והנה איתא בווין תתקטר<sup data-n=\"160\">160</sup> דהיינו התקשרות והתחברות הוא ע\"י ווין וכמ\"ש עשה ווים לעמודים<sup data-n=\"161\">161</sup> כו' ובחצר המשכן ז\"ע יתדות המשכן<sup data-n=\"162\">162</sup> שהם המחברים את המשכן",[["146","146","<b>גם עתה יש יצ\"מ</b>: ראה גם לקו\"ת אמור לה, ב. שלח מח, ג."],["147","147","<b>התורה היא למעלה מהזמן ומקום</b>: וכ\"ה בסה\"מ תרל\"ג כאן ע' קלח. באוה\"ת כאן ע' תתרכג: הוא ית' למעלה מהזמן. ראה גם לקו\"ת במדבר יג, א."],["148","148","<b>חייב אדם . . יצא ממצרים</b>: ראה פסחים קטז, ב (במשנה). תניא פמ\"ז. הגדה של פסח עם לקוטי טעמים מנהגים וביאורים (קה\"ת תשמ\"ו ואילך) ע' תריח בשולי הגליון."],["149","149","<b>וחז\"ל תקנו . . שתים לפני'</b>: בלקו\"ת תצא לד, ד: אכנה\"ג. ראה ברכות יא, סע\"א (במשנה). שו\"ע אדה\"ז הל' ק\"ש רסנ\"ט."],["151","151","<b>דור דיעה</b>: ראה זהר בשלח סב, ב. פע\"ח שחה\"מ שכ\"א, פ\"א. מאמרי אדה\"א דברים ח\"א ע' עו. וש\"נ."],["150","150","<b>שבימי משה . . והרחב הביאור</b>: ראה לקו\"ת האזינו עז, ד."],["152","152","<b>ברכת יוצר אור . . הוי' אחד</b>: ראה גם אוה\"ת בראשית כאן ע' תתרכג. וסה\"מ כאן — תרל\"א ותרל\"ג ע' קלח. תרס\"ה ס\"ע קלד ואילך. תש\"ד ע' 160."],["153","153","<b>עלמא דאתגלי'</b>: ראה זהר בראשית יח, א. ויצא (ס\"ת) קנב, א. קנח, ריש ע\"ב. וארא כט, ב. ת\"ז בהקדמה א, סע\"א ואילך. תניא פכ\"ו."],["154","154","<b>שהמלאכים . . ששרשם מבחי' הדבור</b>: ראה אגה\"ת פ\"ד. ש\"א ח, ב ובהערה 39."],["155","155","<b>וברוח פיו כל צבאם</b>: תהלים לג, ו."],["156","156","<b>אהבת עולם . . הוי' אלקינו</b>: ראה לעיל הערה 152."],["157","157","<b>עלמא דאתכסי'</b>: ראה לעיל הערה 153."],["158","158","<b>ובהרחב הזמן . . תיקנו עוד פסוד\"ז</b>: ראה שו\"ע אדה\"ז חאו\"ח סנ\"א, ס\"א־ ס\"ב. תו\"ח פקודי ח\"ב ע' תמה [ושם: אנשי כנה\"ג]. וש\"נ. סה\"מ תרל\"ח ע' תנא. וש\"נ. לקו\"ת תבוא מב, ד."],["159","159","<b>דאמת ויציב . . ט\"ו ווי\"ן</b>: ראה פע\"ח שער הק\"ש ש\"ח, פכ\"ח. תו\"ח וישב רי, א הערה 14. לקמן מאמר ד\"ה שלש רגלים תחוג לי על יד הערה 75."],["160","160","<b>בווין תתקטר</b>: בזמירות לליל שבת — אזמר בשבחין."],["161","161","<b>עשה ווים לעמודים</b>: פקודי לח, כח."],["162","162","<b>יתדות המשכן</b>: ויקהל לה, יח. פקודי לח, לא."]]],[2001910085,"לארץ ע' בפרש\"י בחומש<sup data-n=\"163\">163</sup>, והוא בחי' כי כל בשמים ובארץ ות\"א דאחיד<sup data-n=\"164\">164</sup> בשמיא וארעא, ולכך אומרים אמת ויציב ונכון וקיים כו' דהיינו שיתאמת אצלו ויהי' מקושר כל היום לאלקות גם אפי' בעת שעוסק במו\"מ וכה\"ג, וזהו הנק' התקשרות על כל היום, ולכך הם ט\"ו ווין היינו לפי שהוא מספר בחי' י\"ה, ונודע כי בחי' י\"ה הוא בחי' חו\"ב<sup data-n=\"165\">165</sup> הנק' אין ויש<sup data-n=\"166\">166</sup> והם תרין ריעין דל\"מ<sup data-n=\"167\">167</sup>, שלכאו' אינו מובן איך הם תרין ריעין כו' הלא הם שני הפכים כו' אך מצד שהיש בטל בתכלית לכן הם תרדל\"מ, וזהו שאומרים כאן אחר ק\"ש ט\"ו ווין דהיינו להמשיך בחי' י\"ה בו\"ה שהוא מקור עלמא דאתגלי' שהוא עולם הפירוד כדי שיהי' ג\"כ ביטול היש לאין כו' ויהי' השם שלם כו'.\n<b>ועפ\"ז</b> יובן ענין דקדוק ל' אותו דבר כו' עדיין כו' וגם בנו דוקא ג\"כ, דהנה רש\"י ז\"ל בחומש<sup data-n=\"168\">168</sup> פי' הוי' אלקינו ה' אחד מה שעתה הוי' אלקינו יהי' לע\"ל הוי' אחד, והיינו ע\"י שהעלם נתן בלבם בלב האדם כנ\"ל, שזמן ניתן לבחי' עולם עד כמה תהי' בבחי' ההעלם כמובן מרבות ר\"פ מקץ ע\"פ קץ שם לחשך<sup data-n=\"169\">169</sup> דיצה\"ר כו' ע\"ש, וע\"י העבודה יזדכך העולם כמ\"ש בביאור ע\"פ כי עכ\"כ חופה בלק\"ת שה\"ש<sup data-n=\"170\">170</sup> בסופו, ואז מה שעכשיו ה' אלקינו יהי' הוי' אחד כו', וכ\"ז שלא נעקר יצה\"ר מן העולם<sup data-n=\"171\">171</sup> אותו דבר שצויתנו עדיין נוהג בנו לבד כו', וז\"ע ה' אלקינו ה' אחד כו'.",[["163","163","<b>בפרש\"י בחומש</b>: תרומה כז, יט."],["164","164","<b>כי כל . . ות\"א דאחיד</b>: דברי הימים-א כט, יא. כ\"ה גם בת\"ז תי\"ג כט, א. לקו\"ת פ' ראה כג, ד. אוה\"ת פ' ראה כרך ו' ע' ב'שלה. סה\"מ תרכ\"ט ע' שנד. תרל\"א ותרל\"ג כאן ע' קלח. ח\"ב ע' תלב. ע' תפז. תרל\"ד ע' קו. ע' רעו. תרל\"ח ע' תנו. תרס\"ה כאן ע' קלה.\nראה גם לקמן מאמר ד\"ה ועבדתם את ה\"א ובהערה 86. ד\"ה והנה תורה היא בחי' קו האמצעי על יד הערה 238."],["165","165","<b>י\"ה . . חו\"ב</b>: ראה זהר אד\"ז האזינו רצ, ב. אגה\"ת פ\"ד. מאמרי אדה\"א דברים ח\"ב ע' שסו וע' תרנו."],["166","166","<b>חו\"ב הנק' אין ויש</b>: ראה הנסמן בביאוה\"ז להצ\"צ כרך ב ע' תתרא. מאמרי אדה\"א בראשית ע' ב. דרושי חתונה ח\"ב ע' תעג. סה\"מ תרכ\"ט ע' רעח."],["167","167","<b>חו\"ב . . תרין ריעין דל\"מ</b>: ראה זהר בשלח נו, א. ויקרא ד, א. מאמרי אדה\"א דברים ח\"ב ע' שסו. וש\"נ. תו\"ח בראשית כא, ב ובהערה 8."],["168","168","<b>רש\"י ז\"ל בחומש</b>: ראה ואתחנן ו, ד."],["169","169","<b>קץ שם לחשך</b>: איוב כח, ג."],["170","170","<b>בביאור . . בלק\"ת שה\"ש</b>: מח, א ואילך."],["171","171","<b>נעקר יצה\"ר מן העולם</b>: לשון ב\"ר ר\"פ מקץ."]]],[2001910086,"<h3>קדש ישראל לה'</h3>\n<b>שפשמ\"א</b>\n<b>קדש</b> ישראל לה'<sup data-n=\"172\">1</sup> ראשית תבואתה<sup data-n=\"173\">2</sup>, הנה תבואתה כתי' בה' לבסוף, ונקוד הוא בחולם, שידוע שנקודת החולם הוא כאלו הי' כתוב בוא\"ו לבסוף, וצ\"ל לאיזהו צורך נכתב בה\"א לבסוף ונקוד חולם כו', וגם מהו שייך שעי\"ז נעשי' ישראל קדש כו', הנה כתיב (ישעי' מ\"ג א') כה אמר כו' בוראך יעקב ויוצרך ישראל, ואיתא בילקוט במקומו<sup data-n=\"174\">3</sup>, וכ\"ה ברבות פ' בחוקתי פל\"ו<sup data-n=\"175\">4</sup> ע\"פ וזכרתי את בריתי יעקוב<sup data-n=\"176\">5</sup>, אמר הקב\"ה לעולמו עולמי עולמי מי בראך כו' יעקב בראך וישראל יוצרך, דכתי' בראך יעקב ויוצרך ישראל, ולכאו' אינו מובן איך שייך לומר שיעקב ברא את העולם, אך הענין הוא ע\"ד שנא' סוף דבר הכל נשמע את האלקי' ירא כו' כי זה כל האדם<sup data-n=\"177\">6</sup>, והיינו שתכלית ברה\"ע הי' בשביל שיהי' גילוי בחי' זה, כי זה מורה על בחי' גילוי אלקו' בעולמות, וכמ\"ש בקרי\"ס זה אלי, והיינו לפי שבקרי\"ס הי' גילוי אלקות וכמשארז\"ל ע' בפרש\"י<sup data-n=\"178\">7</sup> בחומש במקומו, ראתה שפחה על הים<sup data-n=\"179\">8</sup> מה שלא ראה יחזקאל<sup data-n=\"180\">9</sup> לכך נאמר שם לשון זה, וכן לע\"ל כתי' ואמר ביום ההוא הנה אלקינו זה,",[["172","1","<b>קדש ישראל לה'</b>: המאמר הוא חלק מד\"ה הבאים ישרש יעקב שבבוך בש\"ו 1063 קפא, ב בשינוי ההתחלה ובהשמטות והוספות. ונדפס גם בסה\"מ תרנ\"ד ע' קיז ואילך פרט להסיום (ד\"ה וזהו). ובשינויים והוספות וכו' בסה\"מ תרס\"ג ח\"ב ע' קח ואילך. עזר\"ת ע' קכג ואילך.\nהנחת כ\"ק אדמו\"ר מהורש\"ב מדרוש זה נדפסה לקמן בחלק הנחותיו [ושם: שהמאמר נא' לעת ערב].\nהכותרת שבריש המאמר נרשמה בגוכתי\"ק ב\"פ: בבוך 1108: ”בס\"ד שפשמ\"א\". בבוך זה 1130: ”שפשמ\"א\" שבת פ' שמות תרמ\"א.\nלמאמר זה צויין בסה\"מ תרמ\"ד ע' רכב [ראה לקמן ספ\"ב על יד הערה 92]. ובמהדורת תשמ\"ט ואילך גם בע' חצר.\nדרוש זה נרשם ד\"פ א) בבוך בש\"ו כת\"י מעתיק עם הגהות ותיקונים מכ\"ק אדמו\"ר מהר\"ש. ב) בבוך 1108 בגוכתי\"ק (ובצד השמאלי של העמוד נרשם: לד\"ה הבאים בס' בש\"ו קפא' ב'. ובכותרת: בס\"ד שפשמ\"א). והוא הגהות וכו' לבוך בש\"ו. ג) בבוך 1108 בכת\"י מעתיק העתק א' וב' הנ\"ל בתוספת הגהות וכו'. ד) בבוך זה 1130 כת\"י מעתיק העתק ג' הנ\"ל. כנראה שהי' עוד הוראות בהנוגע להעתקת המאמר שלע\"ע לא הגיע לידינו.\nבוך בש\"ו הנ\"ל הוא הנחות של ר' דוב [בעריל] קאליסקער ממאמרי כ\"ק אדמו\"ר הצ\"צ ונק' בשם ”בוך בש\"ו\" [בראשית שמות ויקרא]־ ולפעמים נק' בשם ”ס' וכל שיח\" ע\"ש פתיחתו במאמר ד\"ה וכל שיח השדה. ראה עוד ע\"ד הנ\"ל ב”ספריית ליובאוויטש\" ע' ל ואילך. ע' לז ואילך. מאמרי אדמו\"ר הצ\"צ הנחות תרי\"ד-תרט\"ו ע' שו-שז."],["173","2","<b>קדש ישראל לה' ראשית תבואתה</b>: ירמי' ב, ג. ראה גם תנחומא — באבער — בראשית י ובהערה נה. אוה\"ת פינחס ע' א'ריב. סה\"מ תר\"ל ע' קלב וע' רה. תרל\"א ח\"א ע' קעט. לקמן מאמר ד\"ה ומעתה צ\"ל למה הוקבעו המועדים בתחילתו (ובשני הנחות שם).\nבסה\"מ תרל\"א שם בהערה ד\"ה ולהבין זה כותב שהמאמר באוה\"ת פינחס ע' א'ריב הנ\"ל — נדפס שם בשגגה, והוא משנת תר\"ל."],["174","3","<b>ואיתא בילקוט במקומו</b>: ישעי' רמז תנג — בדפוסים שלפנינו לא נסמן הרמז."],["175","4","<b>ברבות פ' בחוקתי פל\"ו</b>: סימן ד [ושם בשינויים קלים]."],["176","5","<b>וזכרתי את בריתי יעקוב</b>: בחוקותי כו, מב."],["177","6","<b>סוף דבר . . את האלקי' . . זה כל האדם</b>: קהלת יב, יג. ראה לקמן פ\"ה."],["178","7","<b>זה אלי . . בפרש\"י</b>: בשלח טו, ב."],["179","8","<b>ראתה שפחה על הים</b>: מכילתא בשלח טו, ב. ראה מאמרי אדה\"א ויקרא ח\"א ע' ריא. וש\"נ. תו\"ח בשלח ח\"א קצד, ב ואילך. סה\"מ תרל\"א ח\"א ע' רסד ואילך."],["180","9","<b>ראה יחזקאל</b>: ברש\"י שם: ראו נביאים. ראה גם (לקמן בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב] בהנחה כאן ובהערה 10."]]],[2001910087,"רק שלע\"ל נא' ב\"פ זה<sup data-n=\"181\">10</sup>, והוא כי אילו לא חטאו בחטא העגל לא נשתברו הלוחות שהי' חרות חירות מיצה\"ר<sup data-n=\"182\">11</sup> שנק' אבן<sup data-n=\"183\">12</sup>, בחי' לב האבן<sup data-n=\"184\">13</sup>, וישראל שעמדו בה\"ס פסקה<sup data-n=\"185\">14</sup> מהם זוהמת הנחש הקדמוני כו', וא\"כ הי' הבירור בא\"א לגמרי שהרי לא היו צריכים ד\"ת שיחקקו לבם בחי' לב האבן<sup data-n=\"186\">15</sup>, כ\"א ע\"ד דכתי' לע\"ל והסירותי<sup data-n=\"187\">16</sup> את לב האבן<sup data-n=\"188\">17</sup> כו', עד<sup data-n=\"189\">18</sup> לע\"ל שאז גם עכשיו<sup data-n=\"190\">19</sup> יהי' עיקר קיום המצות כמ\"ש ושם נעשה לפניך כמצות רצונך, וכמשנ\"ת מזה במ\"א בענין אדם ר\"ת אדה\"ר ד\"מ<sup data-n=\"194\">23</sup>, בד\"ה אוסרי וביאורו<sup data-n=\"191\">20</sup>, ובד\"ה כי עככ\"ח<sup data-n=\"192\">21</sup>, ובשארי דוכתי<sup data-n=\"193\">22</sup>, ומפני שנשתברו הלוחות ובלוחות שניות הגם שבהם יש גם מדרש הלכות ואגדות כנודע מדברי הגמ'<sup data-n=\"195\">24</sup> ומד\"ר<sup data-n=\"196\">25</sup> בזה שהטעם הוא לא מפני שחוטא נשכר כ\"א מפני שלצורך הבירור שיתלבנו ויצטרפו מחהע\"ג<sup data-n=\"197\">26</sup> הוצרך להיות גילוי אור זה ג\"כ, וע\"ד דכתי' וה' יגיה חשכי<sup data-n=\"198\">27</sup> שבכדי להאיר חשך היותר גס ועב עד\"מ במרתף ששם האויר גס מוכרח להיות אור גדול יותר, וכך כדי להגיה החשך שגם החשך יהי' כאור נוגה<sup data-n=\"199\">28</sup> כו' צ\"ל נמשך מבחי' ש' הוי' דלעילא<sup data-n=\"200\">29</sup> כו', ועד\"ז יובן בענין לוחות שניות, שהם כפלים לתושי'<sup data-n=\"201\">30</sup> כו' מפני שבהם יש בחי' תעלומות חכמה<sup data-n=\"202\">31</sup> כו' שהוא לצורך בירור החשך",[["181","10","<b>ואמר. . אלקינו זה . . ב\"פ זה</b>: ישעי' כה , ט. ראה אוה\"ת שמות ע' פה. בשלח ע' תקלא. שבועות ע' קלג ואילך. ישעי' כרך א ע' רג ואילך. (יהל אור) תהלים ע' שסט. סה\"מ תרנ\"ד ע' קנד. סה\"מ מלוקט ד' ע' שנב."],["182","11","<b>חרות חירות מיצה\"ר</b>: תשא לב, טז. ראה גם לקו\"ש פסח כרך יז ע' 453. אג\"ק שלו ח\"ז ע' רד וע' רא."],["183","12","<b>מיצה\"ר שנק' אבן</b>: ראה סוכה נב, א. זהר ואתחנן רסז, ב. אוה\"ת יחזקאל כרך א ס\"ע תיז ואילך. סה\"מ תר\"ם ח\"א ע' רעט."],["184","13","<b>לב האבן</b>: ראה בסמוך הערה 17."],["185","14","<b>וישראל שעמדו בה\"ס פסקה</b>: שבת קמו, רע\"א. ראה סה\"מ תרמ\"ח ע' קצח. תרס\"ח ע' קלא."],["186","15","<b>לא היו צריכים . . האבן</b>: ראה סה\"מ עזר\"ת כאן ע' קכג."],["187","16","<b>לע\"ל והסירותי</b>: ראה גם שע\"ת סג, סע\"ב ובהערה 20. ש\"א פז, א. אוה\"ת שבהערה 12."],["188","17","<b>והסירותי את לב האבן</b>: יחזקאל לו, כו. (יא, יט — כתוב זה הובא בסה\"מ עזר\"ת כאן)."],["189","18","<b>עד</b>: בבוך 1108 ובסה\"מ תרנ\"ד כאן (ע' קיח): ע\"ד."],["190","19","<b>גם עכשיו</b>: תיבות אלו ניתוספו בגוכתי\"ק בבוך 1108 (על העתק כת\"י מעתיק — ראה לעיל הערה 1) וכ\"ה גם בסה\"מ תרנ\"ד כאן."],["194","23","<b>אדם ר\"ת אדה\"ר ד\"מ</b>: ראה רקאנטי בראשית א, כו. ספר הגלגולים פ\"א. פס\"ב בשם ספר הקנה. תו\"ח שמות ח\"א מז, ב הערה 157."],["191","20","<b>ושם נעשה . . בד\"ה אוסרי וביאורו</b>: מוסף ליו\"ט [בדילוג]. תו\"א ויחי מו, ד. תו\"ח ויחי רלז, ג. רלח, ד ואילך."],["192","21","<b>ושם נעשה . . ובד\"ה כי עככ\"ח</b>: ראה גם לקו\"ת שה\"ש מח, א-ב."],["193","22","<b>ושם נעשה לפניך . . ובשארי דוכתי</b>: ראה גם מאמרי אדה\"א שמות ח\"א ע' רכו. וש\"נ. תו\"ח שמות ח\"א כב, ג. וש\"נ. ספר המאמרים תר\"ם ח\"א ע' שג. וש\"נ."],["195","24","<b>ובלוחות שניות . . מדרש הלכות ואגדות . . מדברי הגמ'</b>: ראה נדרים כב, ב.\nראה גם בענין לוחות ראשונות ואחרונות אוה\"ת תשא ס\"ע ב'נו ואילך. סה\"מ תרל\"ב ח\"א ע' פב ואילך. וש\"נ. ע' רמד ואילך."],["196","25","<b>ובלוחות . . מדברי . . ומד\"ר</b>: ראה שמו\"ר פמ\"ו, א. פמ\"ז, ז. לקו\"ש יתרו כרך טז ע' 197 הערה 42."],["197","26","<b>מחהע\"ג</b>: מחטא העגל."],["198","27","<b>וה' יגיה חשכי</b>: שמו\"ב כב, כט. ראה גם סה\"מ עזר\"ת ע' לד."],["199","28","<b>כאור נוגה</b>: משלי ד, יח."],["200","29","<b>ש' הוי' דלעילא</b>: ראה תו\"א בשלח סא, ד ואילך. סה\"מ תרל\"ח ע' נה. וש\"נ."],["201","30","<b>כפלים לתושי'</b>: נסמן בהערה הבאה."],["202","31","<b>תעלומות חכמה</b>: איוב יא, ו. ראה גם תו\"ח שמות ח\"א לג, א. וש\"נ."]]],[2001910088,"כנודע שבחכ' אתברירו<sup data-n=\"203\">32</sup> כו', עד שכולם יבואו לבחי' אתהפכא מחשוכה לנהורא<sup data-n=\"204\">33</sup> כו', ולכן לע\"ל יאמרו ב\"פ זה שמורה על הגילוי כו', מפני עוצם הגילוי שיהי' לע\"ל בכפלים לתושי' כו' נגד בחי' הגילוי שהי' בקרי\"ס שהי' הכנה למ\"ת<sup data-n=\"205\">34</sup> שא' זה אלי כו' פ\"א לבד, ומשה נתנבא בזה<sup data-n=\"206\">35</sup> כו', שמשה הי' הנביא שהוא המשיך בחי' הגילוי דזה כו', וי\"ל כי ענין בחי' זה זהו ע\"ד מ\"ש אשר יאמר עליו כי הוא זה<sup data-n=\"207\">36</sup> פי' שנראה לכל וזהו שמתגלה למטה דוקא ונודע מדרז\"ל במד\"ר שהראשוני' סילקו השכינה<sup data-n=\"208\">37</sup> עד למעלה מז' רקיעים ומשה דור שביעי לאברהם הורידה למטה, א\"כ הי' הוא הממוצע<sup data-n=\"209\">38</sup> שע\"י הי' גילוי בחי' זה כו', ואולי י\"ל ע\"פ מ\"ש במ\"א בענין גו\"ר וגו\"א<sup data-n=\"210\">39</sup> שגם גילוי בחי' ב\"פ זה יהי' ג\"כ ע\"י משה כו', והיינו מפני כי מן המים משיתיהו<sup data-n=\"211\">40</sup> שעש\"ז נק' משה כו', וע' בת\"א בד\"ה מי שם פה לאדם<sup data-n=\"212\">41</sup>, ועיקר תכלית המכוון מברה\"ע הי' בשביל שיהי' גילוי בחי' זה שיהי' גילוי אלקות כו', והנה זה בגימ' י\"ב<sup data-n=\"213\">42</sup> שהוא בחי' י\"ב שבטים, והיינו לפי שי\"ב שבטים הם ממשיכים בחי' זה גילוי אלקות בעולמות שזהו תכלית המכוון כו', והענין הוא שהגם שנת\"ל שמשה נתנבא בזה הכוונה שהוא הי' הממשיך בחי' זה, וכמ\"ש ונתתי עשב בשדך לבהמתך<sup data-n=\"214\">43</sup>,\n\n<i>בבוך 1108 נרשם הבא לקמן בסיום המאמר:</i>\nכפלי' לתושי', תושי' להתיש הנה\"ב, בכפל, וזהו ב\"פ זה, אך בשרשי' משמע שהתורה בעצם נק' תושיה, וגם בזה צ\"ע.\nעה\"ד לוחות שניהם אינם ע\"צ המקרה ח\"ו, כ\"א הידיעה אינה מכרחת כלל כו'.\nוצ\"ע בת\"א ד\"ה בחדש השלישי<sup data-n=\"8163\">*</sup> אם כוונתו על לוחות ראשונות ג\"כ או על לוחות אחרונות שאז הי' לב האבן שצריך תושיה כו'.",[["203","32","<b>שבחכ' אתברירו</b>: ראה אגה\"ק סכ\"ח. זהר היכלות פקודי רנד, סע\"ב. ע\"ח שער דרושי נקודות ש\"ח, פ\"ו. הנסמן במאמרי אדה\"א דברים ח\"א ע' רצה. שמות ח\"ב ע' שכא. תו\"ח תשא ח\"ב שפד, ד ואילך."],["204","33","<b>אתהפכא מחשוכה לנהורא</b>: ראה זהר בהקדמה ד, א. סה\"מ תרל\"ח ע' קנב. וש\"נ."],["205","34","<b>בקרי\"ס שהי' הכנה למ\"ת</b>: ראה שער האמונה לב, ב ובהערה 9. תו\"ח בשלח ח\"א קמח, ג. וש\"נ."],["206","35","<b>ומשה נתנבא בזה</b>: ראה ספרי ר\"פ מטות הובא ברש\"י שם. תו\"ח בשלח ח\"א קמד, ב הערה 29. אוה\"ת מטות ע' א'תצד."],["207","36","<b>אשר יאמר עליו . . זה</b>: משפטים כב, ח [בהוספת תיבת ”עליו\" — וכ\"ה גם בסה\"מ תרנ\"ד כאן (ע' קיח). עזר\"ת כאן ריש ע' קכה. המשך תער\"ב ח\"א ע' קסב. ע' שכז]."],["208","37","<b>שהראשוני' סילקו השכינה</b>: פס\"ר פסיקתא ויהי ביום כלות משה פ\"ה, ז. ב\"ר פי\"ט, ז."],["209","38","<b>ומשה . . הוא הממוצע</b>: ראה גם תו\"ח תצוה ח\"ב שכג, ג. וש\"נ."],["210","39","<b>ומשה . . גו\"ר וגו\"א</b>: ראה שמו\"ר פ\"ב, ד. ו. דב\"ר ספ\"ט. לקו\"ש שמות כרך יא ע' 8. וש\"נ. מטו\"מ כרך כח ע' 213. וש\"נ. מאמרי אדה\"א ויקרא ח\"א ע' שנט. וש\"נ. נ\"ך ע' תרד. וש\"נ."],["211","40","<b>כי מן המים משיתיהו</b>: שמות ב, י."],["212","41","<b>בת\"א בד\"ה מי שם פה לאדם</b>: שמות נא, ד."],["213","42","<b>זה בגימ' י\"ב</b>: ב\"ר פכ\"ד, ה. פס\"ג, ו. שמו\"ר פל\"ח, ח. ויק\"ר פ\"ח, ג."],["214","43","<b>ונתתי עשב בשדך לבהמתך</b>: עקב יא, טו."],["8163","*","בת\"א בד\"ה בחדש השלישי: יתרו סז, ב."]]],[2001910089,"שלכאו' איך אמר ע\"ע ונתתי<sup data-n=\"215\">44</sup>, אלא לפי שמשנה תורה משה מפי עצמו אמרו<sup data-n=\"217\">*46</sup>, וברוה\"ק כמ\"ש בתוספת<sup data-n=\"216\">45</sup>, לכן מפני ששכינה מדברת מתוך גרונו<sup data-n=\"218\">46</sup> הי' יכול לומר ונתתי כו', וענין אומרו עשב בשדך לבהמתך זהו שהי' ממשיך בחי' הדעת גם בנשמות שנק' זרע בהמה כמ\"ש בת\"א בד\"ה ואלה המשפטי'<sup data-n=\"219\">47</sup> ע\"ש, והם הנשמות שמי\"ב שבטים שנק' י\"ב<sup data-n=\"221\">49</sup> בקר<sup data-n=\"220\">48</sup> דבריאה, ומשה ממשיך דעת בהם, וע\"ש מענין עשב ע\"ב שין<sup data-n=\"222\">50</sup>, מ\"מ זהו שהוא הי' הנביא, והי' הממוצע כנ\"ל, אך מ\"מ עיקר ההמשכה הוא בישראל שהם שבטי ישראל שנים עשר כו', ולכן לא די במה שמשה נתנבא בזה כ\"א שצ\"ל שבטי ישראל י\"ב דוקא כמנין זה כו', ועד\"ז יובן ג\"כ הפי' שאמר הקב\"ה לעולם מי בראך יעקב בראך לפי שיעקב וי\"ב שבטים הם ממשיכים בחי' זה גילוי אלקות שלזה הי' עיקר ברה\"ע לזה א' הכתוב בוראך יעקב שיעקב ברא את העולם שאם לא יעקב לא הי' נברא העולם, כי עשרה עשרה הכף<sup data-n=\"223\">51</sup>, שעשה\"ד מכוון נגד ע\"מ<sup data-n=\"224\">52</sup>, ותנאי התנה הקב\"ה כמארז\"ל בשבת<sup data-n=\"225\">53</sup> ובפ\"ק דע\"כ<sup data-n=\"226\">54</sup> ע\"פ יום הששי<sup data-n=\"227\">55</sup>, וכמ\"ש במד\"ר אלה בזכות מי<sup data-n=\"228\">56</sup> כו' ואלה שמות בנ\"י<sup data-n=\"229\">57</sup> כו' אלה העדות<sup data-n=\"230\">58</sup> כו', ואלמלא מעמדות לא נתקיימו<sup data-n=\"231\">59</sup> כו', שנמצא שעיקר קיום הבריאה הוא ע\"י יעקב בכדי\n\n<i>בבוך 1108 (בכת\"י המעתיק) בגוכתי\"ק בהפסק קו נרשם מלמעלמ\"ט בצד הימיני של העמוד:</i>\nוע\"ד שרצה\"ת הוא כלי לבחי' רצה\"ע בת\"א בד\"ה ויקהל[ftnref_8164_א] ע\"ש.",[["215","44","<b>איך אמר ע\"ע ונתתי</b>: ראה לקו\"ת בחוקותי נ, א. סה\"מ תרכ\"ט ע' ריד ואילך."],["217","*46","<b>אמרו</b>: תיבה זו היא הוספה (מהמעתיק) בכת\"י זה."],["216","45","<b>שמשנה תורה . . מפי עצמו . . בתוספת</b>: ראה מגילה לא, ב ותוד\"ה משה. זהר ואתחנן רסא, א (ובמקדש מלך ואור החמה שם). תו\"ח יתרו ח\"ב רסד, א. מאמרי אדה\"א שמות ח\"ב ע' שלא. סה\"מ תרל\"ח ע' שלח ואילך. לקו\"ש דברים כרך יט ע' 9 ואילך. וש\"נ. ר\"ח שבט כרך לו ע' 42. וש\"נ."],["218","46","<b>ששכינה מדברת מתוך גרונו</b>: ראה תניא פל\"ד. הנסמן במאמרי אדה\"ז על פרשיות התורה ח\"א לע' רלא. תו\"ח בראשית לה, ב הערה 26. שע\"ת לט, א ובהערה 6."],["219","47","<b>בת\"א בד\"ה ואלה המשפטי'</b>: עד, ג ואילך."],["221","49","<b>י\"ב בקר</b>: ראה מלכים-א ז, כה. מד. דברי הימים-ב ד, טו."],["220","48","<b>שמי\"ב שבטים שנק' י\"ב בקר</b>: ראה זהר ויחי רמא, א."],["222","50","<b>עשב ע\"ב שין</b>: ראה ת\"ז תכ\"א סב, ב. תנ\"א פו, ב. תו\"א שם עה, ב. אוה\"ת משפטים ע' א'קיד."],["223","51","<b>עשרה עשרה הכף</b>: נשא ז, פו."],["224","52","<b>שעשה\"ד . . ע\"מ</b>: לקמן במאמר ד\"ה וירא ישראל את היד הגדולה רפ\"ב. ועוד: במדרש ובזהר. ראה פסיקתא רבתי פיסקא עשה\"ד פכ\"א, יט. מדרש לקח טוב יתרו כ, ב. זהר יתרו צג, ב. ויקרא יא, ב. לקו\"ת חוקת נז, סע\"ג ואילך בשם המגיד. מאמרי אדה\"א דברים ח\"א ע' רפ. וש\"נ. תו\"ח וארא ח\"א פא, ג ובהערה 636. סה\"מ תרל\"ח ע' ע. וש\"נ. סה\"מ מלוקט ד' ע' פ ואילך."],["225","53","<b>ותנאי התנה . . בשבת</b>: ראה שם פח, א. ראה גם לקמן מאמר ד\"ה א\"ר אלעזר א\"ר חנינא ת\"ח מרבים שלום הערה 27."],["226","54","<b>ובפ\"ק דע\"כ</b>: ג, א. ה, א."],["227","55","<b>יום הששי</b>: בראשית א, לא."],["228","56","<b>אלה בזכות מי</b>: ראה שמו\"ר פמ\"ח, [ב]. סה\"מ תר\"ם ח\"א ע' רנ. וש\"נ."],["229","57","<b>ואלה שמות בנ\"י</b>: שמות א, א."],["230","58","<b>אלה העדות</b>: ואתחנן ד, מה."],["231","59","<b>ואלמלא מעמדות לא נתקיימו</b>: תענית כז, ב.\n\n[ftn_8164_א])בת\"א בד\"ה ויקהל: פז, ד ואילך."]]],[2001910090,"שיושלם המכוון שנתאוה הקב\"ה להיות לו ית'<sup data-n=\"233\">61</sup> דירה בתחתונים<sup data-n=\"232\">60</sup>, וע' מענין אלה תולדות יעקב יוסף<sup data-n=\"234\">62</sup>, וא\"ו ומילוי וא\"ו<sup data-n=\"235\">63</sup>, ויוסף הוא המשביר<sup data-n=\"236\">64</sup> כו' היינו לבי\"ע, וא\"כ מה שיעקב מבריח מן קצה העליון עד קצה התחתון<sup data-n=\"237\">65</sup> עמ\"ש מענין הכרובי' כרוב א' מקצה מזה<sup data-n=\"238\">66</sup> כו' ע\"י יוסף נמשך בבי\"ע, וזה הי' קודם מ\"ת, ולאחר שניתנה תו' י\"ל שנמשך המשכה עצמית ע\"י משה כו', ועמ\"ש במ\"א מענין משה מלגאו יעקב מלבר<sup data-n=\"239\">67</sup> כו'.\n(ב) <b>אך</b> עדיין צ\"ל ע\"י מה יומשך גילוי בחי' זה בעולם כו' לזה הקדים בפסוק סוף דבר לומר את האלקי' ירא שהיא קבעומ\"ש, ואת מצותיו שמור שהוא קבעומ\"צ כמשי\"ת, דהנה המצות נק' בשם זריעה<sup data-n=\"240\">68</sup> וכמ\"ש אור זרוע<sup data-n=\"241\">69</sup> ועמ\"ש במד\"ר ס\"פ שלח זרע הקב\"ה<sup data-n=\"242\">70</sup> התורה והמצות ולא הניח דבר כו' בא כו'*, וכתי' ויזרע\n\n<i>אך עדיין צ\"ל . . בא כו': בבוך 1108 נרשם מהדו\"ק וז\"ל:</i>\nאך עדיין[ftnref_8165_ב] צ\"ל מה שביעקב נא' בריאה ובישראל נאמר יצירה, והלא בחי' ישראל גדול מבחי' יעקב כו', שהרי הוא מפני כי שרית[ftnref_8166_ג] כו', אך הענין הוא דהנה כדי שיהי' נמשך בחי' כי זה כל האדם הקדים בפסוק תחילה לומר את האלקי' ירא ואת מצותיו שמור ועי\"ז נמשך להיות כי זה כל האדם, דהיינו שע\"י מה ממשיכים בחי' זה הוא ע\"י מצותיו כו'. והנה על המצות נא' בזהר שהם בחי' לבושים[ftnref_8167_ד] שכ\"א מישראל צריך לקיים כל התרי\"ג מצות[ftnref_8168_ה] לבד מצות המלך שהמלך הוא מוציא כולם[ftnref_8169_ו] כו'. וכל המצות מחוייב כ\"א לקיים וצריך לבוא בגלגול או בבחי' עיבור בכדי שיהי' לכאו\"א לבוש מן כל התרי\"ג מצות לבד מצות המ' כנ\"ל, וכשחיסר מצוה אחת חסר לבוש כו', ובגמ' המשילו מעשה המצות לפירות גבי עגלה ערופה כו' ולא הניחוהו לעשות פירות ופריך בגמ' מאי פירות אילימא בנים א\"ה זקן וסריס לא ליבעי עגלה ערופה והתורה לא חילקה אלא מאי פירות מצות[ftnref_8165_ב]. כן כתי' אמרו לצדיק כי טוב כי פרי מעלליו יאכלו[ftnref_8170_ז].",[["233","61","<b>ית'</b>: כ\"ה בכ\"מ ומהם: סה\"מ תרכ\"ט ע' רט. תרל\"ח ע' מ. סה\"מ תר\"ם ח\"ב ע' תקכא. ובהנסמן בהנ\"ל. לקמן מאמר ד\"ה א\"ר אלעזר א\"ר חנינא ת\"ח מרבים שלום פ\"א. מאמר ד\"ה תקעו תרצ\"א על יד הערה 20. לקו\"ש דברים כרך יט ע' 27 ואילך."],["232","60","<b>שנתאוה הקב\"ה . . דירה בתחתונים</b>: ראה תניא רפל\"ו (ובהנסמן בליקוט פירושים לשם). ביאוה\"ז תזריע עב, ג. תו\"ח בא ח\"א קמז, סע\"ב ואילך. וש\"נ. פקודי ח\"ב תנב, ג. סה\"מ תרל\"ח ע' לט ואילך בהערות. סה\"מ תר\"ם ח\"א ע' רנ. וש\"נ. לקמן פ\"ב. לקמן מאמר ד\"ה א\"ר אלעזר א\"ר חנינא ת\"ח מרבים שלום פ\"א."],["234","62","<b>אלה תולדות יעקב יוסף</b>: וישב לז, ב. ראה ב\"ר פפ\"ד, ו. אוה\"ת וישב כרך ה ע' תתק ואילך. סה\"מ תרכ\"ט ע' שפו. תרכ\"ז ע' ריט. וש\"נ. לקמן מאמר ד\"ה וחג הקציר בכורי מעשיך על יד הערה 92."],["235","63","<b>וא\"ו ומילוי וא\"ו</b>: ראה לקו\"ת חוקת ס, ד. אוה\"ת בהעלותך ע' שפז. פ' ראה ע' תשעו. סה\"מ תרכ\"ט ע' כז. וש\"נ. ע' שפו."],["236","64","<b>ויוסף הוא המשביר</b>: מקץ מב, ו [בדילוג]."],["237","65","<b>שיעקב מבריח . . קצה התחתון</b>: ראה זהר בשלח נא, ב. תרומה קעה, ב. לקו\"ת שה\"ש יג, סע\"א ואילך. מאמרי אדה\"א שמות ח\"א ע' יט. וש\"נ. סה\"מ תרכ\"ט ע' קיז. וש\"נ. תרנ\"ג ע' רנח ואילך."],["238","66","<b>כרוב א' מקצה מזה</b>: תרומה כה, יט. ראה תו\"א תרומה פא, ב."],["239","67","<b>משה מלגאו יעקב מלבר</b>: ת\"ז תי\"ג כט, א. ראה לקו\"ת פינחס עח, ג ואילך."],["240","68","<b>המצות נק' בשם זריעה</b>: ראה תו\"א שמות נג, ג. סה\"מ תרל\"ח ע' תי ואילך. תר\"ם ח\"א ע' רסב. וש\"נ."],["241","69","<b>אור זרוע</b>: תהלים צז, יא."],["242","70","<b>במד\"ר ס\"פ שלח זרע הקב\"ה</b>: ראה במדב\"ר פי\"ז, ה. סה\"מ תר\"ם שם. וש\"נ.\n\n[ftn_8165_ב])<i>אך עדיין . . פירות מצות:</i> ע\"פ לשון תו\"א שמות נג, ג (בהשמטות ושינויים).\n\n[ftn_8166_ג])<i>כי שרית:</i> וישלח לב, כט.\n\n[ftn_8167_ד])<i>המצות . . בחי' לבושים:</i> ראה תניא פ\"ה. אגה\"ק סכ\"ט. תו\"א מקץ לב, ד. לקו\"ת שה\"ש טז, רע\"ג.\n\n[ftn_8168_ה])<i>לקיים כל התרי\"ג מצות:</i> ראה לקמן הערה 120.\n\n[ftn_8169_ו])<i>שהמלך הוא מוציא כולם:</i> ראה גם אגה\"ק סכ\"ט. תו\"א שמות כאן נג, ג. סה\"מ תרכ\"ז ע' שלד. תרכ\"ט ע' ד וע' רמח. תרס\"ח ריש ע' רלז. לקו\"ש קרח כרך יח ע' 192 הערה 55.\n\n[ftn_8165_ב])<i>אך עדיין . . פירות מצות:</i> ע\"פ לשון תו\"א שמות נג, ג (בהשמטות ושינויים).\n\n[ftn_8170_ז])<i>אמרו לצדיק כי טוב:</i> ישעי' ג, י [ ושם: צדיק . . מעלליהם — ראה גם לקמן מאמר ד\"ה והי' אור הלבנה ובהערה 8]."]]],[2001910091,"יצחק בארץ ההיא<sup data-n=\"243\">71</sup> ופי' ברבות אין זריעה אלא צדקה<sup data-n=\"244\">72</sup> וכמ\"ש זרעו לכם לצדקה<sup data-n=\"245\">73</sup>, נמצא מכ\"ז מובן<sup data-n=\"246\">*74</sup> שהמצות נק' בשם פירות<sup data-n=\"247\">74</sup>, ולהבין זאת<sup data-n=\"248\">75</sup> הנה ארז\"ל נתאוה הקב\"ה להיות לו דירה בתחתונים, והנה לכאו' אינו מובן ענין דירה זו דהלא לית אתר פנוי מיני'<sup data-n=\"249\">76</sup>, וכתי' הלא את השמים ואת הארץ אני מלא<sup data-n=\"250\">77</sup>, וגם איתא ברבות ע\"פ וירא אליו ה' בלבת אש<sup data-n=\"252\">79</sup> מתוך הסנה ללמד שאין מקום פנוי<sup data-n=\"251\">78</sup> מן השכינה אפי' סנה, אך הענין הוא דהנה יעקב א' אכן יש ה' במקום הזה<sup data-n=\"253\">80</sup> ואנכי לא ידעתי, והנה",[["243","71","<b>ויזרע יצחק בארץ ההיא</b>: תולדות כו, יב."],["244","72","<b>ופי' ברבות אין זריעה אלא צדקה</b>: וכ\"ה בבוך בש\"ו 1063 כאן ע' קפב. ראה תד\"א זוטא פ\"א."],["245","73","<b>זרעו לכם לצדקה</b>: הושע י, יב."],["246","*74","<b>מובן</b>: תיבה זו ניתוספה בכת\"י המעתיק (ע\"י המעתיק)."],["247","74","<b>שהמצות נק' בשם פירות</b>: ראה סוטה מו, ע\"א. סה\"מ תרס\"ג כאן ע' קיח."],["248","75","<b>ולהבין זאת . . אני מלא</b>: לשון התו\"א שבהערה 68."],["249","76","<b>לית אתר פנוי מיני'</b>: ראה לקמן מאמר ד\"ה במשנה וכו' ר' נהוראי אומר הערה 21."],["250","77","<b>הלא את השמים . . אני מלא</b>: ירמי' כג, כד."],["252","79","<b>וירא אליו ה' בלבת אש</b>: שמות ג, ב [ושם: מלאך ה' אליו — וכ\"ה בבוך בש\"ו הנ\"ל]."],["251","78","<b>ברבות . . ללמד שאין מקום פנוי</b>: שמו\"ר פ\"ב, ה.\nבשמו\"ר שם: ”ללמדך\" וכ\"ה בלקו\"ת בהר מא, א. אוה\"ת שמות ע' סו. סה\"מ עזרת כאן ריש ע' קכו. (לקמן בחלק ההנחות) הנחה ד\"ה תקעו בחודש שופר על יד הערה 24. אבל הלשון שבפנים הובא גם בלקו\"ת ויקרא בהוספות נב, ג. בוך בש\"ו שבהערה 72. (לקמן בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב] בהנחה כאן על יד הערה 75.\nבבוך בש\"ו 1063: הסנה למה מתוך הסנה ללמד. ובבוך 1108 בכת\"י המעתיק העתיק מבוך בש\"ו כבפנים. ואולי נשמט מפני תיבות הדומות: הסנה . . הסנה."],["253","80","<b>אכן יש ה' במקום הזה</b>: ויצא כח, טז. ראה גם לקמן מאמר ד\"ה רני ושמחי פ\"ג. (לקמן בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב] הנחה ד\"ה תקעו בחדש שופר פיסקא והענין. ובחלק ההנחות שם פיסקא ויש להבין. המשך תער\"ב ח\"ב ע' תתקכט ואילך."]]],[2001910092,"ענין אומרו המקום<sup data-n=\"254\">81</sup> הזה קאי על בהמ\"ק כמ\"ש הת\"א לית דין אתר הדיוט<sup data-n=\"255\">82</sup>, פי' שאינו רק כמו כל בחי' מציאות מקום שנברא מע\"מ שנק' בשם מילין דהדיוטא<sup data-n=\"256\">83</sup>, כ\"א שמקום זה שהי' מקום שנבנה אח\"כ הבהמ\"ק, והיינו שבבהמ\"ק הי' גילוי השכינה וכמ\"ש וכבוד הוי' מלא את המשכן<sup data-n=\"257\">84</sup>, ובמקדש היו קורין את השם ככתבו<sup data-n=\"258\">85</sup>, ולכאו' ג\"ז אינו מובן<sup data-n=\"259\">86</sup> שהרי מכה\"כ<sup data-n=\"260\">87</sup> ולית אתר פנוי מיני', אך הענין הוא דמה שמכה\"כ היינו שהוא רק בחי' המתלבשת בנבראים להחיותם ואתה מחי' את כולם<sup data-n=\"261\">88</sup> ע\"י בחי' אתה ך\"ב אותיות, אבל אינו מאיר אלקו' בעולם בבחי' גילוי ואף שנא' את השמים ואת הארץ אני מלא הוא רק בהעלם, משא\"כ בבהמ\"ק הי' גילוי השכינה וכמשארז\"ל צמצם שכינתו<sup data-n=\"262\">89</sup> בין ב' בדי הארון והיינו שהי' מאיר שם בגילוי כו', וזהו ע\"ד שארז\"ל מה הנשמה ממלא את הגוף<sup data-n=\"263\">90</sup> כך הקב\"ה ממלא את כל העולם, והנה אנו רואים בחיות הנפש שמאיר בגוף שאם היות שהחיות מתלבש בכל אברי הגוף ואפי' בצפורני הרגל, וכ\"ש ברגל עצמו, ואעפ\"כ הנה נודע ונראה שעיקר השראת הנפש הוא במוח שבראש<sup data-n=\"264\">91</sup>, והיינו ששם נמשך בחי' גילוי הנפש ועד\"ז הי' בבהמ\"ק גילוי השכינה כו', היינו ע\"ד שמאיר חיות הנפש במוח שבראש ששם מאיר בבחי' גילוי כו', וממוצא דבר נשמע שאף שבבהמ\"ק הי' גילוי שכינה מ\"מ אינו נק' עדיין דירה בתחתוני', לפי שמה שהי' מאיר בבהמ\"ק בחי' גילוי זהו רק מבחי' ממכ\"ע וע\"ד כמו הנשמה שמאירה בגוף שמאירה במוח בבחי' גילוי זהו רק מבחי' הנשמה שמתלבשת בגוף שבשאר אברים היא מאירה בבחי' העלם ובמוח שבראש היא מאירה בגילוי כו', אבל בחי' מקיף שבנשמה אינה מאירה אפי' במוח שבראש, וכך מה שהי' השראת השכינה בבהמ\"ק זהו מבחי' ממכ\"ע, אבל בחי' סוכ\"ע<sup data-n=\"266\">*92</sup> לא הי' מאיר<sup data-n=\"265\">92</sup> עדיין כו', שלכן במדינה היו קורין את השם בכינויו<sup data-n=\"267\">93</sup>, ונתאוה הקב\"ה להיות לו",[["254","81","<b>המקום</b>: כ\"ה בגוכתי\"ק."],["255","82","<b>הת\"א לית דין אתר הדיוט</b>: לויצא כח, יז. ראה אוה\"ת בא כרך ז ע' ב'תרכד."],["256","83","<b>מע\"מ שנק' בשם מילין דהדיוטא</b>: ראה זהר בהעלותך קמט, ב. סידור שער התפלה יח, סע\"ד. לקו\"ת אחרי כה, ד. אוה\"ת בא שם. לקמן מאמר ד\"ה והנה תורה היא בחי' קו האמצעי על יד הערה 170 ואילך. (לקמן בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב] הנחה ד\"ה תקעו בחדש שופר פיסקא והענין. סה\"מ תרכ\"ז ס\"ע רטו ואילך. תרל\"א ח\"א ע' ד."],["257","84","<b>וכבוד הוי' מלא את המשכן</b>: פקודי מ, לד-לה."],["258","85","<b>ובמקדש . . השם ככתבו</b>: תמיד פ\"ז, מ\"ב. ראה גם לקמן מאמר ד\"ה ראה קראתי בשם ספ\"ד."],["259","86","<b>ג\"ז אינו מובן</b>: ראה תניא פנ\"א. לקו\"ת אמור לד, ב."],["260","87","<b>מכה\"כ</b>: ישעי' ו, ג."],["261","88","<b>ואתה מחי' את כולם</b>: נחמי' ט, ו. ראה שער היחוד והאמונה פ\"ב."],["262","89","<b>צמצם שכינתו</b>: ראה ב\"ר פ\"ד, ד. מאמרי אדה\"ז תקס\"ג ח\"א ס\"ע שמו ואילך (נו\"א). לקו\"ת אמור לד, ב. הנסמן במאמרי אדה\"א בראשית ע' קכט. שה\"א ז, א ובהערה 12."],["263","90","<b>מה הנשמה ממלא את הגוף</b>: ראה ברכות י, א. מאמרי אדה\"א הנחות תקע\"ז ע' לה. וש\"נ."],["264","91","<b>שעיקר . . במוח שבראש</b>: ראה רבינו יונה לברכות יד, סע\"ב ד\"ה הרוצה. שו\"ע הל' תפילין סכ\"ה, ס\"ה. ובשו\"ע אדה\"ז שם סי\"א. תניא פנ\"א ואילך. מאמרי אדה\"א דברים ח\"ג ע' תתסו. וש\"נ. שמות ח\"ב ע' תקמג ואילך. ש\"א י, ב הערה 31."],["266","*92","<b>ממכ\"ע . . סוכ\"ע</b>: זהר רע\"מ פינחס רכה, א."],["265","92","<b>בבהמ\"ק . . ממכ\"ע . . סוכ\"ע לא הי' מאיר</b>: ראה סה\"מ תרמ\"ד ע' רכב."],["267","93","<b>במדינה . . בכינויו</b>: תמיד פ\"ז, מ\"ב."]]],[2001910093,"דירה בתחתוני' היינו שיהי' גילוי בחי' הסוכ\"ע, ולכך כשיהי' נמשך בגילוי בחי' סוכ\"ע יהי' הגילוי באופן אחר ממש, שיהי' מאיר בכל העולם בשוה, שהרי בחי' סוכ\"ע אין בו חילוקי מדרגות כו'.\n(ג) <b>והנה</b> כדי להמשיך בחי' דירה בתחתונים זהו ע\"י הברכות שארז\"ל חייב אדם לברך<sup data-n=\"268\">94</sup> מאה ברכות בכ\"י, דלכאו' אינו מובן מהו ענין הברכה שאנו מברכים להקב\"ה כי מה צריך לברכה שלנו, והלא אנת הוא שלימותא דכולהו<sup data-n=\"269\">95</sup> כו', אך הנה פי' הברכה הוא בחי' המשכה מהעלם לגילוי<sup data-n=\"270\">96</sup> כי ברוך הוא ל' בריכה<sup data-n=\"271\">97</sup> המבריך את הגפן<sup data-n=\"272\">98</sup> שהוא בחי' המשכה כו', והיינו שע\"י הברכה נמשך מהעלם אל הגילוי, ולזה חייב לברך מאה ברכות, והיינו לפי שיש יחידות עשירות מאות, שהוא כנגד ג' עולמות בי\"ע<sup data-n=\"273\">99</sup>, ולכן כדי שיומשך למטה בעולם העשי' צריך לברך מאה ברכות לפי שכשיש מאה אזי נמשך למטה לפחות א' לפי שכשנמשך מאה בבריאה נמשך מזה חלק העשירי<sup data-n=\"274\">100</sup> ביצי' שהוא עשרה וממילא נמשך בחי' האצי' בעשי' בחי' א' עכ\"פ, אבל כשחסר ממאה ברכות אזי לא יומשך למטה בעשי' אפי' אחד כו'. אך הברכה הוא דוקא ע\"י ישראל, וכמ\"ש בית ישראל ברכו את הוי'<sup data-n=\"275\">101</sup> והיינו לפי שיש בכאו\"א מישראל בכח למסור נפשו באחד<sup data-n=\"276\">102</sup> ויש להם בחי' ביטול וכמ\"ש ועתה ישראל מה הוי' אלקיך שואל מעמך<sup data-n=\"277\">103</sup> ומזה דוקא למד ר' מאיר<sup data-n=\"278\">104</sup> א\"ת מה אלא מאה<sup data-n=\"279\">105</sup> כו', והיינו לפי שע\"י בחי' מה שיש להם היינו בחי' הביטול כו' עי\"ז יכולים לברך מאה ברכות, והנה ההפרש שבין מה למאה הוא שבמאה ניתוסף א', והענין הוא דהנה בריאת העולמות מתחיל בבי\"ת וך\"ו דורות קרא האלף תגר<sup data-n=\"280\">106</sup> עד שבמ\"ת פתח בא' תחלה אנכי<sup data-n=\"281\">107</sup> כו', והטעם איתא בזהר שלכך לא פתח ברה\"ע בא' לפי",[["268","94","<b>חייב אדם לברך</b>: מנחות מג, ב."],["269","95","<b>אנת הוא שלימותא דכולהו</b>: ראה ת\"ז בהקדמה יז, ב."],["270","96","<b>הברכה . . המשכה מהעלם לגילוי</b>: ראה גם זח\"ג רע\"מ עקב ער, סע\"ב. תו\"א מקץ לז, ג. לקו\"ת ואתחנן ב, א. ביאוה\"ז עקב קיט, ד. תו\"ח בשלח ח\"א קס, ג. וש\"נ. סה\"מ תר\"ם ח\"א ע' רלח. וש\"נ."],["271","97","<b>ברוך הוא לשון בריכה</b>: ראה שערי אורה [לר\"י גיקטלייא] שער א (ה, א). לקו\"ת תזריע כב, ג. פ' ראה כט, א. מאמרי אדה\"א הנחות תקע\"ז ע' רסב. וש\"נ. סה\"מ תרל\"ח ע' צז. וש\"נ. לקמן מאמר ד\"ה בגמ' וכו' קא מפלגי רפ\"ב."],["272","98","<b>המבריך את הגפן</b>: כלאים פ\"ז, מ\"א. ראה גם תו\"א מקץ לז, ג. סה\"מ תר\"ם ח\"א ע' רלח. וש\"נ."],["273","99","<b>יחידות עשירות מאות . . בי\"ע</b>: ראה לקו\"ת בלק עד, ב."],["274","100","<b>נמשך מזה חלק העשירי</b>: ראה גם שערי אורה שם ה, ב ואילך. שפע טל בהקדמה יד, א ואילך. שם ש\"א, פ\"ה. לעיל מאמר ד\"ה הקבצו ושמעו בנ\"י ובהערה 38."],["275","101","<b>בית ישראל ברכו את הוי'</b>: תהלים קלה, יט."],["276","102","<b>למסור נפשו באחד</b>: ראה זהר רע\"מ משפטים קיט, א. צו לג, א. מאמרי אדה\"א דברים ח\"ב ע' תו. וש\"נ. שמות ח\"א ע' רעח ואילך. הנחות תקע\"ז ע' שא."],["277","103","<b>ועתה ישראל . . מעמך</b>: עקב י, יב."],["278","104","<b>ר' מאיר</b>: ראה סה\"מ תרל\"ח ע' ריג."],["279","105","<b>א\"ת מה אלא מאה</b>: ראה שו\"ע אדה\"ז הל' ברכות השחר רסמ\"ו. הנסמן במאמרי אדה\"א דברים ח\"א ע' קכז."],["280","106","<b>וך\"ו דורות קרא האלף תגר</b>: ראה ב\"ר פ\"א, י. תנחומא — באבער — יתרו טז. וש\"נ. בסה\"מ עזר\"ת כאן ע' קכז: ”וט\"ו\" דורות. ונשצ\"ל כבפנים."],["281","107","<b>אנכי</b>: יתרו כ, ב."]]]]});
